// TURNOS_CHEGADA agora é a MESMA referência de EMPRESA_CONFIG.turnosChegada.
// Assim, todo uso existente continua funcionando e passa a refletir o config
// (inclusive quando atualizado pelo Firebase via aplicarEmpresaConfig).
const TURNOS_CHEGADA = EMPRESA_CONFIG.turnosChegada;

// ==================================================================
// CALENDÁRIO DOS TURNOS
// ------------------------------------------------------------------
// Um turno deixa de ser um horário e passa a ser uma regra por dia.
// Quem quiser saber o horário de um dia pergunta a turnoNoDia().
// ==================================================================

const DIAS_SEMANA = ['dom', 'seg', 'ter', 'qua', 'qui', 'sex', 'sab'];
const DIAS_NOME = { dom: 'Domingo', seg: 'Segunda', ter: 'Terça', qua: 'Quarta',
                    qui: 'Quinta', sex: 'Sexta', sab: 'Sábado' };

let TURNOS = [];

// new Date('2026-08-22') é interpretado em UTC e no Brasil volta um dia.
// Este é o erro clássico de calendário: a rota de sábado aparecendo na sexta.
function turnoData(iso) {
  if (iso instanceof Date) return iso;
  const m = String(iso || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return null;
  return new Date(+m[1], +m[2] - 1, +m[3]);   // meia-noite local
}

function turnoDiaChave(iso) {
  const d = turnoData(iso);
  return d ? DIAS_SEMANA[d.getDay()] : null;
}

// Semanas inteiras entre duas datas, contando por dia e não por milissegundo:
// horário de verão faz um dia ter 23 ou 25 horas.
function turnoSemanasEntre(isoA, isoB) {
  const a = turnoData(isoA), b = turnoData(isoB);
  if (!a || !b) return null;
  const dias = Math.round((b - a) / 86400000);
  return Math.floor(dias / 7);
}

// Migra o mapa antigo sem mudar nada: o horário de hoje vira o padrão e
// todos os dias operam.
function turnosSemear() {
  if (TURNOS.length) return TURNOS;
  Object.keys(TURNOS_CHEGADA || {}).forEach(nome => {
    TURNOS.push({
      id: 'tn-' + nome.replace(/[^A-Za-z0-9]/g, '') || ('tn' + TURNOS.length),
      nome: nome,
      chegada: TURNOS_CHEGADA[nome] || '',
      saida: '',
      dias: {},          // vazio = todos os dias usam o padrão
      alternado: null    // { dia:'sab', semanas:2, desde:'YYYY-MM-DD' }
    });
  });
  return TURNOS;
}

function turnoPorNome(nome) {
  turnosSemear();
  return TURNOS.find(t => t.nome === nome) || null;
}

// A porta única. Devolve sempre um objeto — nunca null — para nenhum
// chamador precisar tratar ausência.
function turnoNoDia(nome, dataIso) {
  const t = turnoPorNome(nome);
  if (!t) {
    // turno fora do cadastro: cai no mapa antigo, como sempre foi
    const h = (TURNOS_CHEGADA || {})[nome] || '';
    return { opera: true, chegada: h, saida: '', origem: 'legado', nome: nome };
  }
  const chave = turnoDiaChave(dataIso);
  const regra = chave ? t.dias[chave] : undefined;

  // dia explicitamente desligado
  if (regra === false) {
    return { opera: false, chegada: '', saida: '', origem: 'dia-desligado',
             nome: nome, motivo: (DIAS_NOME[chave] || 'Este dia') + ' não opera neste turno.' };
  }

  // alternância: só vale para o dia configurado
  if (t.alternado && chave === t.alternado.dia) {
    const n = turnoSemanasEntre(t.alternado.desde, dataIso);
    const passo = Math.max(1, parseInt(t.alternado.semanas, 10) || 2);
    if (n === null) {
      return { opera: true, chegada: (regra && regra.chegada) || t.chegada,
               saida: (regra && regra.saida) || t.saida, origem: 'alternado-sem-referencia', nome: nome };
    }
    if (n < 0 || (n % passo) !== 0) {
      return { opera: false, chegada: '', saida: '', origem: 'alternado',
               nome: nome,
               motivo: (DIAS_NOME[chave] || 'Este dia') + ' alternado: não é a vez deste turno.' };
    }
  }

  const usa = (regra && typeof regra === 'object') ? regra : {};
  return {
    opera: true,
    chegada: usa.chegada || t.chegada || '',
    saida: usa.saida || t.saida || '',
    origem: (usa.chegada || usa.saida) ? 'excecao-do-dia' : 'padrao',
    nome: nome, dia: chave
  };
}

// Quais turnos operam num dia. Serve para a tela de criar rota e, adiante,
// para o app do motorista dizer "sem rota hoje" em vez de mostrar a de ontem.
function turnosDoDia(dataIso) {
  turnosSemear();
  return TURNOS.map(t => Object.assign({ turno: t }, turnoNoDia(t.nome, dataIso)))
               .filter(r => r.opera);
}

// Compatibilidade: quem só quer a chegada de hoje continua funcionando.
function turnoChegada(nome, dataIso) {
  const r = turnoNoDia(nome, dataIso || hojeLocal());
  return r.opera ? r.chegada : '';
}
function turnoSaida(nome, dataIso) {
  const r = turnoNoDia(nome, dataIso || hojeLocal());
  return r.opera ? r.saida : '';
}


// Mescla a configuração vinda do Firebase (doc 'config') sobre os padrões,
// sem perder nada que não tenha sido configurado. Chamado em loadData().
function aplicarEmpresaConfig(cfgFirebase) {
  try { if (typeof tvAplicarContextoConta === 'function') setTimeout(tvAplicarContextoConta, 0); } catch(e) {}
  try { const _n = (cfgFirebase && cfgFirebase.nome) || C.empresaNome || C.marca;
        if (_n) document.title = _n + ' \u2014 Portal temvia \u2014 Gest\u00e3o'; } catch(e) {}
  // Frota da operacao (item 16). Vem antes do "return" de empresa porque a
  // frota e independente dos dados de empresa.
  try {
    if (Array.isArray(cfgFirebase.veiculos)) {
      FROTA = cfgFirebase.veiculos;
      if (typeof renderSidebar === 'function' && DATA.length) renderSidebar();
    }
  } catch (err) { console.warn('frota config:', err); }
  // Nome da operacao atendida. Mora em config.empresa.operacaoNome, junto do
  // nome da transportadora. A leitura do nivel antigo (config.operacaoNome)
  // fica como resgate: quem gravou antes da correcao nao perde o valor.
  try {
    if (cfgFirebase) {
      const _v = (cfgFirebase.empresa && cfgFirebase.empresa.operacaoNome !== undefined)
        ? cfgFirebase.empresa.operacaoNome
        : cfgFirebase.operacaoNome;
      if (_v !== undefined) EMPRESA_CONFIG.operacaoNome = _v || '';
      const _op = document.getElementById('cfgOperacaoNome');
      if (_op) _op.value = EMPRESA_CONFIG.operacaoNome || '';
      if (typeof tvAplicarContextoConta === 'function') tvAplicarContextoConta();
    }
  } catch (e) { console.warn('operacaoNome config:', e); }

  // Turnos (calendário). Sem cadastro, os turnos atuais são migrados.
  try {
    if (cfgFirebase && Array.isArray(cfgFirebase.turnos) && cfgFirebase.turnos.length) {
      TURNOS = cfgFirebase.turnos;
    }
    turnosSemear();
  } catch (e) { console.warn('turnos config:', e); }

  // Pontos de origem e destino
  try {
    if (cfgFirebase && Array.isArray(cfgFirebase.pontos) && cfgFirebase.pontos.length) {
      PONTOS = cfgFirebase.pontos;
      ptAplicarNoSistema();
    }
  } catch (e) { console.warn('pontos config:', e); }

  // Regras do otimizador (config.otimizacao): centralizadas, com defaults.
  try { if (cfgFirebase) optAplicarConfig(cfgFirebase.otimizacao); }
  catch (e) { console.warn('config de otimizacao:', e); }
  if (!cfgFirebase) return;
  // API Key do Google Maps: o servidor (Firestore) é a fonte da verdade.
  // Aplica a chave salva na nuvem mesmo que ainda não exista config de empresa,
  // e replica no localStorage para acelerar os próximos carregamentos neste navegador.
  try {
    // RESERVA: so vale se a casca ainda nao trouxer a chave.
    if (!chaveDaCasca() && cfgFirebase.mapsApiKey && typeof cfgFirebase.mapsApiKey === 'string') {
      console.warn('[temvia] Chave do Maps veio do Firestore. ' +
                   'Publique mapsKey na casca desta operacao.');
      MAPS_API_KEY = cfgFirebase.mapsApiKey;
      try { localStorage.setItem('redentor_maps_key', cfgFirebase.mapsApiKey); } catch(_) {}
    }
  } catch(err) { console.warn('mapsApiKey config:', err); }
  if (!cfgFirebase.empresa) return; // sem config de empresa: mantém padrões (chave já aplicada acima)
  const e = cfgFirebase.empresa;
  const numCoords = (obj) => { // garante lat/lng numéricos
    if (obj && obj.lat != null) obj.lat = parseFloat(obj.lat);
    if (obj && obj.lng != null) obj.lng = parseFloat(obj.lng);
    return obj;
  };
  try {
    if (e.nome) EMPRESA_CONFIG.nome = e.nome;
    if (e.whatsCliente !== undefined) EMPRESA_CONFIG.whatsCliente = e.whatsCliente;
    if (e.whatsRedentor !== undefined) EMPRESA_CONFIG.whatsRedentor = e.whatsRedentor;
    if (e.turnosChegada) Object.assign(EMPRESA_CONFIG.turnosChegada, e.turnosChegada);
    if (e.garagem) Object.assign(EMPRESA_CONFIG.garagem, numCoords(e.garagem));
    if (e.destino) Object.assign(EMPRESA_CONFIG.destino, numCoords(e.destino));
    if (e.destinoAlt) Object.assign(EMPRESA_CONFIG.destinoAlt, numCoords(e.destinoAlt));
  } catch(err) { console.warn('aplicarEmpresaConfig:', err); }
}

const VERTIV_DESTINO = 'Estr. dos Carvalhos, 1441 — Cajuru do Sul, Sorocaba-SP';
const VERTIV_LAT = -23.386451104226673;
const VERTIV_LNG = -47.38984559023686;
const VERTIV_LABEL = 'Vertiv';
const GARAGEM_LABEL = 'Garagem Redentor (início da rota)';

const LINE_COLORS = ['lc1','lc2','lc3','lc4','lc5','lc6','lc7'];

// ---- DATA ----
const DATA_VERSION = C.dataVersion;
let DATA = [];

let DESLIGADOS = []; // passageiros removidos das linhas
let ROTAS_EXTRAS = []; // rotas extras temporárias
let SEM_ROTA = []; // passageiros aguardando alocação de rota
let activeId = null;
let turnoFilter = 'todos';
let editingPassIdx = null;

function lc(n) {
  if (typeof n === 'string' && n.startsWith('VERTIV')) return 'lc-vertiv';
  return LINE_COLORS[(n-1) % 7];
}

// ==================== COR DA LINHA (item 15) ====================
// As linhas 1 a 7 nasceram com cor fixa no codigo. Linhas criadas pelo
// "Gerenciar Linhas" ficavam sem cor (brancas no mapa). Agora a cor e um
// campo da propria linha: rota.cor. Quem nao tem cor definida continua
// caindo na cor antiga, entao nada muda para as linhas ja existentes.
const CORES_LINHA = [
  '#F59E0B', '#3B82F6', '#10B981', '#EF4444', '#8B5CF6', '#EC4899', '#14B8A6',
  '#F97316', '#06B6D4', '#84CC16', '#A855F7', '#F43F5E', '#0EA5E9', '#EAB308'
];

// Cor efetiva de uma linha (aceita o numero da linha ou a propria rota).
function corLinha(linhaOuRota) {
  const rota = (linhaOuRota && typeof linhaOuRota === 'object')
    ? linhaOuRota
    : DATA.find(r => String(r.linha) === String(linhaOuRota));
  if (rota && rota.cor) return rota.cor;
  const linha = rota ? rota.linha : linhaOuRota;
  if (typeof linha === 'string' && linha.startsWith('VERTIV')) return '#DC2626';
  const i = parseInt(linha, 10);
  return CORES_LINHA[isNaN(i) ? 0 : (i - 1) % 7];
}

// Estilo pronto para o quadradinho da linha, quando ha cor propria.
function estiloBadgeLinha(linhaOuRota) {
  const rota = (linhaOuRota && typeof linhaOuRota === 'object')
    ? linhaOuRota
    : DATA.find(r => String(r.linha) === String(linhaOuRota));
  if (!rota || !rota.cor) return '';
  // A Fase 1 neutralizou a cor decorativa do rail com !important, porque ali a
  // cor nao queria dizer nada. Agora quer: foi o gestor que escolheu. Por isso
  // o inline tambem vai com !important — cor escolhida vence cor neutralizada.
  return ' style="background:' + rota.cor + '22 !important;color:' + rota.cor + ' !important"';
}

// ---- Fechar o Roteirizador sem perder trabalho (item 10) ----
// So pergunta se ha mesmo algo a perder: passageiros carregados ou veiculos
// montados. Com a tela vazia, fecha direto — perguntar a toa cansa.
function rtTemTrabalho() {
  try {
    if (!RT_DAY) return false;
    if (RT_DAY.pool && RT_DAY.pool.length) return true;
    return !!(RT_DAY.vehicles && RT_DAY.vehicles.some(v => v.pax && v.pax.length));
  } catch (e) { return false; }
}

function rtFechar() {
  if (rtTemTrabalhoNaoPublicado() &&
      !confirm('Deseja mesmo sair? Os dados não salvos serão perdidos.\n\n' +
               'As rotas que você já publicou continuam salvas.')) return;
  document.getElementById('modalRoteirizador').classList.remove('open');
  // Zera na saída também: se algo novo for acrescentado ao modal amanhã e
  // esquecido no reset de abertura, a tela ainda nasce limpa.
  rtZerarTudo();
}

// ==================== FASE 1 — HELPERS DO APP SHELL ====================
// Apenas apresentacao: recolher menu, menu do usuario e identidade de conta.
// Nenhuma regra de negocio, permissao ou handler existente e alterado aqui.

function tvToggleSidebar() {
  var sh = document.getElementById('tvShell');
  if (!sh) return;
  var recolhido = sh.classList.toggle('tv-collapsed');
  // a seta aponta para onde o clique leva: < recolhe, > mostra de novo
  var seta = document.getElementById('tvSetaRecolher');
  var btn = document.getElementById('tvBtnRecolher');
  if (seta) seta.innerHTML = recolhido ? "<path d='M10 6l6 6-6 6'/>" : "<path d='M14 6l-6 6 6 6'/>";
  if (btn) btn.title = recolhido ? 'Mostrar menu' : 'Recolher menu';
}

function tvToggleUser() {
  var m = document.getElementById('tvUserMenu');
  if (m) m.classList.toggle('tv-open');
}

// "Linhas e Rotas" ja e a tela aberta: fecha overlays e volta para ela.
function tvIrParaLinhas() {
  document.querySelectorAll('.modal-overlay.open').forEach(function (m) { m.classList.remove('open'); });
  var mv = document.getElementById('motoView');
  if (mv) mv.classList.remove('open');
}

// Hierarquia de marca: temvia e sempre o produto; a transportadora e contexto.
// O nome vem do cadastro da operacao (casca/config) — nada hardcoded.
// ---------------- Seletor de cliente ----------------
// A lista vem da casca: é ela que sabe quem são seus vizinhos. O engine é o
// mesmo para todos, então ele não tem como adivinhar.
function tvOperacoesIrmas() {
  const lista = Array.isArray(C.operacoes) ? C.operacoes.slice() : [];
  // sem cadastro na casca, ao menos a operação atual aparece
  if (!lista.some(o => o.id === C.clienteId)) {
    lista.unshift({ id: C.clienteId, nome: C.empresaNome || C.marca, path: C.pathPrefix });
  }
  return lista;
}

function tvRenderMenuCliente() {
  const box = document.getElementById('tvUserMenu');
  if (!box) return;
  const ops = tvOperacoesIrmas();
  let h = '';
  if (ops.length > 1) {
    h += '<div class="tv-menu-tit">Trocar de cliente</div>';
    ops.forEach(o => {
      const atual = o.id === C.clienteId;
      h += '<button type="button"' + (atual ? ' class="on" disabled' : '') +
        ' onclick="tvTrocarCliente(\'' + o.id + '\')">' +
        '<span class="tv-menu-bola"' + (o.cor ? ' style="background:' + o.cor + '"' : '') + '></span>' +
        esc(o.nome) + (atual ? '<small>aqui</small>' : '') + '</button>';
    });
    h += '<div class="tv-menu-sep"></div>';
  }
  h += '<button type="button" onclick="logout()">' +
    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" ' +
    'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
    '<path d=\'M15 17l5-5-5-5M20 12H9M11 20H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h5\'/></svg>Sair</button>';
  box.innerHTML = h;
}

// Trocar de cliente é recarregar na casca do outro. Dentro do mesmo projeto
// Firebase a sessão continua valendo, então não pede login de novo.
function tvTrocarCliente(id) {
  const o = tvOperacoesIrmas().find(x => x.id === id);
  if (!o || o.id === C.clienteId) return;
  if (typeof temAlteracaoPendente === 'function' && temAlteracaoPendente() &&
      !confirm('Há alterações não salvas. Trocar para ' + o.nome + ' mesmo assim?')) return;
  try { localStorage.setItem('temvia_ultima_operacao', o.id); } catch (e) {}
  window.location.href = o.path + 'index.html';
}

function tvAplicarContextoConta() {
  var nome = (typeof EMPRESA_CONFIG !== 'undefined' && EMPRESA_CONFIG && EMPRESA_CONFIG.nome)
    ? EMPRESA_CONFIG.nome : (C.empresaNome || C.marca || '');
  var el = document.getElementById('tvContextoConta');
  if (el) {
    el.textContent = nome || '\u00A0';
    el.title = nome || '';
  }
  // Quem está sendo atendido. Sem cadastro, cai no nome da pasta da operação
  // (DSV, Evamo) — assim a linha nunca fica vazia nem inventa informação.
  // O rodapé dizia "Gestor / Administrador" — não muda e não ajuda. Passa a
  // dizer qual cliente está aberto, que é a dúvida real de quem atende vários.
  var elNome = document.getElementById('tvUserNome');
  var elPapel = document.getElementById('tvUserPapel');
  var opAtual = tvOperacoesIrmas().find(function (o) { return o.id === C.clienteId; });
  if (elNome) elNome.textContent = (opAtual && opAtual.nome) || C.empresaNome || C.marca || '—';
  if (elPapel) elPapel.textContent = nome || 'Gestor';
  var elAv = document.getElementById('tvAvatar');
  if (elAv) elAv.textContent = ((opAtual && opAtual.nome) || C.marca || '--')
    .replace(/[^A-Za-zÀ-ÿ ]/g, '').trim().slice(0, 2).toUpperCase();
  tvRenderMenuCliente();

  var elOp = document.getElementById('tvOperacaoAtendida');
  if (elOp) {
    var op = (typeof EMPRESA_CONFIG !== 'undefined' && EMPRESA_CONFIG && EMPRESA_CONFIG.operacaoNome)
      ? String(EMPRESA_CONFIG.operacaoNome).trim() : '';
    if (!op) op = (C.pathPrefix || '').split('/').filter(Boolean).pop().toUpperCase();
    elOp.textContent = op ? 'Atendendo ' + op : '';
    elOp.style.display = op ? '' : 'none';
    elOp.title = op ? 'Empresa atendida por esta operação' : '';
  }
}

function tvAplicarUsuario(email) {
  var nome = (email || '').split('@')[0].replace(/[._-]+/g, ' ').trim();
  if (nome) nome = nome.replace(/\b\w/g, function (c) { return c.toUpperCase(); });
  var elN = document.getElementById('tvUserNome');
  var elA = document.getElementById('tvAvatar');
  if (elN) { elN.textContent = nome || 'Gestor'; elN.title = email || ''; }
  if (elA) {
    var p = (nome || 'Gestor').split(' ').filter(Boolean);
    elA.textContent = ((p[0] || '')[0] || '') + ((p[1] || '')[0] || '');
  }
}

// Fecha menus flutuantes ao clicar fora.
document.addEventListener('click', function (ev) {
  if (!ev.target.closest || !ev.target.closest('.tv-side-foot')) {
    var m = document.getElementById('tvUserMenu');
    if (m) m.classList.remove('tv-open');
  }
  if (!ev.target.closest || !ev.target.closest('.tv-menu-wrap')) {
    document.querySelectorAll('.tv-menu.tv-open').forEach(function (x) { x.classList.remove('tv-open'); });
  }
});

function tvToggleMenu(id, ev) {
  if (ev) ev.stopPropagation();
  var m = document.getElementById(id);
  if (!m) return;
  var abrindo = !m.classList.contains('tv-open');
  document.querySelectorAll('.tv-menu.tv-open').forEach(function (x) { x.classList.remove('tv-open'); });
  if (abrindo) m.classList.add('tv-open');
}

// Iniciais para o avatar do motorista no resumo da linha.
function tvIniciais(nome) {
  var p = String(nome || '').trim().split(/\s+/).filter(Boolean);
  if (!p.length) return '--';
  return ((p[0][0] || '') + (p.length > 1 ? (p[p.length - 1][0] || '') : '')).toUpperCase();
}

// ---- SIDEBAR ----
function updateStats() {
  const ativos = DATA.reduce((s, r) => s + r.passageiros.filter(p => p.status === 'ativo').length, 0);
  const nLinhas = new Set(DATA.map(r => String(r.linha).replace(/ \d+$/, ''))).size;
  const nRotas  = DATA.length;
  const elF = document.getElementById('stat-func');  if (elF) elF.textContent = ativos;
  const elL = document.getElementById('stat-lines'); if (elL) elL.textContent = new Set(DATA.map(r => String(r.linha))).size;
  const elT = document.getElementById('stat-turnos'); if (elT) elT.textContent = new Set(DATA.map(r => r.turno).filter(Boolean)).size;
  const elR = document.getElementById('stat-rotas'); if (elR) elR.textContent = nRotas;
}

function renderSidebar() {
  const q = document.getElementById('searchInput').value.toLowerCase().trim();
  const list = document.getElementById('lineList');
  list.innerHTML = '';

  updateStats();
  renderTurnoFilter();

  // Search mode: show matching passengers with Edit button
  if (q) {
    renderSearchResults(q);
    return;
  }

  // Status filter mode
  if (statusFilter2 !== 'todos') {
    renderStatusList('');
    return;
  }

  // Default: show lines sorted by linha number then turno
  const turnoOrder = {'1°': 1, '2°': 2, '3°': 3};
  const sortedData = [...DATA].sort((a, b) => a.linha - b.linha || (turnoOrder[a.turno]||9) - (turnoOrder[b.turno]||9));
  sortedData.forEach(rota => {
    if (turnoFilter !== 'todos' && rota.turno !== turnoFilter) return;
    const div = document.createElement('div');
    div.className = 'line-item' + (activeId === rota.id ? ' active' : '');
    div.onclick = () => selectLine(rota.id);
    const nome_motorista = rota.motorista || 'Motorista a definir';
    const total = rota.passageiros.length;
    // Fase 1 (apresentacao): numero da linha com dois digitos quando numerico.
    // A fonte do dado e a mesma: rota.linha.
    const badgeTxt = /^\d+$/.test(String(rota.linha))
      ? String(rota.linha).padStart(2, '0') : rota.linha;
    div.innerHTML =
      '<div class="line-badge ' + lc(rota.linha) + '"' + estiloBadgeLinha(rota) + '>' + badgeTxt + '</div>' +
      '<div class="line-info">' +
        '<div class="line-name">Linha ' + rota.linha + '</div>' +
        '<div class="line-meta">' + rota.turno + ' Turno · ' + nome_motorista + ' · ' + rota.veiculo + '</div>' +
      '</div>' +
      '<div class="line-count">' + total + '</div>';
    list.appendChild(div);
  });
}

function renderSearchResults(q) {
  const list = document.getElementById('lineList');
  let found = [];
  DATA.forEach(rota => {
    rota.passageiros.forEach((p, pidx) => {
      const haystack = [p.nome, p.bairro, p.cidade, p.embarque, p.endereco]
        .map(x => (x || '').toLowerCase()).join(' ');
      if (haystack.includes(q)) {
        found.push({ p, rota, pidx });
      }
    });
  });
  DESLIGADOS.forEach(p => {
    const haystack = [p.nome, p.bairro, p.cidade, p.embarque, p.endereco]
      .map(x => (x || '').toLowerCase()).join(' ');
    if (haystack.includes(q)) found.push({ p, rota: null, pidx: -1 });
  });

  if (found.length === 0) {
    list.innerHTML = '<div style="padding:16px;color:var(--muted);font-size:13px;text-align:center">Nenhum resultado encontrado.</div>';
    return;
  }

  const statusColors = { ativo: 'var(--green)', ferias: 'var(--accent)', afastado: 'var(--red)', desligado: 'var(--muted)' };
  const statusIcons  = { ativo: '', ferias: '', afastado: '', desligado: '' };

  found.forEach(({ p, rota, pidx }) => {
    const div = document.createElement('div');
    div.className = 'line-item';
    div.style.flexDirection = 'column';
    div.style.alignItems = 'flex-start';
    div.style.gap = '6px';
    div.style.cursor = 'default';

    const cor = statusColors[p.status] || 'var(--green)';
    const icon = statusIcons[p.status] || '';
    const linhaInfo = rota
      ? ('Linha ' + rota.linha + ' · ' + rota.turno + ' Turno')
      : ('Desligado · Era L' + p.linhaOrigem);

    const top = document.createElement('div');
    top.style.cssText = 'display:flex;justify-content:space-between;width:100%;align-items:center';

    const info = document.createElement('div');
    info.innerHTML =
      '<div style="font-weight:500;font-size:13px">' + p.nome + '</div>' +
      '<div style="font-size:11px;color:var(--muted);margin-top:2px">' + linhaInfo + ' · <span style="color:' + cor + '">' + icon + ' ' + (p.status || '') + '</span></div>' +
      (p.telefone ? '<div style="font-size:11px;color:var(--muted)">' + waLink(p.telefone) + '</div>' : '') +
      ((p.bairro || p.cidade) ? '<div style="font-size:11px;color:var(--muted)">' + [p.bairro, p.cidade].filter(Boolean).join(' · ') + '</div>' : '');

    top.appendChild(info);

    // Botão Editar — aparece para todos que têm rota (inclusive sem-rota)
    if (rota) {
      const btn = document.createElement('button');
      btn.className = 'add-btn';
      btn.style.cssText = 'font-size:11px;padding:4px 10px;flex-shrink:0';
      btn.textContent = 'Editar';
      btn.onclick = (function(rid, pi) {
        return function() { editFromSearch(rid, pi); };
      })(rota.id, pidx);
      top.appendChild(btn);
    }

    div.appendChild(top);
    list.appendChild(div);
  });
}

function editFromSearch(rotaId, idx) {
  document.getElementById('searchInput').value = '';
  activeId = rotaId;
  renderSidebar();
  selectLine(rotaId);
  // Small delay to let the line render then open modal
  setTimeout(() => openEditModal(rotaId, idx), 200);
}

function renderStatusList(q) {
  const list = document.getElementById('lineList');
  const statusLabel = { ferias: 'Férias', afastado: 'Afastado', desligado: 'Desligado', ativo: 'Ativo', 'sem-rota': 'Sem Rota' };
  const statusColor = { ferias: 'var(--accent)', afastado: 'var(--red)', desligado: 'var(--muted)', ativo: 'var(--green)', 'sem-rota': '#9ca3af' };
  const statusEmoji = { ferias: '', afastado: '', desligado: '', ativo: '', 'sem-rota': '' };

  let pessoas = [];

  if (statusFilter2 === 'desligado') {
    pessoas = DESLIGADOS.map(p => ({ ...p, linhaInfo: 'Era Linha ' + p.linhaOrigem + ' · ' + p.turnoOrigem + ' Turno', rotaId: null, passIdx: -1 }));
  } else if (statusFilter2 === 'sem-rota') {
    // Buscar em todas as rotas passageiros com status sem-rota
    DATA.forEach(rota => {
      rota.passageiros.forEach((p, pidx) => {
        if (p.status === 'sem-rota') {
          pessoas.push({ ...p, linhaInfo: 'Sem Rota · aguardando alocação', rotaId: rota.id, passIdx: pidx });
        }
      });
    });
    // Incluir também pool SEM_ROTA se existir
    if (SEM_ROTA && SEM_ROTA.length) {
      SEM_ROTA.forEach((p, pidx) => {
        pessoas.push({ ...p, linhaInfo: 'Sem Rota · pool', rotaId: '__semrota__', passIdx: pidx });
      });
    }
  } else {
    DATA.forEach(rota => {
      if (turnoFilter !== 'todos' && rota.turno !== turnoFilter) return;
      rota.passageiros.forEach((p, pidx) => {
        if (p.status === statusFilter2) {
          pessoas.push({ ...p, linhaInfo: 'Linha ' + rota.linha + ' · ' + rota.turno + ' Turno', rotaId: rota.id, passIdx: pidx });
        }
      });
    });
  }

  if (q) pessoas = pessoas.filter(p => [p.nome, p.bairro, p.cidade, p.embarque].map(x => (x||'').toLowerCase()).join(' ').includes(q.toLowerCase()));

  if (pessoas.length === 0) {
    list.innerHTML = '<div style="padding:16px;color:var(--muted);font-size:13px;text-align:center">Nenhum registro encontrado.</div>';
    return;
  }

  const cor = statusColor[statusFilter2] || 'var(--accent)';
  const emoji = statusEmoji[statusFilter2] || '';

  pessoas.forEach(p => {
    const div = document.createElement('div');
    div.className = 'line-item';
    div.style.cssText = 'flex-direction:column;align-items:flex-start;gap:6px;cursor:default';

    const retornoHtml = p.retorno ? '<span style="color:var(--accent);font-size:10px"> · Retorno: ' + p.retorno + '</span>' : '';

    const top = document.createElement('div');
    top.style.cssText = 'display:flex;justify-content:space-between;width:100%;align-items:center;gap:8px';

    const info = document.createElement('div');
    info.style.cssText = 'display:flex;align-items:center;gap:10px;flex:1;min-width:0';

    const avatar = document.createElement('div');
    avatar.style.cssText = 'width:36px;height:36px;border-radius:10px;background:rgba(100,100,100,0.15);display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0';
    avatar.textContent = emoji;

    const text = document.createElement('div');
    text.className = 'line-info';
    text.innerHTML =
      '<div class="line-name" style="font-size:13px">' + p.nome + '</div>' +
      '<div class="line-meta">' + p.linhaInfo + retornoHtml + '</div>' +
      (p.telefone ? '<div style="font-size:11px;color:var(--muted)">' + waLink(p.telefone) + '</div>' : '') +
      ((p.bairro || p.cidade) ? '<div style="font-size:11px;color:var(--muted)">' + [p.bairro, p.cidade].filter(Boolean).join(' · ') + '</div>' : '');

    info.appendChild(avatar);
    info.appendChild(text);
    top.appendChild(info);

    // Botão Editar — disponível para todos (inclusive pool sem-rota, para poder alocar)
    if (p.rotaId && p.passIdx >= 0) {
      const btn = document.createElement('button');
      btn.className = 'add-btn';
      btn.style.cssText = 'font-size:11px;padding:4px 10px;flex-shrink:0';
      btn.textContent = 'Editar';
      btn.onclick = (function(rid, pi) {
        return function() { editFromSearch(rid, pi); };
      })(p.rotaId, p.passIdx);
      top.appendChild(btn);
    }

    div.appendChild(top);
    list.appendChild(div);
  });
}

function filterSidebar() { renderSidebar(); }

function renderTurnoFilter() {
  const bar = document.getElementById('turnoFilterBar');
  if (!bar) return;
  // Turnos que realmente têm passageiros cadastrados
  const ordem = {'1°':1,'2°':2,'3°':3,'ADM':4};
  const presentes = [...new Set(DATA.filter(r => r.passageiros && r.passageiros.length).map(r => r.turno))]
    .sort((a,b) => (ordem[a]||9) - (ordem[b]||9));
  // Se o turno filtrado atual não existe mais, volta para "todos"
  if (turnoFilter !== 'todos' && !presentes.includes(turnoFilter)) turnoFilter = 'todos';
  let html = '<button class="turno-btn' + (turnoFilter==='todos'?' active':'') + '" onclick="setTurnoFilter(\'todos\', this)">Todos</button>';
  presentes.forEach(t => {
    const label = (t === 'ADM') ? 'ADM' : (t + ' Turno');
    html += '<button class="turno-btn' + (turnoFilter===t?' active':'') + '" onclick="setTurnoFilter(\'' + t + '\', this)">' + label + '</button>';
  });
  bar.innerHTML = html;
}

function setTurnoFilter(t, btn) {
  turnoFilter = t;
  document.querySelectorAll('.turno-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  renderSidebar();
}

// ---- MAIN ----
