function renderTable(rota) {
  const tbody = document.getElementById('passTable');
  if (!tbody) return;
  tbody.innerHTML = '';

  const sorted = [...rota.passageiros].sort((a, b) => {
    const ta = a.horario && a.horario !== '--:--' ? a.horario : '99:99';
    const tb = b.horario && b.horario !== '--:--' ? b.horario : '99:99';
    return ta.localeCompare(tb);
  });

  const statusMap   = { ativo: 'status-ativo', ferias: 'status-ferias', afastado: 'status-afastado', desligado: 'status-desligado' };
  const statusLabel = { ativo: 'Ativo', ferias: 'Férias', afastado: 'Afastado', desligado: 'Desligado' };

  sorted.forEach((p, seqIdx) => {
    const realIdx = rota.passageiros.indexOf(p);
    const embarque = p.embarque || p.endereco;
    const retornoFmt = p.retorno ? (() => {
      // Convert YYYY-MM-DD to DD/MM/YYYY if needed
      const m = p.retorno.match(/^(\d{4})-(\d{2})-(\d{2})$/);
      return m ? m[3]+'/'+m[2]+'/'+m[1] : p.retorno;
    })() : '';
    const retornoBadge = (p.retorno && (p.status === 'ferias' || p.status === 'afastado'))
      ? '<span class="retorno-badge">↩ ' + retornoFmt + '</span>' : '';

    const tr = document.createElement('tr');
    if (p.status === 'desligado') tr.style.opacity = '0.5';
    tr.innerHTML =
      '<td class="td-order">' + (seqIdx + 1) + '</td>' +
      '<td class="td-time">' + (p.horario || '--:--') + '</td>' +
      '<td><div class="td-name" style="' + (p.status==='ferias'||p.status==='afastado' ? 'color:var(--red);opacity:0.85' : '') + '">' + p.nome + '</div><div class="td-sub">' + (p.cidade || '') + '</div></td>' +
      '<td style="font-size:12px;color:var(--muted);white-space:nowrap">' + (p.telefone || '—') + '</td>' +
      '<td class="td-addr"><div>' + (embarque || '—') + '</div>' +
        (p.embarque && p.endereco && p.embarque !== p.endereco ? '<div class="td-addr-embarque">' + p.endereco + '</div>' : '') +
      '</td>' +
      '<td style="font-size:12px;color:var(--muted)">' + (p.bairro || '—') + '</td>' +
      '<td style="' + (p.status==='ferias'||p.status==='afastado' ? 'color:var(--red)' : '') + '"><span class="status-badge ' + (statusMap[p.status] || 'status-ativo') + '"><span class="dot"></span>' + (statusLabel[p.status] || 'Ativo') + '</span>' + retornoBadge + '</td>' +
      '<td class="actions-td" style="text-align:right"></td>';

    const btn = document.createElement('button');
    btn.className = 'action-btn act-editar';
    btn.title = 'Editar passageiro';
    btn.setAttribute('aria-label', 'Editar passageiro');
    // Fase 1: os botoes estavam sem rotulo visivel (textContent vazio).
    // Icone SVG apenas — o handler abaixo continua o mesmo.
    btn.innerHTML = "<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='1.9' stroke-linecap='round' stroke-linejoin='round'><path d='M4 20h4L19 9a2.1 2.1 0 0 0-3-3L5 17v3Z'/><path d='M14.5 6.5 17.5 9.5'/></svg>";
    btn.onclick = (function(rid, ri) {
      return function() { openEditModal(rid, ri); };
    })(rota.id, realIdx);
    tr.querySelector('.actions-td').appendChild(btn);

    const btnDel = document.createElement('button');
    btnDel.className = 'action-btn act-excluir';
    btnDel.title = 'Excluir passageiro';
    btnDel.setAttribute('aria-label', 'Excluir passageiro');
    btnDel.innerHTML = "<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='1.9' stroke-linecap='round' stroke-linejoin='round'><path d='M4 7h16M9.5 7V5h5v2M6.5 7l.8 13h9.4l.8-13'/><path d='M10 11v6M14 11v6'/></svg>";
    btnDel.style.cssText = 'margin-left:2px';
    btnDel.onclick = (function(rid, ri) {
      return function() { excluirPassageiro(rid, ri); };
    })(rota.id, realIdx);
    tr.querySelector('.actions-td').appendChild(btnDel);

    // Reorder cell
    const tdReorder = document.createElement('td');
    tdReorder.style.cssText = 'text-align:center;white-space:nowrap';
    const btnUp = document.createElement('button');
    btnUp.className = 'reorder-btn';
    btnUp.textContent = '↑';
    btnUp.title = 'Embarcar antes (troca o horario com o de cima)';
    btnUp.disabled = seqIdx === 0;
    btnUp.onclick = (function(rid, ri) {
      return function() { movePassageiro(rid, ri, -1); };
    })(rota.id, realIdx);
    const btnDown = document.createElement('button');
    btnDown.className = 'reorder-btn';
    btnDown.textContent = '↓';
    btnDown.title = 'Embarcar depois (troca o horario com o de baixo)';
    btnDown.disabled = seqIdx === sorted.length - 1;
    btnDown.onclick = (function(rid, ri) {
      return function() { movePassageiro(rid, ri, 1); };
    })(rota.id, realIdx);
    tdReorder.appendChild(btnUp);
    tdReorder.appendChild(document.createTextNode(' '));
    tdReorder.appendChild(btnDown);
    tr.appendChild(tdReorder);

    tbody.appendChild(tr);
  });
}

// ---- REORDENAR PASSAGEIRO (setas da tabela) ----
// A tabela e exibida em ordem de HORARIO (renderTable ordena por p.horario).
// Portanto "subir" um passageiro = ele passar a embarcar no horario de quem
// esta acima. A funcao TROCA os dois horarios entre si; nenhum outro campo e
// tocado e a duracao total da rota nao muda.
// Fica registrado no Relatorio de Alteracoes e e salvo como qualquer edicao.
function movePassageiro(rotaId, idx, dir) {
  const rota = DATA.find(r => r.id === rotaId);
  if (!rota) return;

  // mesma ordenacao usada por renderTable
  const sorted = [...rota.passageiros].sort((a, b) => {
    const ta = a.horario && a.horario !== '--:--' ? a.horario : '99:99';
    const tb = b.horario && b.horario !== '--:--' ? b.horario : '99:99';
    return ta.localeCompare(tb);
  });

  const p = rota.passageiros[idx];
  if (!p) return;
  const pos = sorted.indexOf(p);
  const alvo = pos + dir;
  if (pos < 0 || alvo < 0 || alvo >= sorted.length) return;

  const q = sorted[alvo];
  const valido = h => /^\d{2}:\d{2}$/.test(String(h || ''));
  if (!valido(p.horario) || !valido(q.horario)) {
    alert('Nao da para trocar a ordem: um dos dois passageiros esta sem horario de embarque.\n\n' +
          'Preencha o horario dos dois (no lapis de editar) ou use o Roteirizador.');
    return;
  }
  if (p.horario === q.horario) {
    alert('Os dois passageiros tem o mesmo horario (' + p.horario + '). Trocar nao muda nada.\n\n' +
          'Ajuste o horario de um deles para definir a ordem.');
    return;
  }

  const hp = p.horario, hq = q.horario;
  p.horario = hq;
  q.horario = hp;

  logChange('Ordem de embarque', p.nome, hp, hq, 'trocou com ' + q.nome);
  logChange('Ordem de embarque', q.nome, hq, hp, 'trocou com ' + p.nome);

  saveAfterChange();
  renderTable(rota);
}

// ---- CAPACIDADES ----
// Capacidades historicas, usadas so como ultimo recurso: linha antiga que ainda
// nao aponta para nenhum veiculo do cadastro.
const CAP = { 'Van': 15, 'Carro': 4 };

// ==================== FROTA (item 16) ====================
// Cada veiculo e um registro proprio. A capacidade de passageiros nao e um
// numero fixo do "tipo": e uma conta sobre os assentos do veiculo.
//     capacidade = assentos - tripulacao
// e pode ser sobrescrita a mao quando o veiculo perdeu poltronas (area PCD,
// adaptacao). Isso cobre desde um carro de 6 lugares ate um onibus de 46
// assentos com motorista + auxiliar (44 vagas operacionais).
let FROTA = [];

function frCapacidadeDe(v) {
  if (!v) return 0;
  if (v.capacidadeManual != null && v.capacidadeManual !== '') return Math.max(0, parseInt(v.capacidadeManual, 10) || 0);
  return Math.max(0, (parseInt(v.assentos, 10) || 0) - (parseInt(v.tripulacao, 10) || 0));
}

// Como o veiculo aparece nas telas, no PDF e no Excel.
function frRotulo(v) {
  if (!v) return '';
  return v.apelido || (v.modelo ? v.tipo + ' ' + v.modelo : v.tipo);
}

function frBuscar(id) { return FROTA.find(v => v.id === id) || null; }

// O veiculo de uma linha. Prioriza o cadastro; cai no rotulo antigo se a linha
// ainda nao foi migrada.
function veiculoDaRota(rota) {
  if (!rota) return null;
  if (rota.veiculoId) { const v = frBuscar(rota.veiculoId); if (v) return v; }
  return null;
}

function getCapacidade(rota) {
  const v = veiculoDaRota(rota);
  if (v) return frCapacidadeDe(v);
  return CAP[rota.veiculo] || 15;
}

// Resumo de ocupacao de uma linha, ja com a cor e o texto prontos.
function ocupacaoDaRota(rota) {
  const cap = getCapacidade(rota);
  const n = rota.passageiros.length;
  const pct = cap > 0 ? Math.round((n / cap) * 100) : 0;
  const excedeu = n > cap;
  const restam = cap - n;
  return {
    n: n, cap: cap, pct: pct, excedeu: excedeu, restam: Math.max(0, restam),
    acima: Math.max(0, n - cap),
    // O alarme conta VAGAS, nao porcentagem. Porcentagem trata mal veiculos de
    // tamanhos diferentes: 90% e "acabou" num carro de 4 e "cabem mais quatro"
    // num onibus de 44. Uma vaga livre e uma vaga livre em qualquer veiculo.
    //   verde  = 2 vagas ou mais
    //   ambar  = ultima vaga, ou lotada
    //   vermelho = excedeu
    cor: excedeu ? 'var(--red)' : (restam <= 1 ? 'var(--warn, #E0A94A)' : 'var(--green)'),
    texto: excedeu
      ? (n + ' passageiros / ' + cap + ' vagas')
      : (n + ' / ' + cap + ' vagas'),
    detalhe: excedeu
      ? (rota.passageiros.length - cap === 1 ? '1 passageiro acima da capacidade'
                                             : (n - cap) + ' passageiros acima da capacidade')
      : (restam === 0 ? 'lotada'
         : restam === 1 ? 'última vaga'
         : restam + ' vagas livres · ' + pct + '%')
  };
}

// Ocupacao media da operacao — soma passageiros e soma vagas (media ponderada,
// que e a que faz sentido: uma van cheia pesa mais que um carro vazio).
function ocupacaoMediaFrota() {
  let pax = 0, vagas = 0;
  DATA.forEach(r => { pax += r.passageiros.length; vagas += getCapacidade(r); });
  return vagas > 0 ? Math.round((pax / vagas) * 100) : 0;
}

// ==================== GERENCIADOR DE LINHAS ====================
let glEditandoId = null; // id da rota em edição (null = criando)

// Preenche o select de turno do Gerenciar Linhas com os turnos que JÁ existem
// (padrões + turnos das linhas cadastradas), mantendo "Outro turno (digitar)" ao final.
// Assim você reaproveita um turno (ex.: AdmTeste) em várias linhas sem redigitar.
// Preenche o select de veiculo com a frota cadastrada. Sem frota, mantem as
// opcoes antigas para o sistema continuar utilizavel enquanto o gestor cadastra.
function glPopularVeiculos(selecionado) {
  const sel = document.getElementById('glVeiculo');
  const dica = document.getElementById('glVeiculoDica');
  if (!sel) return;
  const atual = selecionado !== undefined ? selecionado : sel.value;
  if (FROTA.length) {
    sel.innerHTML = FROTA.map(v =>
      '<option value="' + v.id + '">' + esc(frRotulo(v)) + ' — ' + frCapacidadeDe(v) + ' vagas</option>'
    ).join('');
    if (dica) dica.textContent = 'A capacidade vem do cadastro da frota, em Configurações.';
  } else {
    sel.innerHTML = '<option value="Van">Van (15 lugares)</option>' +
                    '<option value="Carro">Carro (4 lugares)</option>';
    if (dica) dica.textContent = 'Cadastre a frota em Configurações para usar as capacidades reais dos seus veículos.';
  }
  if (atual && Array.from(sel.options).some(o => o.value === atual)) sel.value = atual;
}

function glPopularTurnos() {
  const sel = document.getElementById('glTurno');
  if (!sel) return;
  const atual = sel.value;
  const turnos = [];
  const add = (t) => { if (t && turnos.indexOf(t) === -1) turnos.push(t); };
  // O turno agora tem cadastro próprio (Configurações › Operação). Digitar um
  // nome aqui criaria turno sem horário, sem dias e sem calendário — o que o
  // motorista e o passageiro precisam ler. A lista vem só do cadastro.
  try { turnosSemear(); TURNOS.forEach(t => add(t.nome)); } catch (e) {}
  DATA.forEach(r => add(r.turno));            // e os já usados, para não sumir nenhum
  const ordemPadrao = { '1°': 1, '2°': 2, '3°': 3, 'ADM': 4 };
  turnos.sort((a, b) => (ordemPadrao[a] || 99) - (ordemPadrao[b] || 99) || String(a).localeCompare(String(b)));
  const rotulo = (t) => (t === 'ADM' ? 'ADM' : t + (/^\d/.test(t) ? ' Turno' : ''));
  let html = '';
  turnos.forEach(t => { html += '<option value="' + esc(t) + '">' + esc(rotulo(t)) + '</option>'; });
  sel.innerHTML = html;
  const dica = document.getElementById('glTurnoDica');
  if (dica) dica.innerHTML = 'Para criar ou mudar um turno, use ' +
    '<a href="#" onclick="document.getElementById(\'modalGerLinhas\').classList.remove(\'open\');' +
    'openConfig();cfgIr(\'oper\');return false" style="color:var(--accent)">Configurações › Operação</a>.';
  if (atual && Array.from(sel.options).some(o => o.value === atual)) sel.value = atual;
}

function openGerLinhas() {
  glCorSel = '';
  glPopularVeiculos();
  glEditandoId = null;
  glPopularTurnos();
  glResetForm();
  glRenderCores();
  glRenderLista();
  // toggle do campo "turno novo"
  const selT = document.getElementById('glTurno');
  selT.onchange = function() {
    const _g = document.getElementById('glTurnoNovoGroup');
    if (_g) _g.style.display = (selT.value === '__novo__') ? 'block' : 'none';
  };
  document.getElementById('modalGerLinhas').classList.add('open');
}

function glResetForm() {
  glCorSel = ''; glRenderCores();
  glEditandoId = null;
  document.getElementById('glFormTitulo').textContent = 'Criar nova linha';
  document.getElementById('glLinha').value = '';
  document.getElementById('glTurno').value = '1°';
  // o campo de digitar turno saiu: o turno agora vem do cadastro
  const _tn = document.getElementById('glTurnoNovo'); if (_tn) _tn.value = '';
  const _tg = document.getElementById('glTurnoNovoGroup'); if (_tg) _tg.style.display = 'none';
  document.getElementById('glVeiculo').value = 'Van';
  document.getElementById('glMotorista').value = '';
  document.getElementById('glBtnSalvar').textContent = 'Criar linha';
  document.getElementById('glBtnCancelar').style.display = 'none';
  document.getElementById('glFormMsg').textContent = '';
}

function glCancelarEdicao() {
  glCorSel = ''; glRenderCores(); glResetForm(); }

function glRenderLista() {
  const div = document.getElementById('glLista');
  if (!DATA.length) { div.innerHTML = '<div style="padding:12px;font-size:13px;color:var(--muted)">Nenhuma linha cadastrada ainda.</div>'; return; }
  // ordena por turno e linha
  const ordemT = {'1°':1,'2°':2,'3°':3,'ADM':4};
  const rotas = [...DATA].sort((a,b) => (ordemT[a.turno]||9)-(ordemT[b.turno]||9) || (a.linha-b.linha));
  let html = '';
  rotas.forEach(r => {
    const oc = ocupacaoDaRota(r);
    html += '<div class="gl-item">' +
      '<span class="gl-bolinha" style="background:' + corLinha(r) + '"></span>' +
      '<div style="flex:1;min-width:0">' +
        '<div style="font-weight:700;font-size:14px">Linha ' + esc(String(r.linha)) + ' — ' + esc(r.turno === 'ADM' ? 'ADM' : r.turno + ' Turno') + '</div>' +
        '<div style="font-size:12px;color:var(--muted)">' + esc(r.veiculo || '—') + (r.motorista ? ' · ' + esc(r.motorista) : '') + '</div>' +
        '<div style="font-size:12px;margin-top:3px;color:' + oc.cor + '">' +
          (oc.excedeu ? '\u25CF ' : '') + oc.texto + ' <span style="color:var(--muted)">· ' + oc.detalhe + '</span></div>' +
      '</div>' +
      '<button onclick="glEditar(\'' + r.id + '\')" class="ico-btn ico-editar" title="Editar linha" aria-label="Editar linha"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 20h4L19 9a2.1 2.1 0 0 0-3-3L5 17v3Z\"/><path d=\"M14.5 6.5 17.5 9.5\"/></svg></button>' +
      '<button onclick="glExcluir(\'' + r.id + '\')" class="ico-btn ico-excluir" title="Excluir linha" aria-label="Excluir linha"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 7h16M9.5 7V5h5v2M6.5 7l.8 13h9.4l.8-13\"/><path d=\"M10 11v6M14 11v6\"/></svg></button>' +
    '</div>';
  });
  const media = ocupacaoMediaFrota();
  html = '<div class="fr-resumo">Ocupação média da operação: <b>' + media + '%</b>' +
         '<span>' + DATA.length + (DATA.length === 1 ? ' linha' : ' linhas') + '</span></div>' + html;
  div.innerHTML = html;
}

let glCorSel = '';

function glRenderCores() {
  const box = document.getElementById('glCores');
  if (!box) return;
  box.innerHTML = CORES_LINHA.map(c =>
    '<button type="button" class="gl-cor' + (glCorSel === c ? ' sel' : '') + '"' +
    ' style="background:' + c + '" title="' + c + '" onclick="glSetCor(\'' + c + '\')"></button>'
  ).join('') +
  '<button type="button" class="gl-cor gl-cor-auto' + (glCorSel ? '' : ' sel') + '"' +
  ' title="Cor automática" onclick="glSetCor(\'\')">auto</button>';
}

function glSetCor(c) { glCorSel = c || ''; glRenderCores(); }

function glSalvar() {
  const linhaRaw = document.getElementById('glLinha').value.trim();
  let turno = document.getElementById('glTurno').value;
  if (turno === '__novo__') {   // caminho antigo: não existe mais na tela
    turno = (document.getElementById('glTurnoNovo') || { value: '' }).value.trim();
    if (!turno) { glMsg('Digite o nome do novo turno.', true); return; }
  }
  // O select guarda o id do veiculo quando ha frota; sem frota, guarda o rotulo
  // antigo ("Van"/"Carro"). As duas formas continuam validas.
  const escolhido = document.getElementById('glVeiculo').value;
  const veicObj = frBuscar(escolhido);
  const veiculoId = veicObj ? veicObj.id : null;
  const veiculo = veicObj ? frRotulo(veicObj) : escolhido;
  const motorista = document.getElementById('glMotorista').value.trim();
  const msg = document.getElementById('glFormMsg');

  if (!linhaRaw) { glMsg('Informe o número da linha.', true); return; }
  // número da linha aceita texto (ex.: VERTIV) mas normalmente número
  const linhaNum = /^\d+$/.test(linhaRaw) ? parseInt(linhaRaw, 10) : linhaRaw;

  const novoId = linhaRaw + '-' + turno;

  if (glEditandoId) {
    // EDIÇÃO: atualiza a rota existente
    const rota = DATA.find(r => r.id === glEditandoId);
    if (!rota) { glMsg('Linha não encontrada.', true); return; }
    // Se mudou linha/turno, o id muda — verifica conflito
    if (novoId !== glEditandoId && DATA.some(r => r.id === novoId)) {
      glMsg('Já existe uma linha ' + linhaRaw + ' no turno ' + turno + '.', true); return;
    }
    // Se reduziu capacidade abaixo da ocupação, avisa
    const novaCap = veicObj ? frCapacidadeDe(veicObj) : (CAP[veiculo] || 15);
    if (rota.passageiros.length > novaCap) {
      if (!confirm('Esta linha tem ' + rota.passageiros.length + ' passageiros, mas o ' + veiculo + ' comporta ' + novaCap + '. Continuar mesmo assim?')) return;
    }
    rota.linha = linhaNum;
    rota.turno = turno;
    rota.veiculo = veiculo;
    if (veiculoId) rota.veiculoId = veiculoId; else delete rota.veiculoId;
    if (glCorSel) rota.cor = glCorSel; else delete rota.cor;
    rota.motorista = motorista;
    rota.id = novoId;
    rota.cod = 'L' + linhaRaw + '|' + turno + '|' + (veicObj ? veicObj.tipo : veiculo).toUpperCase();
    logChange('alteracao', 'Linha ' + linhaRaw, '—', 'Linha editada (' + veiculo + ', turno ' + turno + ')', '');
    saveAfterChange();
    renderSidebar();
    glResetForm();
    glRenderLista();
    glMsg('Linha atualizada!', false);
    return;
  }

  // CRIAÇÃO: verifica se já existe
  if (DATA.some(r => r.id === novoId)) {
    glMsg('Já existe uma linha ' + linhaRaw + ' no turno ' + turno + '.', true); return;
  }
  const novaRota = {
    id: novoId,
    linha: linhaNum,
    turno: turno,
    cor: glCorSel || undefined, veiculo: veiculo, veiculoId: veiculoId || undefined,
    cod: 'L' + linhaRaw + '|' + turno + '|' + (veicObj ? veicObj.tipo : veiculo).toUpperCase(),
    motorista: motorista,
    motoristaSaida: '',
    passageiros: []
  };
  DATA.push(novaRota);
  logChange('inclusao', 'Linha ' + linhaRaw, '—', 'Nova linha criada (' + veiculo + ', turno ' + turno + ')', '');
  saveAfterChange();
  renderSidebar();
  glResetForm();
  glRenderLista();
  glMsg('Linha ' + linhaRaw + ' (' + turno + ') criada!', false);
}

function glEditar(id) {
  const rota = DATA.find(r => r.id === id);
  if (!rota) return;
  glEditandoId = id;
  document.getElementById('glFormTitulo').textContent = 'Editar linha ' + rota.linha + ' (' + rota.turno + ')';
  document.getElementById('glLinha').value = rota.linha;
  // turno: agora a lista já contém os turnos existentes; seleciona direto se houver,
  // e só cai em "digitar" se for um turno que não está na lista.
  glPopularTurnos();
  const selT = document.getElementById('glTurno');
  const existeNaLista = Array.from(selT.options).some(o => o.value === rota.turno);
  if (existeNaLista) {
    selT.value = rota.turno;
    const _g2 = document.getElementById('glTurnoNovoGroup');
    if (_g2) _g2.style.display = 'none';
  } else {
    selT.value = '__novo__';
    document.getElementById('glTurnoNovoGroup').style.display = 'block';
    document.getElementById('glTurnoNovo').value = rota.turno;
  }
  glCorSel = rota.cor || ''; glRenderCores();
  glPopularVeiculos(rota.veiculoId || rota.veiculo);
  document.getElementById('glVeiculo').value = rota.veiculo;
  document.getElementById('glMotorista').value = rota.motorista || '';
  document.getElementById('glBtnSalvar').textContent = 'Salvar alterações';
  document.getElementById('glBtnCancelar').style.display = 'block';
  document.getElementById('glFormMsg').textContent = '';
  // rola para o topo do modal
  document.getElementById('modalGerLinhas').querySelector('.modal').scrollTop = 0;
}

function glExcluir(id) {
  const rota = DATA.find(r => r.id === id);
  if (!rota) return;
  if (rota.passageiros.length > 0) {
    alert('Esta linha tem ' + rota.passageiros.length + ' passageiro(s). Remova ou realoque os passageiros antes de excluir a linha.');
    return;
  }
  if (!confirm('Excluir a linha ' + rota.linha + ' (' + rota.turno + ')? Esta ação não pode ser desfeita.')) return;
  const idx = DATA.findIndex(r => r.id === id);
  if (idx >= 0) {
    DATA.splice(idx, 1);
    logChange('exclusao', 'Linha ' + rota.linha, '—', 'Linha excluída (turno ' + rota.turno + ')', '');
    saveAfterChange();
    renderSidebar();
    glRenderLista();
    if (glEditandoId === id) glResetForm();
  }
}

function glMsg(texto, erro) {
  const m = document.getElementById('glFormMsg');
  m.textContent = texto;
  m.style.color = erro ? 'var(--red)' : 'var(--green)';
}
// ==================== FIM GERENCIADOR DE LINHAS ====================

function isLotada(rota, excluindoIdx = null) {
  let count = rota.passageiros.length;
  if (excluindoIdx !== null) count--; // ao editar, não conta o próprio passageiro
  return count >= getCapacidade(rota);
}

// Popula o select de turno com os turnos REAIS existentes nas linhas (DATA),
// garantindo a ordem padrão e sempre incluindo "A Definir" ao final.
// Assim, qualquer turno novo criado no Gerenciar Linhas aparece aqui automaticamente.
function popularTurnoOptions() {
  const sel = document.getElementById('fTurno');
  if (!sel) return;
  const atual = sel.value; // preserva seleção atual, se houver
  // Coleta turnos distintos presentes nas linhas cadastradas
  const turnos = [];
  // mesma fonte do Gerenciar Linhas: o cadastro manda, as linhas complementam
  try { turnosSemear(); TURNOS.forEach(t => { if (turnos.indexOf(t.nome) === -1) turnos.push(t.nome); }); } catch (e) {}
  DATA.forEach(r => { if (r.turno && turnos.indexOf(r.turno) === -1) turnos.push(r.turno); });
  // Ordena pelos turnos padrão primeiro, depois alfabético para os customizados
  const ordemPadrao = { '1°': 1, '2°': 2, '3°': 3, 'ADM': 4 };
  turnos.sort((a, b) => (ordemPadrao[a] || 99) - (ordemPadrao[b] || 99) || String(a).localeCompare(String(b)));
  const rotulo = (t) => {
    const h = (EMPRESA_CONFIG.turnosChegada && EMPRESA_CONFIG.turnosChegada[t]) ? (' — chegada ' + EMPRESA_CONFIG.turnosChegada[t]) : '';
    return (t === 'ADM' ? 'ADM' : t + (/^\d/.test(t) ? ' Turno' : '')) + h;
  };
  let html = '';
  turnos.forEach(t => { html += '<option value="' + esc(t) + '">' + esc(rotulo(t)) + '</option>'; });
  html += '<option value="A Definir">A Definir (sem rota ainda)</option>';
  sel.innerHTML = html;
  // Restaura a seleção anterior, se ainda existir
  if (atual && Array.from(sel.options).some(o => o.value === atual)) sel.value = atual;
}

function updateLinhaOptions(preferRotaId) {
  const turno = document.getElementById('fTurno').value;
  const sel = document.getElementById('fLinha');
  sel.innerHTML = '';

  // Turno "A Definir": passageiro entra sem rota (aguardando alocacao)
  if (turno === 'A Definir') {
    const opt = document.createElement('option');
    opt.value = '__sem_rota__';
    opt.textContent = 'Sem Rota (aguardando alocação)';
    sel.appendChild(opt);
    const st = document.getElementById('fStatus');
    if (st) { st.value = 'sem-rota'; if (typeof toggleSemRota === 'function') toggleSemRota(); }
    return;
  }

  const rotaOriginalId = editingPassIdx !== null ? activeId : null;

  DATA.forEach(rota => {
    if (rota.turno !== turno) return;
    const isOrigem = rota.id === rotaOriginalId;
    const ocupacao = isOrigem ? rota.passageiros.length - 1 : rota.passageiros.length;
    const cap = getCapacidade(rota);
    const lotada = ocupacao >= cap;
    if (lotada && !isOrigem) return;

    const opt = document.createElement('option');
    opt.value = rota.id;
    opt.textContent = 'Linha ' + rota.linha + ' — ' + rota.passageiros.length + '/' + cap + ' pass.' + (isOrigem ? ' (linha atual)' : '');
    sel.appendChild(opt);
  });

  const target = preferRotaId || activeId;
  if (target) {
    const exists = Array.from(sel.options).some(o => o.value === target);
    if (exists) sel.value = target;
  }

  if (sel.options.length === 0) {
    const opt = document.createElement('option');
    opt.value = '';
    opt.textContent = 'Nenhuma linha disponível neste turno';
    sel.appendChild(opt);
  }
}

