// ---- PDF EXPORT ----
let pdfRevision = {};

// ==================== PDF — RELATÓRIO DE EMBARQUE ====================
// Layout claro, para impressão e para o cliente. A marca temvia é a do produto;
// transportadora e operação aparecem como contexto, nunca acima dela.

const PDF_COR = {
  ambar:    [245, 158, 11],
  ambarClr: [254, 243, 219],
  tinta:    [23, 23, 23],
  texto:    [64, 64, 64],
  suave:    [124, 124, 124],
  linha:    [226, 228, 232],
  fundo:    [249, 250, 251],
  verde:    [21, 128, 61],
  verdeClr: [230, 247, 237],
  vermelho: [190, 32, 44],
  vermeClr: [253, 235, 236],
  laranja:  [180, 105, 10],
  laranjaC: [254, 243, 219]
};

let PDF_LOGO = undefined; // undefined = ainda não tentou; null = não disponível

async function pdfCarregarLogo() {
  if (PDF_LOGO !== undefined) return PDF_LOGO;
  // O ?v= existe porque um 404 antigo fica guardado no navegador: sem furar o
  // cache, o arquivo pode estar no ar e o PDF continuar usando a marca vetorial.
  // (Era o que acontecia com cache:'force-cache', que nem revalidava.)
  const ver = window.TEMA_VERSAO || 'x';
  const caminhos = ['/marca/temvia-horizontal-claro.png?v=' + ver,
                    'marca/temvia-horizontal-claro.png?v=' + ver];
  for (const url of caminhos) {
    try {
      const resp = await fetch(url, { cache: 'reload' });
      if (!resp.ok) throw new Error('HTTP ' + resp.status);
      const tipo = resp.headers.get('content-type') || '';
      // GitHub Pages devolve uma pagina HTML quando o caminho nao existe
      if (tipo.indexOf('image/') !== 0) throw new Error('resposta não é imagem (' + tipo + ')');
      const blob = await resp.blob();
      if (blob.size < 500) throw new Error('arquivo vazio ou truncado (' + blob.size + ' bytes)');
      PDF_LOGO = await new Promise((ok, err) => {
        const fr = new FileReader();
        fr.onload = () => ok(fr.result);
        fr.onerror = () => err(new Error('leitura falhou'));
        fr.readAsDataURL(blob);
      });
      return PDF_LOGO;
    } catch (e) {
      console.warn('[pdf] logo não carregou de ' + new URL(url, location.href).href + ' — ' + e.message);
    }
  }
  // Sem o arquivo, desenhamos a marca em vetor. O PDF nunca sai sem marca.
  console.warn('[pdf] usando a marca vetorial. Para usar o PNG oficial, ' +
               'confira se /marca/temvia-horizontal-claro.png está no repositório.');
  PDF_LOGO = null;
  return PDF_LOGO;
}

// Marca temvia desenhada em vetor: símbolo (a seta em V) + palavra.
// As coordenadas vêm do SVG oficial (viewBox 64x64): triângulo (9,17)-(49,17)-(31,51)
// traçado, mais a barra interna (18,29)-(38,29). Serve de reserva do PNG e
// imprime nítida em qualquer ampliação.
function pdfDesenharMarca(doc, x, y, alt) {
  const s = alt * 1.06;                       // lado da caixa do símbolo
  const P = (px, py) => [x + px / 64 * s, y + py / 64 * s];
  doc.setLineCap('round'); doc.setLineJoin('round');
  doc.setDrawColor(250, 168, 20);
  doc.setLineWidth(7.5 / 64 * s);
  const a = P(9, 17), b = P(49, 17), c = P(31, 51);
  doc.lines([[b[0] - a[0], b[1] - a[1]], [c[0] - b[0], c[1] - b[1]], [a[0] - c[0], a[1] - c[1]]],
            a[0], a[1], [1, 1], 'S', true);
  const d = P(18, 29), e = P(38, 29);
  doc.line(d[0], d[1], e[0], e[1]);
  doc.setLineCap('butt'); doc.setLineJoin('miter');
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(alt * 2.9);
  doc.setTextColor.apply(doc, PDF_COR.tinta);
  doc.text('temvia', x + s * 1.18, y + alt * 0.88);
}

// Ícones vetoriais simples. Desenhar em vetor mantém o PDF leve e nítido em
// qualquer zoom — imagem rasterizada ficaria borrada na impressão.
function pdfIcone(doc, nome, x, y, t, cor) {
  const c = cor || PDF_COR.ambar;
  doc.setDrawColor(c[0], c[1], c[2]);
  doc.setFillColor(c[0], c[1], c[2]);
  doc.setLineWidth(0.35);
  const m = t / 2;
  switch (nome) {
    case 'pessoa':
      doc.circle(x + m, y + t * 0.32, t * 0.20, 'S');
      doc.lines([[t * 0.34, -t * 0.30], [t * 0.34, t * 0.30]], x + m - t * 0.34, y + t * 0.92, [1, 1], 'S', false);
      break;
    case 'telefone':
      doc.roundedRect(x + t * 0.28, y + t * 0.08, t * 0.44, t * 0.84, t * 0.10, t * 0.10, 'S');
      doc.line(x + t * 0.42, y + t * 0.20, x + t * 0.58, y + t * 0.20);
      break;
    case 'relogio':
      doc.circle(x + m, y + m, m * 0.86, 'S');
      doc.line(x + m, y + m, x + m, y + m - t * 0.26);
      doc.line(x + m, y + m, x + m + t * 0.18, y + m + t * 0.10);
      break;
    case 'van':
      doc.roundedRect(x + t * 0.06, y + t * 0.26, t * 0.88, t * 0.42, t * 0.08, t * 0.08, 'S');
      doc.line(x + t * 0.06, y + t * 0.46, x + t * 0.94, y + t * 0.46);
      doc.circle(x + t * 0.26, y + t * 0.72, t * 0.09, 'S');
      doc.circle(x + t * 0.72, y + t * 0.72, t * 0.09, 'S');
      break;
    case 'revisao':
      doc.circle(x + m, y + m, m * 0.80, 'S');
      doc.line(x + m, y + m - m * 0.80, x + m + t * 0.16, y + m - m * 0.80 + t * 0.10);
      break;
    case 'calendario':
      doc.roundedRect(x + t * 0.10, y + t * 0.18, t * 0.80, t * 0.72, t * 0.08, t * 0.08, 'S');
      doc.line(x + t * 0.10, y + t * 0.40, x + t * 0.90, y + t * 0.40);
      doc.line(x + t * 0.32, y + t * 0.08, x + t * 0.32, y + t * 0.26);
      doc.line(x + t * 0.68, y + t * 0.08, x + t * 0.68, y + t * 0.26);
      break;
    case 'casa':
      doc.lines([[m, -t * 0.38], [m, t * 0.38]], x, y + t * 0.48, [1, 1], 'S', false);
      doc.rect(x + t * 0.18, y + t * 0.48, t * 0.64, t * 0.40, 'S');
      break;
    case 'pino':
      doc.circle(x + m, y + t * 0.38, t * 0.30, 'S');
      doc.lines([[-t * 0.22, t * 0.34], [t * 0.44, 0]], x + m + t * 0.22, y + t * 0.56, [1, 1], 'S', false);
      break;
    case 'grupo':
      doc.circle(x + t * 0.36, y + t * 0.30, t * 0.17, 'S');
      doc.lines([[t * 0.28, -t * 0.26], [t * 0.28, t * 0.26]], x + t * 0.08, y + t * 0.86, [1, 1], 'S', false);
      doc.circle(x + t * 0.76, y + t * 0.32, t * 0.13, 'S');
      break;
  }
}

function pdfRotuloValor(doc, rotulo, valor, x, y, icone, larguraMax) {
  if (icone) pdfIcone(doc, icone, x, y - 3.4, 4.2);
  const dx = icone ? 6 : 0;
  doc.setFont('helvetica', 'normal'); doc.setFontSize(7);
  doc.setTextColor.apply(doc, PDF_COR.suave);
  doc.text(rotulo, x + dx, y - 0.6);
  // O valor encolhe ate caber no proprio campo. Melhor um nome de motorista
  // um ponto menor do que ele atravessando o divisor do campo seguinte.
  const txt = String(valor || '—');
  let corpo = 9.5;
  if (larguraMax) {
    doc.setFont('helvetica', 'bold');
    while (corpo > 6.5) {
      doc.setFontSize(corpo);
      if (doc.getTextWidth(txt) <= larguraMax) break;
      corpo -= 0.5;
    }
  }
  doc.setFont('helvetica', 'bold'); doc.setFontSize(corpo);
  doc.setTextColor.apply(doc, PDF_COR.tinta);
  doc.text(txt, x + dx, y + 4.2);
}

function pdfCabecalho(doc, ctx, completo) {
  const L = 14, R = 196;
  if (completo) {
    if (PDF_LOGO) {
      doc.addImage(PDF_LOGO, 'PNG', L, 11, 34, 8.1);
    } else {
      pdfDesenharMarca(doc, L, 11, 8.1);
    }
    doc.setDrawColor.apply(doc, PDF_COR.linha); doc.setLineWidth(0.4);
    doc.line(L + 40, 10, L + 40, 22);
    doc.setFont('helvetica', 'bold'); doc.setFontSize(12);
    doc.setTextColor.apply(doc, PDF_COR.laranja);
    doc.text(ctx.transportadora, L + 45, 15.5);
    if (ctx.operacao) {
      doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
      doc.setTextColor.apply(doc, PDF_COR.texto);
      doc.text('Operação ' + ctx.operacao, L + 45, 20.5);
    }
    doc.setDrawColor.apply(doc, PDF_COR.ambar); doc.setLineWidth(0.5);
    doc.circle(R - 8, 16, 7.4, 'S');
    pdfIcone(doc, 'van', R - 12.2, 12, 8.4);
    doc.setFillColor.apply(doc, PDF_COR.ambar);
    doc.rect(L, 27, R - L, 0.9, 'F');
    return 34;
  }
  // páginas seguintes: faixa fina, só para dar contexto
  doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
  doc.setTextColor.apply(doc, PDF_COR.tinta);
  doc.text('temvia', L, 14);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
  doc.setTextColor.apply(doc, PDF_COR.texto);
  doc.text(ctx.transportadora + ' · ' + ctx.tituloLinha, L + 20, 14);
  doc.setFillColor.apply(doc, PDF_COR.ambar);
  doc.rect(L, 17.5, R - L, 0.6, 'F');
  return 23;
}

function pdfRodapePagina(doc, ctx) {
  const L = 14, R = 196;
  doc.setDrawColor.apply(doc, PDF_COR.linha); doc.setLineWidth(0.3);
  doc.line(L, 283, R, 283);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
  doc.setTextColor.apply(doc, PDF_COR.suave);
  // O texto "Pagina X de Y" e escrito no fim, quando o total ja e conhecido.
  doc.setFontSize(7);
  doc.text('temvia', L, 288);
}

// Escreve "Pagina X de Y" em todas as paginas, agora que Y e conhecido.
function pdfFinalizarPaginas(doc, ctx, R) {
  const total = doc.internal.getNumberOfPages();
  for (let i = 1; i <= total; i++) {
    doc.setPage(i);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
    doc.setTextColor.apply(doc, PDF_COR.suave);
    doc.text('Relatório de Embarque   \u2022   ' + ctx.tituloLinha + '   \u2022   Página ' + i + ' de ' + total,
             R, 288, { align: 'right' });
  }
}

async function exportPDF(rotaId) {
  const { jsPDF } = window.jspdf;
  if (!jsPDF) { alert('Biblioteca PDF não carregou ainda. Tente novamente.'); return; }

  await pdfCarregarLogo();

  const targetIds = rotaId ? [rotaId] : (activeId ? [activeId] : DATA.map(r => r.id));

  for (const rid of targetIds) {
    const rota = DATA.find(r => r.id === rid);
    if (!rota) continue;

    if (!pdfRevision[rid]) pdfRevision[rid] = 0;
    pdfRevision[rid]++;
    const rev = pdfRevision[rid];

    const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    const now = new Date();
    const datahora = now.toLocaleDateString('pt-BR') + ' ' +
      now.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });

    const nomeOperacao = (EMPRESA_CONFIG.operacaoNome || '').trim() ||
      (C.pathPrefix || '').split('/').filter(Boolean).pop().toUpperCase();
    const ctx = {
      transportadora: EMPRESA_CONFIG.nome || C.empresaNome || C.marca,
      operacao: nomeOperacao,
      tituloLinha: 'Linha ' + rota.linha + ' — ' + rota.turno + ' Turno'
    };

    const L = 14, R = 196;
    let y = pdfCabecalho(doc, ctx, true);

    // ---- título + data de geração ----
    doc.setFont('helvetica', 'bold'); doc.setFontSize(20);
    doc.setTextColor.apply(doc, PDF_COR.tinta);
    doc.text('Relatório de Embarque', L, y + 7);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
    doc.setTextColor.apply(doc, PDF_COR.texto);
    doc.text('Relação de passageiros e pontos de embarque', L, y + 12.5);

    doc.setDrawColor.apply(doc, PDF_COR.linha); doc.setLineWidth(0.3);
    doc.setFillColor(255, 255, 255);
    doc.roundedRect(R - 58, y - 2, 58, 16, 2, 2, 'FD');
    pdfIcone(doc, 'calendario', R - 53, y + 3, 6.4);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
    doc.setTextColor.apply(doc, PDF_COR.suave);
    doc.text('Gerado em', R - 44, y + 4.5);
    doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
    doc.setTextColor.apply(doc, PDF_COR.tinta);
    doc.text(datahora, R - 44, y + 10.5);
    y += 20;

    // ---- cartão da linha ----
    const chegada = TURNOS_CHEGADA[rota.turno] || '—';
    const motor = rota.motorista || 'A definir';
    const mObj = MOTORISTAS.find(m => m.nome === motor);
    doc.setFillColor.apply(doc, PDF_COR.fundo);
    doc.setDrawColor.apply(doc, PDF_COR.linha); doc.setLineWidth(0.3);
    doc.roundedRect(L, y, R - L, 24, 3, 3, 'FD');

    doc.setDrawColor.apply(doc, PDF_COR.ambar); doc.setLineWidth(0.5);
    doc.circle(L + 12, y + 12, 7, 'S');
    pdfIcone(doc, 'van', L + 8, y + 8, 8);

    doc.setFont('helvetica', 'bold'); doc.setFontSize(14);
    doc.setTextColor.apply(doc, PDF_COR.tinta);
    doc.text(ctx.tituloLinha, L + 24, y + 8);

    // Larguras por campo, nao divisao igual: telefone e veiculo precisam de mais
    // espaco que "Chegada" e "Revisao". Soma = 156mm (largura util do cartao).
    const campos = [
      ['Motorista', motor,                              'pessoa',   36],
      ['Telefone',  mObj && mObj.tel ? mObj.tel : '—',  'telefone', 36],
      ['Chegada',   chegada,                            'relogio',  24],
      ['Veículo',   rota.veiculo || '—',                'van',      36],
      ['Revisão',   'R' + rev,                          'revisao',  24]
    ];
    let cx = L + 25;
    campos.forEach((c, i) => {
      if (i > 0) {
        doc.setDrawColor.apply(doc, PDF_COR.linha); doc.setLineWidth(0.3);
        doc.line(cx - 3, y + 11, cx - 3, y + 20);
      }
      pdfRotuloValor(doc, c[0], c[1], cx, y + 15.5, c[2], c[3] - 8);
      cx += c[3];
    });
    y += 30;

    // ---- passageiros ----
    const sorted = [...rota.passageiros]
      .filter(p => p.status !== 'desligado')
      .sort((a, b) => {
        const ta = a.horario && a.horario !== '--:--' ? a.horario : '99:99';
        const tb = b.horario && b.horario !== '--:--' ? b.horario : '99:99';
        return ta.localeCompare(tb);
      });

    const statusLabel = { ativo: 'Ativo', ferias: 'Férias', afastado: 'Afastado' };
    const statusCor = {
      ativo:    { txt: PDF_COR.verde,    bg: PDF_COR.verdeClr },
      ferias:   { txt: PDF_COR.vermelho, bg: PDF_COR.vermeClr },
      afastado: { txt: PDF_COR.laranja,  bg: PDF_COR.laranjaC }
    };
    const fmtRetorno = (d) => {
      if (!d) return '';
      const m = String(d).match(/^(\d{4})-(\d{2})-(\d{2})$/);
      return m ? m[3] + '/' + m[2] + '/' + m[1] : d;
    };

    const meta = sorted.map(p => ({
      status: p.status,
      retorno: (p.status === 'ferias' || p.status === 'afastado') ? fmtRetorno(p.retorno) : ''
    }));

    const rows = sorted.map((p, i) => [
      i + 1,
      p.horario || '--:--',
      p.nome,
      p.telefone || '—',
      p.embarque || p.endereco || '—',
      p.bairro || '—',
      ''  // status desenhado à mão, como pílula
    ]);

    doc.autoTable({
      startY: y,
      head: [['#', 'Horário', 'Passageiro', 'Telefone', 'Ponto de Embarque', 'Bairro', 'Status']],
      body: rows,
      theme: 'plain',
      styles: {
        font: 'helvetica', fontSize: 8, cellPadding: { top: 2.6, bottom: 2.6, left: 2, right: 2 },
        textColor: PDF_COR.tinta, lineColor: PDF_COR.linha, lineWidth: 0,
        valign: 'middle', overflow: 'linebreak'
      },
      headStyles: {
        fillColor: PDF_COR.ambar, textColor: [255, 255, 255], fontStyle: 'bold',
        fontSize: 7.8, halign: 'left', cellPadding: { top: 3.6, bottom: 3.6, left: 2.4, right: 2.4 }
      },
      bodyStyles: { lineWidth: { bottom: 0.2 }, lineColor: PDF_COR.linha },
      // sem zebrado: o separador fino ja organiza a leitura
      alternateRowStyles: { fillColor: [255, 255, 255] },
      // 'avoid': se a linha nao cabe, ela inteira vai para a proxima pagina.
      // Sem isso o endereco parte no meio e a continuacao aparece orfa.
      rowPageBreak: 'avoid',
      // Somam 182mm (largura util). Telefone e Horario levam folga porque o
      // conteudo deles nao pode quebrar em duas linhas sem ficar ilegivel.
      columnStyles: {
        0: { cellWidth: 10, halign: 'center', textColor: PDF_COR.suave },
        1: { cellWidth: 17, halign: 'center', fontStyle: 'bold' },
        2: { cellWidth: 42 },
        3: { cellWidth: 25, fontSize: 7.6 },
        4: { cellWidth: 43 },
        5: { cellWidth: 23, fontSize: 7.8, textColor: PDF_COR.texto },
        6: { cellWidth: 22, halign: 'center' }
      },
      margin: { left: L, right: 210 - R, top: 24, bottom: 18 },
      didParseCell: function (d) {
        if (d.section === 'head' && d.column.index === 0) d.cell.styles.halign = 'center';
        if (d.section === 'head' && (d.column.index === 1 || d.column.index === 6)) d.cell.styles.halign = 'center';
      },
      didDrawCell: function (d) {
        if (d.section !== 'body' || d.column.index !== 6) return;
        const info = meta[d.row.index];
        if (!info) return;
        const rot = statusLabel[info.status] || info.status;

        // "Ativo" é o estado normal: sai como texto neutro, sem pastilha.
        // Colorir 13 linhas iguais de verde não informa nada e ainda faz a
        // tabela parecer listrada. A cor fica reservada para a exceção.
        if (info.status === 'ativo') {
          doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
          doc.setTextColor.apply(doc, PDF_COR.texto);
          doc.text(rot, d.cell.x + d.cell.width / 2, d.cell.y + d.cell.height / 2 + 1, { align: 'center' });
          return;
        }

        const cor = statusCor[info.status] || statusCor.ativo;
        const duas = !!info.retorno;
        const larguraPill = 19;
        const altura = duas ? 9 : 6;
        const px = d.cell.x + (d.cell.width - larguraPill) / 2;
        const py = d.cell.y + (d.cell.height - altura) / 2;
        doc.setFillColor.apply(doc, cor.bg);
        doc.setDrawColor.apply(doc, cor.txt);
        doc.setLineWidth(0.2);
        doc.roundedRect(px, py, larguraPill, altura, 1.6, 1.6, 'FD');
        doc.setTextColor.apply(doc, cor.txt);
        doc.setFont('helvetica', 'bold'); doc.setFontSize(7.6);
        doc.text(rot, px + larguraPill / 2, py + (duas ? 3.7 : 4), { align: 'center' });
        if (duas) {
          doc.setFont('helvetica', 'normal'); doc.setFontSize(6);
          doc.text('Retorno ' + info.retorno, px + larguraPill / 2, py + 7.3, { align: 'center' });
        }
      },
      didDrawPage: function (d) {
        const primeira = d.pageNumber === 1;
        if (!primeira) pdfCabecalho(doc, ctx, false);
        pdfRodapePagina(doc, ctx);
      }
    });

    // ---- rodapé com totais ----
    // Se o cartão inteiro não couber, vira uma faixa de uma linha. Mandar uma
    // folha quase vazia só para carregar o total é feio num documento que o
    // cliente recebe — e o gestor imprime isso todo dia.
    const cap = getCapacidade(rota);
    const ativos = sorted.filter(p => p.status === 'ativo').length;
    let fy = doc.lastAutoTable.finalY + 7;
    const espaco = 280 - fy;

    if (espaco < 12) { doc.addPage(); pdfCabecalho(doc, ctx, false); pdfRodapePagina(doc, ctx); fy = 30; }

    if (280 - fy < 24) {
      // faixa compacta
      doc.setFillColor.apply(doc, PDF_COR.fundo);
      doc.setDrawColor.apply(doc, PDF_COR.linha); doc.setLineWidth(0.3);
      doc.roundedRect(L, fy, R - L, 10, 2, 2, 'FD');
      doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
      doc.setTextColor.apply(doc, PDF_COR.tinta);
      doc.text(sorted.length + ' passageiros', L + 4, fy + 6.4);
      doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
      doc.setTextColor.apply(doc, PDF_COR.suave);
      doc.text('· ' + ativos + ' ativos · ' + cap + ' vagas', L + 30, fy + 6.4);
      doc.setFontSize(7);
      doc.text('Garagem: ' + GARAGEM, L + 66, fy + 4.4);
      doc.text('Destino: ' + DESTINO, L + 66, fy + 8);
      pdfFinalizarPaginas(doc, ctx, R);
      const turnoNumC = rota.turno.replace('°', '');
      const dataFileC = hojeLocal(now) + '_' +
        now.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }).replace(':', '');
      doc.save('L' + rota.linha + 'T' + turnoNumC + '_R' + rev + '_' + dataFileC + '.pdf');
      continue;
    }

    doc.setFillColor.apply(doc, PDF_COR.fundo);
    doc.setDrawColor.apply(doc, PDF_COR.linha); doc.setLineWidth(0.3);
    doc.roundedRect(L, fy, R - L, 22, 3, 3, 'FD');

    pdfIcone(doc, 'grupo', L + 6, fy + 7.5, 7);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
    doc.setTextColor.apply(doc, PDF_COR.suave);
    doc.text('Total de passageiros', L + 15, fy + 8);
    doc.setFont('helvetica', 'bold'); doc.setFontSize(15);
    doc.setTextColor.apply(doc, PDF_COR.tinta);
    doc.text(String(sorted.length), L + 15, fy + 16);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
    doc.setTextColor.apply(doc, PDF_COR.suave);
    doc.text(ativos + ' ativos · ' + cap + ' vagas', L + 26, fy + 15.4);

    doc.setDrawColor.apply(doc, PDF_COR.linha);
    doc.line(L + 58, fy + 4, L + 58, fy + 18);
    pdfIcone(doc, 'casa', L + 62, fy + 7.5, 7);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
    doc.setTextColor.apply(doc, PDF_COR.suave);
    doc.text('Garagem', L + 71, fy + 8);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
    doc.setTextColor.apply(doc, PDF_COR.tinta);
    doc.text(doc.splitTextToSize(GARAGEM, 54), L + 71, fy + 13);

    doc.setDrawColor.apply(doc, PDF_COR.linha);
    doc.line(L + 128, fy + 4, L + 128, fy + 18);
    pdfIcone(doc, 'pino', L + 132, fy + 7.5, 7);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
    doc.setTextColor.apply(doc, PDF_COR.suave);
    doc.text('Destino', L + 141, fy + 8);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
    doc.setTextColor.apply(doc, PDF_COR.tinta);
    doc.text(doc.splitTextToSize(DESTINO, 45), L + 141, fy + 13);

    pdfFinalizarPaginas(doc, ctx, R);

    const turnoNum = rota.turno.replace('°', '');
    const dataFile = hojeLocal(now) + '_' +
      now.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }).replace(':', '');
    const filename = 'L' + rota.linha + 'T' + turnoNum + '_R' + rev + '_' + dataFile + '.pdf';
    doc.save(filename);
  }
}

function exportAllPDF() {
  DATA.forEach(rota => exportPDF(rota.id));
}



function renderOptResult(opt, chegadaHora) {
  const body = document.getElementById('optResultBody');
  const alertas = opt.novasParadas.filter(p => p.alerta);
  const sg = opt.saidaGaragem || 0;
  const absG = ((sg % 1440) + 1440) % 1440;
  const saidaH = Math.floor(absG / 60).toString().padStart(2,'0');
  const saidaM = (absG % 60).toString().padStart(2,'0');

  let html = '<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px">';
  html += '<div class="report-stat"><div class="report-stat-num" style="color:var(--green)">' + opt.novasParadas.length + '</div><div class="report-stat-label">Paradas</div></div>';
  html += '<div class="report-stat"><div class="report-stat-num" style="color:var(--accent)">' + opt.totalDuration + 'min</div><div class="report-stat-label">Duração total</div></div>';
  html += '<div class="report-stat"><div class="report-stat-num" style="color:var(--accent2)">' + saidaH + ':' + saidaM + '</div><div class="report-stat-label">Saída Garagem</div></div>';
  html += '<div class="report-stat"><div class="report-stat-num" style="color:' + (alertas.length > 0 ? 'var(--red)' : 'var(--green)') + '">' + alertas.length + '</div><div class="report-stat-label">Alertas +60min</div></div>';
  html += '</div>';

  if (opt.passSemCoords && opt.passSemCoords.length > 0) {
    html += '<div style="background:rgba(245,158,11,0.08);border:1px solid rgba(245,158,11,0.3);border-radius:8px;padding:10px;margin-bottom:12px;font-size:12px;color:var(--accent)">Sem coordenadas: ' + opt.passSemCoords.map(p => p.nome.split(' ')[0]).join(', ') + '</div>';
  }

  html += '<div style="max-height:300px;overflow-y:auto">';
  opt.novasParadas.forEach((item, i) => {
    const alertHtml = item.alerta
      ? '<span class="alert-badge">' + item.minutosEmRota + 'min em rota</span>'
      : '<span style="font-size:10px;color:var(--muted)">' + item.minutosEmRota + 'min em rota</span>';
    html += '<div class="report-row">' +
      '<div class="report-time" style="font-weight:700;color:var(--accent);min-width:40px">' + (i+1) + '</div>' +
      '<div style="font-weight:600;font-size:13px;min-width:55px">' + item.horario + '</div>' +
      '<div style="flex:1"><div style="font-size:12px;font-weight:500">' + item.passageiro.nome + '</div>' + alertHtml + '</div>' +
    '</div>';
  });
  html += '</div>';
  body.innerHTML = html;
}

function aplicarOtimizacao() {
  if (!pendingOptimization || !pendingOptimization.ctx) return;
  const { rotaId, ctx, metrica, keepOrder, anterior } = pendingOptimization;
  const rota = DATA.find(r => r.id === rotaId);
  if (!rota) return;

  // ---- validacao antes de gravar ----
  const erros = [];
  const nomesNaRota = metrica.ordem.reduce((acc, pi) => acc.concat(ctx.pontos[pi].nomes), []);
  const ativos = rota.passageiros.filter(p => p.status === 'ativo' && (p.endereco || p.embarque));
  if (new Set(metrica.ordem).size !== metrica.ordem.length) erros.push('sequência com ponto repetido');
  if (metrica.ordem.length !== ctx.pontos.length) erros.push('faltam pontos na sequência');
  if (nomesNaRota.length !== ativos.length) erros.push('a quantidade de passageiros não confere');
  ativos.forEach(p => { if (nomesNaRota.indexOf(p.nome) < 0) erros.push('passageiro fora da sequência: ' + p.nome); });
  if (new Set(nomesNaRota).size !== nomesNaRota.length) erros.push('passageiro duplicado na sequência');
  if (erros.length) {
    setOptStatus('Não apliquei: ' + erros.join('; ') + '. A rota continua como estava.', 'error');
    return;
  }
  if (!OPT_CFG.permitirAcimaDoLimite && metrica.violacoes > 0 &&
      !confirm('Esta rota deixa ' + metrica.violacoes + ' passageiro(s) acima de ' +
               OPT_CFG.maxRideMin + ' min em viagem.\n\nAplicar mesmo assim?')) return;

  const cap = getCapacidade(rota);
  if (nomesNaRota.length > cap &&
      !confirm('Esta linha ficará com ' + nomesNaRota.length + ' passageiros para ' + cap +
               ' vagas.\n\nAplicar mesmo assim?')) return;

  // ---- aplica em copia; so grava se tudo der certo ----
  const backup = rota.passageiros.map(p => ({ nome: p.nome, horario: p.horario, ordem: p.ordem }));
  try {
    metrica.ordem.forEach((pi, k) => {
      const hora = otHHMM(metrica.embarqueMin[k]);
      ctx.pontos[pi].nomes.forEach(nome => {
        const p = rota.passageiros.find(x => x.nome === nome);
        if (!p) throw new Error('passageiro sumiu durante a aplicação: ' + nome);
        p.horario = hora;
        if (!keepOrder) p.ordem = k + 1;
      });
    });
  } catch (e) {
    backup.forEach(b => {
      const p = rota.passageiros.find(x => x.nome === b.nome);
      if (p) { p.horario = b.horario; p.ordem = b.ordem; }
    });
    setOptStatus('Falha ao aplicar: ' + e.message + '. Nada foi alterado.', 'error');
    return;
  }

  // ---- auditoria ----
  const nomesOrdem = o => o.map(i => ctx.pontos[i].nomes.join('+')).join(' → ');
  if (keepOrder) {
    logChange('alteracao', 'Linha ' + rota.linha + ' ' + rota.turno,
      'Horários anteriores', 'Horários recalculados (ordem mantida)',
      metrica.durMin + ' min · saída ' + otHHMM(metrica.saidaGaragem));
  } else {
    logChange('alteracao', 'Linha ' + rota.linha + ' ' + rota.turno,
      nomesOrdem(anterior.ordem) + ' · ' + anterior.durMin + ' min / ' + (Math.round(anterior.distKm * 10) / 10) + ' km',
      nomesOrdem(metrica.ordem) + ' · ' + metrica.durMin + ' min / ' + (Math.round(metrica.distKm * 10) / 10) + ' km',
      'Rota otimizada · economia de ' + (anterior.durMin - metrica.durMin) + ' min e ' +
      (Math.round((anterior.distKm - metrica.distKm) * 10) / 10) + ' km · ' +
      metrica.violacoes + ' acima de ' + OPT_CFG.maxRideMin + ' min');
  }

  saveAfterChange();
  document.getElementById('modalOtimizar').classList.remove('open');
  selectLine(rotaId);
  pendingOptimization = null;
}



// ---- API KEY CONFIG ----
let MAPS_API_KEY = '';

// ---------------------------------------------------------------------------
// CHAVE DO GOOGLE MAPS
// Infraestrutura da temvia, nao configuracao da operacao. A fonte e a casca
// (arquivo do repositorio, so a temvia edita). Nao ha editor em tela nenhuma.
//
// TRANSICAO: enquanto houver casca sem `mapsKey`, o Firestore e o localStorage
// continuam valendo como reserva de LEITURA, com aviso no console. Remover as
// duas reservas assim que todas as operacoes estiverem publicadas.
// ---------------------------------------------------------------------------
function chaveFirebaseLocal() {
  try { return (C && C.fb && C.fb.apiKey) || ''; } catch (e) { return ''; }
}

function chaveDaCasca() {
  try {
    var k = window.CLIENTE_CONFIG && window.CLIENTE_CONFIG.mapsKey;
    return (typeof k === 'string' && k.indexOf('AIza') === 0) ? k : '';
  } catch (e) { return ''; }
}

function getApiKey() {
  if (MAPS_API_KEY) return MAPS_API_KEY;

  var daCasca = chaveDaCasca();
  if (daCasca) { MAPS_API_KEY = daCasca; return MAPS_API_KEY; }

  // --- reserva temporaria ---
  var cache = '';
  try { cache = localStorage.getItem('redentor_maps_key') || ''; } catch (e) {}
  if (cache && cache !== chaveFirebaseLocal()) {
    console.warn('[temvia] Chave do Maps veio do cache local. ' +
                 'Publique mapsKey na casca desta operacao.');
    MAPS_API_KEY = cache;
  } else if (cache === chaveFirebaseLocal()) {
    // Cache corrompido de versoes antigas guardava a chave do Firebase aqui.
    try { localStorage.removeItem('redentor_maps_key'); } catch (e) {}
  }
  return MAPS_API_KEY;
}

// ---------------- Configurações > Otimização de rotas ----------------
// A tela só lê e escreve OPT_CFG. Nenhuma regra vive aqui dentro.

function ocPreencher() {
  const set = (id, v) => { const el = document.getElementById(id); if (el) el.value = v; };
  const chk = (id, v) => { const el = document.getElementById(id); if (el) el.checked = !!v; };
  set('ocMaxRide', OPT_CFG.maxRideMin);
  set('ocMargem', OPT_CFG.margemChegadaMin);
  set('ocParada', OPT_CFG.stopServiceSeconds);
  set('ocAdicional', OPT_CFG.extraPassengerSeconds);
  set('ocTolerancia', OPT_CFG.coordToleranceMeters);
  set('ocReserva', OPT_CFG.reservaVagas);
  set('ocGanhoMin', Math.round((OPT_CFG.minGanhoSegundos / 60) * 10) / 10);
  set('ocGanhoKm', Math.round((OPT_CFG.minGanhoMetros / 1000) * 10) / 10);
  chk('ocAgrupar', OPT_CFG.agruparPontos);
  chk('ocPreservar', OPT_CFG.preservarOrdem);
  chk('ocPermitirAcima', OPT_CFG.permitirAcimaDoLimite);
  const r = document.querySelector('input[name="ocObjetivo"][value="' + OPT_CFG.objetivo + '"]');
  if (r) r.checked = true;
  ocAtualizarDependentes();
}

// Campo que não vale nada sem o interruptor ligado fica apagado, em vez de
// aceitar um número que o sistema vai ignorar.
function ocAtualizarDependentes() {
  const agr = document.getElementById('ocAgrupar');
  const box = document.getElementById('ocTolBox');
  if (agr && box) {
    box.style.opacity = agr.checked ? '1' : '.45';
    const t = document.getElementById('ocTolerancia');
    if (t) t.disabled = !agr.checked;
  }
  const pres = document.getElementById('ocPreservar');
  const gbox = document.getElementById('ocGanhoBox');
  if (pres && gbox) {
    gbox.style.opacity = pres.checked ? '1' : '.45';
    ['ocGanhoMin', 'ocGanhoKm'].forEach(id => {
      const el = document.getElementById(id); if (el) el.disabled = !pres.checked;
    });
  }
}

function ocMsg(txt, erro) {
  const el = document.getElementById('ocMsg');
  if (!el) return;
  el.textContent = txt || '';
  el.className = 'opt-status' + (txt ? (erro ? ' error' : ' success') : '');
}

async function ocSalvar() {
  const v = id => (document.getElementById(id) || {}).value;
  const c = id => !!(document.getElementById(id) || {}).checked;
  const objetivoEl = document.querySelector('input[name="ocObjetivo"]:checked');

  // Monta e valida pelo mesmo caminho que a carga da nuvem usa: um valor
  // recusado aqui é o mesmo valor que seria recusado lá.
  const bruto = {
    maxRideMin: Number(v('ocMaxRide')),
    margemChegadaMin: Number(v('ocMargem')),
    stopServiceSeconds: Number(v('ocParada')),
    extraPassengerSeconds: Number(v('ocAdicional')),
    coordToleranceMeters: Number(v('ocTolerancia')),
    reservaVagas: Number(v('ocReserva')),
    minGanhoSegundos: Math.round(Number(v('ocGanhoMin')) * 60),
    minGanhoMetros: Math.round(Number(v('ocGanhoKm')) * 1000),
    agruparPontos: c('ocAgrupar'),
    preservarOrdem: c('ocPreservar'),
    permitirAcimaDoLimite: c('ocPermitirAcima'),
    objetivo: objetivoEl ? objetivoEl.value : OPT_CFG.objetivo
  };
  optAplicarConfig(bruto);
  const aceito = optConfigParaSalvar();
  // Comparar campo a campo, não JSON.stringify: os dois objetos têm as mesmas
  // chaves em ORDEM diferente, e comparar as strings acusava divergência
  // mesmo quando nada tinha sido recusado.
  const rotulos = {
    maxRideMin: 'Tempo máximo em rota', margemChegadaMin: 'Margem de chegada',
    stopServiceSeconds: 'Tempo por parada', extraPassengerSeconds: 'Adicional por passageiro',
    coordToleranceMeters: 'Distância para mesmo ponto', minGanhoSegundos: 'Ganho mínimo de tempo',
    minGanhoMetros: 'Ganho mínimo de distância', agruparPontos: 'Agrupar passageiros',
    preservarOrdem: 'Manter a ordem atual', permitirAcimaDoLimite: 'Aplicar sem confirmar', reservaVagas: 'Reserva de vagas',
    objetivo: 'Objetivo'
  };
  const recusados = Object.keys(aceito).filter(k => aceito[k] !== bruto[k]);
  if (recusados.length) {
    ocMsg('Fora do intervalo, voltou ao padrão: ' +
          recusados.map(k => rotulos[k] || k).join(', ') + '.', true);
    ocPreencher();
  }

  // A matriz guardada foi calculada com as regras antigas: descartar evita
  // comparar rota nova com base velha.
  if (typeof optLimparCacheMatriz === 'function') optLimparCacheMatriz();

  try {
    if (!fbDb) await initFirebase();
    if (!fbDb) { ocMsg('Salvo nesta sessão, mas o servidor está indisponível.', true); return; }
    const { setDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    await setDoc(doc(fbDb, CLIENTE_ID, 'config'),
      { otimizacao: optConfigParaSalvar(), updatedAt: new Date().toISOString() }, { merge: true });
    if (!recusados.length) ocMsg('Regras de otimização salvas.', false);
    logChange('alteracao', 'Otimização de rotas', '—',
      'máx ' + OPT_CFG.maxRideMin + ' min · margem ' + OPT_CFG.margemChegadaMin +
      ' min · objetivo ' + OPT_CFG.objetivo, '');
  } catch (e) {
    ocMsg('Salvo nesta sessão (erro ao gravar no servidor: ' + e.message + ')', true);
  }
}

function ocRestaurarPadroes() {
  if (!confirm('Voltar todas as regras de otimização aos valores padrão da temvia?')) return;
  optAplicarConfig(null);
  ocPreencher();
  ocMsg('Padrões restaurados. Clique em salvar para gravar no servidor.', false);
}

// A coluna agrupa as seções que já existem: marca cada bloco com a seção a
// que pertence e mostra uma de cada vez. Sem reescrever o conteúdo — só a
// navegação, que é onde estava o problema.
const CFG_SECOES = [["oper", "Operação", "Dados da empresa e horários dos turnos", ["DADOS DA EMPRESA", "Horários de chegada por turno"]], ["pontos", "Pontos", "Origem e destino das rotas", ["Pontos de origem e destino"]], ["frota", "Frota", "Veículos e capacidades", ["Frota"]], ["otim", "Otimização", "Regras do planejamento de rotas", ["Otimização de rotas"]], ["acesso", "Acesso", "Chave do Google Maps e logins", ["GOOGLE MAPS API KEY", "LOGINS DA EMPRESA CLIENTE"]], ["dados", "Dados", "Backup e restauração", []]];
let CFG_ATUAL = 'oper';

function cfgClassificar() {
  const cont = document.getElementById('cfgConteudo');
  if (!cont || cont.dataset.pronto) return;

  // Passo 1: herança pelo título. Serve para os campos, que não têm ação.
  const alvos = {};
  CFG_SECOES.forEach(([k, , , lista]) => lista.forEach(a => { alvos[a.toLowerCase()] = k; }));
  const pais = new Set();
  cont.querySelectorAll('.opt-title').forEach(t => pais.add(t.parentElement));
  let sec = 'oper';
  pais.forEach(pai => {
    [...pai.children].forEach(el => {
      if (el.classList.contains('opt-title')) {
        const txt = (el.textContent || '').trim().toLowerCase();
        const achou = Object.keys(alvos).find(a => txt.indexOf(a) === 0);
        if (achou) sec = alvos[achou];
      }
      el.dataset.sec = sec;
    });
  });

  // Passo 2: quem TEM ação é classificado pela ação, não pela posição.
  // Herdar do título anterior punha "Salvar dados da empresa" em Pontos e
  // "Restaurar padrões" em Dados — só porque vinham depois na página.
  const porAcao = {
    criarAcessoCliente: 'acesso',
    salvarEmpresaConfig: 'oper',
    ptSalvar: 'pontos', ptCancelar: 'pontos',
    frSalvar: 'frota', frCancelar: 'frota',
    ocSalvar: 'otim', ocRestaurarPadroes: 'otim',
    exportBackup: 'dados', importBackup: 'dados'
  };
  [...cont.querySelectorAll('*')].forEach(el => {
    const acoes = [el].concat([...el.querySelectorAll('[onclick],[onchange]')])
      .map(x => (x.getAttribute && (x.getAttribute('onclick') || x.getAttribute('onchange'))) || '')
      .join(' ');
    const achadas = Object.keys(porAcao).filter(fn => acoes.indexOf(fn + '(') >= 0);
    // só decide quando todas as ações do bloco pertencem à MESMA seção
    const secs = [...new Set(achadas.map(fn => porAcao[fn]))];
    if (secs.length === 1) el.dataset.sec = secs[0];
  });

  // Passo 3: marcação explícita vence tudo.
  cont.querySelectorAll('[data-sec-fixa]').forEach(el => { el.dataset.sec = el.dataset.secFixa; });

  [...cont.children].forEach(el => { if (!el.dataset.sec) el.dataset.sec = 'oper'; });
  cont.dataset.pronto = '1';
}

function cfgIr(k) {
  if (CFG_ATUAL !== k) ['ocMsg', 'ptMsg', 'frMsg'].forEach(id => {
    const el = document.getElementById(id); if (el) el.textContent = '';
  });
  CFG_ATUAL = k;
  cfgClassificar();
  const cont = document.getElementById('cfgConteudo');
  // Duas regras, nesta ordem:
  //  1. cada bloco marcado aparece só na sua seção;
  //  2. quem é apenas caminho até um bloco visível reabre.
  // Sem a regra 2, os contêineres somem e levam o conteúdo junto. Sem a
  // regra 1, um contêiner visível arrasta irmãos de outras seções — foi
  // assim que o backup apareceu dentro de Otimização.
  if (cont) {
    cont.querySelectorAll('[data-sec]').forEach(el => {
      el.style.display = (el.dataset.sec === k) ? '' : 'none';
    });
    cont.querySelectorAll('[data-sec="' + k + '"]').forEach(el => {
      let n = el.parentElement;
      // .cfg-oculto e escondido de proposito: campos legados que so existem
      // para o salvar continuar lendo. Reabri-los mostrava coordenada solta.
      while (n && n !== cont) {
        if (!n.classList.contains('cfg-oculto')) n.style.display = '';
        n = n.parentElement;
      }
    });
    [...cont.children].forEach(el => {
      if (el.dataset.sec === k) return;
      if (!el.querySelector('[data-sec="' + k + '"]')) el.style.display = 'none';
    });
  }
  document.querySelectorAll('.cfg-passo').forEach(b =>
    b.classList.toggle('on', b.dataset.sec === k));
  const body = cont && cont.closest('.modal-body');
  if (body) body.scrollTop = 0;
}

function cfgCabecalho() {
  const el = document.getElementById('cfgTopo');
  if (!el) return;
  const op = tvOperacoesIrmas().find(o => o.id === C.clienteId);
  el.innerHTML = '<span>Estas configurações valem para</span><b>' +
    esc((op && op.nome) || C.empresaNome || C.marca) + '</b>' +
    '<code>' + esc(C.clienteId) + '</code>';
}

function openConfig() {
  tnLimparForm();
  tnRenderLista();
  try { tnAplicarNoSistema(); } catch (e) {}
  // Aviso de "salvo" é de um clique específico. Ao reabrir a tela ele não
  // vale mais — ficava lá dizendo que algo foi salvo agora há pouco.
  ['ocMsg', 'ptMsg', 'frMsg', 'cfgMsg', 'apiKeyMsg'].forEach(id => {
    const el = document.getElementById(id);
    if (el) { el.textContent = ''; el.className = el.className.replace(/\b(success|error)\b/g, ''); }
  });
  cfgCabecalho();
  cfgIr(CFG_ATUAL);
  ocPreencher();
  ptLimparForm();
  ptRenderLista();
  try { ptSemear(); ptAplicarNoSistema(); } catch (e) {}
  try { const _op = document.getElementById('cfgOperacaoNome');
        if (_op) _op.value = EMPRESA_CONFIG.operacaoNome || ''; } catch (e) {}
  frLimparForm();
  frRenderLista();
  // Preencher campos de Dados da Empresa com os valores atuais
  try {
    const c = EMPRESA_CONFIG;
    const set = (id, val) => { const el = document.getElementById(id); if (el) el.value = val; };
    set('cfgNome', c.nome || '');
    set('cfgWhatsCliente', c.whatsCliente || '');
    set('cfgWhatsRedentor', c.whatsRedentor || '');
    set('cfgSenhaCliente', c.senhaCliente || '');
    set('cfgT1', c.turnosChegada['1°'] || '');
    set('cfgT2', c.turnosChegada['2°'] || '');
    set('cfgT3', c.turnosChegada['3°'] || '');
    set('cfgTA', c.turnosChegada['ADM'] || '');
    set('cfgGarCoords', (c.garagem.lat != null ? c.garagem.lat + ', ' + c.garagem.lng : ''));
    set('cfgDestCoords', (c.destino.lat != null ? c.destino.lat + ', ' + c.destino.lng : ''));
  } catch(e) {}
  document.getElementById('modalConfig').classList.add('open');
}

// 1E: salva os dados da empresa (nome, horários, coordenadas) no config do Firebase
// ---------------- Cadastro de turnos (Config > Operação) ----------------
// Compacto: o turno normal ocupa duas linhas. Só o que difere do padrão
// aparece — sete dias por turno em quatro turnos seriam 28 linhas na tela.

let tnEditandoId = null;
let tnRascunhoDias = {};      // exceções em edição
let tnRascunhoAlt = null;     // alternância em edição

function tnResumo(t) {
  const partes = [];
  DIAS_SEMANA.forEach(d => {
    const r = t.dias[d];
    if (r === false) partes.push(DIAS_NOME[d] + ' não opera');
    else if (r && typeof r === 'object') {
      const p = [];
      if (r.chegada) p.push('chega ' + r.chegada);
      if (r.saida) p.push('sai ' + r.saida);
      if (p.length) partes.push(DIAS_NOME[d] + ' ' + p.join(' e '));
    }
  });
  if (t.alternado && t.alternado.dia) {
    partes.push(DIAS_NOME[t.alternado.dia] + ' a cada ' + (t.alternado.semanas || 2) +
      ' semanas' + (t.alternado.desde ? ' desde ' + tnDataBr(t.alternado.desde) : ''));
  }
  return partes.length ? partes.join(' · ') : 'Todos os dias no horário padrão';
}
function tnDataBr(iso) {
  const m = String(iso).match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? (m[3] + '/' + m[2]) : iso;
}

function tnRenderLista() {
  const box = document.getElementById('tnLista');
  if (!box) return;
  turnosSemear();
  if (!TURNOS.length) {
    box.innerHTML = '<div style="font-size:12px;color:var(--muted);padding:10px;' +
      'border:1px dashed var(--border);border-radius:10px">Nenhum turno cadastrado.</div>';
    return;
  }
  box.innerHTML = TURNOS.map(t =>
    '<div class="fr-item">' +
      '<div style="flex:1;min-width:0">' +
        '<div style="font-weight:600;font-size:13px">' + esc(t.nome) + '</div>' +
        '<div style="font-size:11.5px;color:var(--muted)">' + esc(tnResumo(t)) + '</div>' +
      '</div>' +
      '<div class="fr-cap" style="font-size:11px;font-weight:600">' +
        (t.chegada || '—') + '<span>' + (t.saida || 'sem saída') + '</span></div>' +
      '<button onclick="tnEditar(\'' + t.id + '\')" class="ico-btn ico-editar" title="Editar turno" aria-label="Editar turno"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M4 20h4L19 9a2.1 2.1 0 0 0-3-3L5 17v3Z"/><path d="M14.5 6.5 17.5 9.5"/></svg></button>' +
      '<button onclick="tnExcluir(\'' + t.id + '\')" class="ico-btn ico-excluir" title="Excluir turno" aria-label="Excluir turno"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M4 7h16M9.5 7V5h5v2M6.5 7l.8 13h9.4l.8-13"/><path d="M10 11v6M14 11v6"/></svg></button>' +
    '</div>').join('');
}

// As exceções só aparecem quando existem. O botão de acrescentar fica sempre.
function tnRenderExcecoes() {
  const box = document.getElementById('tnExcecoes');
  if (!box) return;
  let h = '<div class="tn-exc-tit">Exceções por dia <span>o que difere do horário padrão</span></div>';
  const linhas = [];
  DIAS_SEMANA.forEach(d => {
    const r = tnRascunhoDias[d];
    if (r === undefined) return;
    linhas.push('<div class="tn-exc">' +
      '<b>' + DIAS_NOME[d] + '</b>' +
      '<select class="form-input" onchange="tnMudarTipo(\'' + d + '\', this.value)">' +
        '<option value="horario"' + (r !== false ? ' selected' : '') + '>Horário próprio</option>' +
        '<option value="folga"' + (r === false ? ' selected' : '') + '>Não opera</option>' +
      '</select>' +
      (r === false ? '<span class="tn-exc-obs">nenhuma rota neste dia</span>' :
        '<input class="form-input" type="time" value="' + ((r && r.chegada) || '') + '" ' +
          'onchange="tnMudarHora(\'' + d + '\', \'chegada\', this.value)" title="Chegada">' +
        '<input class="form-input" type="time" value="' + ((r && r.saida) || '') + '" ' +
          'onchange="tnMudarHora(\'' + d + '\', \'saida\', this.value)" title="Saída">') +
      '<button class="ico-btn ico-excluir" onclick="tnRemoverExcecao(\'' + d + '\')" ' +
        'title="Remover exceção" aria-label="Remover exceção">×</button>' +
      '</div>');
  });
  h += linhas.length ? linhas.join('') :
    '<div class="tn-exc-vazio">Nenhuma exceção: todos os dias usam o horário padrão.</div>';

  h += '<div class="tn-exc-add">' +
    '<select class="form-input" id="tnNovoDia">' +
      DIAS_SEMANA.filter(d => tnRascunhoDias[d] === undefined)
        .map(d => '<option value="' + d + '">' + DIAS_NOME[d] + '</option>').join('') +
    '</select>' +
    '<button class="export-btn" onclick="tnAddExcecao()">Acrescentar exceção</button>' +
    '</div>';

  // alternância
  const alt = tnRascunhoAlt || {};
  h += '<div class="tn-exc-tit" style="margin-top:12px">Dia alternado ' +
       '<span>sábado sim, sábado não — e o outro turno na semana seguinte</span></div>';
  h += '<div class="tn-alt">' +
    '<label class="pl-check"><input type="checkbox" id="tnAltOn"' + (tnRascunhoAlt ? ' checked' : '') +
      ' onchange="tnAltToggle()"> Este turno opera em semanas alternadas num dia</label>' +
    (tnRascunhoAlt ?
      '<div class="tn-alt-campos">' +
        '<select class="form-input" onchange="tnAltCampo(\'dia\', this.value)">' +
          DIAS_SEMANA.map(d => '<option value="' + d + '"' + (alt.dia === d ? ' selected' : '') +
            '>' + DIAS_NOME[d] + '</option>').join('') +
        '</select>' +
        '<span>a cada</span>' +
        '<input class="form-input" type="number" min="1" max="8" value="' + (alt.semanas || 2) + '" ' +
          'onchange="tnAltCampo(\'semanas\', this.value)" style="width:64px">' +
        '<span>semanas, a partir de</span>' +
        '<input class="form-input" type="date" value="' + (alt.desde || '') + '" ' +
          'onchange="tnAltCampo(\'desde\', this.value)">' +
      '</div>' +
      '<div class="tn-exc-vazio">Escolha um dia em que este turno realmente opera. Para revezar ' +
      'com outro turno, use a mesma data mais uma semana no outro.</div>'
      : '') +
    '</div>';
  box.innerHTML = h;
}

function tnAddExcecao() {
  const d = (document.getElementById('tnNovoDia') || {}).value;
  if (!d) return;
  tnRascunhoDias[d] = { chegada: '', saida: '' };
  tnRenderExcecoes();
}
function tnRemoverExcecao(d) { delete tnRascunhoDias[d]; tnRenderExcecoes(); }
function tnMudarTipo(d, v) {
  tnRascunhoDias[d] = (v === 'folga') ? false : { chegada: '', saida: '' };
  tnRenderExcecoes();
}
function tnMudarHora(d, campo, v) {
  if (!tnRascunhoDias[d] || typeof tnRascunhoDias[d] !== 'object') tnRascunhoDias[d] = {};
  tnRascunhoDias[d][campo] = v;
}
function tnAltToggle() {
  const on = (document.getElementById('tnAltOn') || {}).checked;
  tnRascunhoAlt = on ? { dia: 'sab', semanas: 2, desde: '' } : null;
  tnRenderExcecoes();
}
function tnAltCampo(campo, v) {
  if (!tnRascunhoAlt) return;
  tnRascunhoAlt[campo] = (campo === 'semanas') ? (parseInt(v, 10) || 2) : v;
}

function tnMsg(txt, erro) {
  const el = document.getElementById('tnMsg');
  if (!el) return;
  el.textContent = txt || '';
  el.style.color = erro ? 'var(--red)' : 'var(--green)';
}

function tnLimparForm() {
  tnEditandoId = null;
  tnRascunhoDias = {};
  tnRascunhoAlt = null;
  ['tnNome', 'tnChegada', 'tnSaida'].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
  const b = document.getElementById('tnBtnSalvar'); if (b) b.textContent = 'Adicionar turno';
  const c = document.getElementById('tnBtnCancelar'); if (c) c.style.display = 'none';
  tnRenderExcecoes();
}
function tnCancelar() { tnLimparForm(); tnMsg(''); }

function tnEditar(id) {
  const t = TURNOS.find(x => x.id === id);
  if (!t) return;
  tnEditandoId = id;
  document.getElementById('tnNome').value = t.nome || '';
  document.getElementById('tnChegada').value = t.chegada || '';
  document.getElementById('tnSaida').value = t.saida || '';
  tnRascunhoDias = JSON.parse(JSON.stringify(t.dias || {}));
  tnRascunhoAlt = t.alternado ? JSON.parse(JSON.stringify(t.alternado)) : null;
  document.getElementById('tnBtnSalvar').textContent = 'Salvar alterações';
  document.getElementById('tnBtnCancelar').style.display = '';
  tnRenderExcecoes();
  tnMsg('Editando ' + t.nome + '.', false);
  const campo = document.getElementById('tnNome');
  if (campo) campo.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

function tnSalvar() {
  const nome = (document.getElementById('tnNome').value || '').trim();
  const chegada = document.getElementById('tnChegada').value;
  const saida = document.getElementById('tnSaida').value;
  if (!nome) { tnMsg('Dê um nome ao turno.', true); return; }
  if (!chegada && !saida) { tnMsg('Informe ao menos um horário: chegada ou saída.', true); return; }
  const repetido = TURNOS.find(t => t.nome === nome && t.id !== tnEditandoId);
  if (repetido) { tnMsg('Já existe um turno chamado "' + nome + '".', true); return; }
  if (tnRascunhoAlt && !tnRascunhoAlt.desde) {
    tnMsg('O dia alternado precisa de uma data de referência — um dia em que ele realmente opera.', true);
    return;
  }

  const dados = { nome: nome, chegada: chegada, saida: saida,
                  dias: tnRascunhoDias, alternado: tnRascunhoAlt };
  if (tnEditandoId) {
    const t = TURNOS.find(x => x.id === tnEditandoId);
    const antigo = t.nome;
    Object.assign(t, dados);
    // renomear turno mexeria nas linhas: por ora, mantemos o nome ligado
    if (antigo !== nome) {
      DATA.forEach(r => { if (r.turno === antigo) r.turno = nome; });
      logChange('alteracao', 'Turno ' + antigo, antigo, nome, 'Renomeado nas linhas também');
    }
    logChange('alteracao', 'Turno ' + nome, '—', tnResumo(t), '');
  } else {
    TURNOS.push(Object.assign({ id: 'tn' + Date.now().toString(36) }, dados));
    logChange('inclusao', 'Turno ' + nome, '—', 'Novo turno cadastrado', '');
  }
  tnAplicarNoSistema();
  tnSalvarNaNuvem();
  tnLimparForm();
  tnRenderLista();
  tnMsg('Turnos atualizados.', false);
}

function tnExcluir(id) {
  const t = TURNOS.find(x => x.id === id);
  if (!t) return;
  const emUso = DATA.filter(r => r.turno === t.nome).length;
  if (emUso) {
    tnMsg('Não dá para excluir: ' + emUso + ' linha(s) usam o turno "' + t.nome + '".', true);
    return;
  }
  if (!confirm('Excluir o turno ' + t.nome + '?')) return;
  TURNOS = TURNOS.filter(x => x.id !== id);
  logChange('exclusao', 'Turno ' + t.nome, t.nome, '—', '');
  tnAplicarNoSistema();
  tnSalvarNaNuvem();
  tnRenderLista();
  tnMsg('Turno removido.', false);
}

// Sete lugares do sistema leem TURNOS_CHEGADA. Mantê-lo em sincronia é o que
// permite trocar o modelo sem reescrever todos eles de uma vez.
function tnAplicarNoSistema() {
  Object.keys(TURNOS_CHEGADA).forEach(k => { delete TURNOS_CHEGADA[k]; });
  TURNOS.forEach(t => { TURNOS_CHEGADA[t.nome] = t.chegada || ''; });
  // e os campos escondidos que salvarEmpresaConfig ainda lê
  const par = [['cfgT1', '1°'], ['cfgT2', '2°'], ['cfgT3', '3°'], ['cfgTA', 'ADM']];
  par.forEach(([id, nome]) => {
    const el = document.getElementById(id);
    if (el) el.value = TURNOS_CHEGADA[nome] || '';
  });
}

async function tnSalvarNaNuvem() {
  try {
    if (!fbDb) await initFirebase();
    if (!fbDb) { tnMsg('Salvo nesta sessão, mas o servidor está indisponível.', true); return; }
    const { setDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    await setDoc(doc(fbDb, CLIENTE_ID, 'config'),
      { turnos: TURNOS, updatedAt: new Date().toISOString() }, { merge: true });
  } catch (e) {
    tnMsg('Salvo nesta sessão (erro ao gravar no servidor: ' + e.message + ')', true);
  }
}

// ---------------- Cadastro de pontos (Config) ----------------
// Origem e destino deixam de ser duas variaveis presas no codigo. Enquanto os
// seletores por rota nao chegam, a garagem e o destino do sistema continuam
// vindo daqui — o cadastro e a fonte, nao uma copia.
let PONTOS = [];
let ptEditandoId = null;

function ptSemear() {
  if (PONTOS.length) return;
  const g = EMPRESA_CONFIG.garagem, d = EMPRESA_CONFIG.destino;
  if (g && g.lat) PONTOS.push({ id: 'pt-garagem', nome: 'Garagem', tipo: 'garagem',
    endereco: g.endereco || '', lat: g.lat, lng: g.lng });
  if (d && d.lat) PONTOS.push({ id: 'pt-destino', nome: d.nome || 'Empresa', tipo: 'empresa',
    endereco: d.endereco || '', lat: d.lat, lng: d.lng });
}

function ptRenderLista() {
  const box = document.getElementById('ptLista');
  if (!box) return;
  ptSemear();
  if (!PONTOS.length) {
    box.innerHTML = '<div style="font-size:12px;color:var(--muted);padding:10px;border:1px dashed var(--border);border-radius:10px">' +
      'Nenhum ponto cadastrado.</div>';
    return;
  }
  const rot = { garagem: 'Garagem', empresa: 'Empresa atendida', outro: 'Outro' };
  box.innerHTML = PONTOS.map(p =>
    '<div class="fr-item">' +
      '<div style="flex:1;min-width:0">' +
        '<div style="font-weight:600;font-size:13px">' + esc(p.nome) + '</div>' +
        '<div style="font-size:11.5px;color:var(--muted)">' + (rot[p.tipo] || p.tipo) +
          (p.endereco ? ' · ' + esc(p.endereco) : '') + '</div>' +
      '</div>' +
      '<div class="fr-cap" style="font-size:11px;font-weight:500">' +
        p.lat.toFixed(4) + '<span>' + p.lng.toFixed(4) + '</span></div>' +
      '<button onclick="ptEditar(\'' + p.id + '\')" class="ico-btn ico-editar" title="Editar ponto" aria-label="Editar ponto"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M4 20h4L19 9a2.1 2.1 0 0 0-3-3L5 17v3Z"/><path d="M14.5 6.5 17.5 9.5"/></svg></button>' +
      '<button onclick="ptExcluir(\'' + p.id + '\')" class="ico-btn ico-excluir" title="Excluir ponto" aria-label="Excluir ponto"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M4 7h16M9.5 7V5h5v2M6.5 7l.8 13h9.4l.8-13"/><path d="M10 11v6M14 11v6"/></svg></button>' +
    '</div>').join('');
}

function ptMsg(txt, erro) {
  const el = document.getElementById('ptMsg');
  if (!el) return;
  el.textContent = txt || '';
  el.style.color = erro ? 'var(--red)' : 'var(--green)';
}

function ptLimparForm() {
  ptEditandoId = null;
  ['ptNome', 'ptEndereco', 'ptCoords'].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
  const t = document.getElementById('ptTipo'); if (t) t.value = 'outro';
  const b = document.getElementById('ptBtnSalvar'); if (b) b.textContent = 'Adicionar ponto';
  const c = document.getElementById('ptBtnCancelar'); if (c) c.style.display = 'none';
}
function ptCancelar() { ptLimparForm(); ptMsg(''); }

function ptEditar(id) {
  const p = PONTOS.find(x => x.id === id);
  if (!p) return;
  ptEditandoId = id;
  document.getElementById('ptNome').value = p.nome || '';
  document.getElementById('ptEndereco').value = p.endereco || '';
  document.getElementById('ptCoords').value = p.lat + ', ' + p.lng;
  document.getElementById('ptTipo').value = p.tipo || 'outro';
  document.getElementById('ptBtnSalvar').textContent = 'Salvar alterações';
  document.getElementById('ptBtnCancelar').style.display = '';
  ptMsg('Editando ' + p.nome + '. Os campos abaixo já estão preenchidos.', false);
  const campo = document.getElementById('ptNome');
  if (campo) campo.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

function ptSalvar() {
  const nome = (document.getElementById('ptNome').value || '').trim();
  const endereco = (document.getElementById('ptEndereco').value || '').trim();
  const coords = (document.getElementById('ptCoords').value || '').trim();
  const tipo = document.getElementById('ptTipo').value;
  if (!nome) { ptMsg('Dê um nome ao ponto.', true); return; }
  const m = coords.match(/^\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*$/);
  if (!m) { ptMsg('Coordenadas no formato "-23.5146, -47.5167".', true); return; }
  const lat = parseFloat(m[1]), lng = parseFloat(m[2]);
  if (lat < -90 || lat > 90 || lng < -180 || lng > 180) { ptMsg('Coordenadas fora do intervalo válido.', true); return; }

  if (ptEditandoId) {
    const p = PONTOS.find(x => x.id === ptEditandoId);
    if (!p) { ptMsg('Ponto não encontrado.', true); return; }
    Object.assign(p, { nome: nome, endereco: endereco, lat: lat, lng: lng, tipo: tipo });
    logChange('alteracao', 'Ponto ' + nome, '—', 'Cadastro do ponto alterado', '');
  } else {
    PONTOS.push({ id: 'pt' + Date.now().toString(36), nome: nome, endereco: endereco,
                  lat: lat, lng: lng, tipo: tipo });
    logChange('inclusao', 'Ponto ' + nome, '—', 'Novo ponto cadastrado', '');
  }
  ptAplicarNoSistema();
  ptSalvarNaNuvem();
  ptLimparForm();
  ptRenderLista();
  ptMsg('Pontos atualizados.', false);
}

function ptExcluir(id) {
  const p = PONTOS.find(x => x.id === id);
  if (!p) return;
  if (PONTOS.filter(x => x.tipo === p.tipo).length === 1 && p.tipo !== 'outro') {
    ptMsg('Este é o único ponto do tipo "' + p.tipo + '". Cadastre outro antes de excluir.', true);
    return;
  }
  if (!confirm('Excluir o ponto ' + p.nome + '?')) return;
  PONTOS = PONTOS.filter(x => x.id !== id);
  logChange('exclusao', 'Ponto ' + p.nome, p.nome, '—', '');
  ptAplicarNoSistema();
  ptSalvarNaNuvem();
  ptRenderLista();
  ptMsg('Ponto removido.', false);
}

// A garagem e o destino do sistema passam a vir do cadastro. Mutar os objetos
// (em vez de trocar a referência) faz todo mundo enxergar — GARAGEM_COORDS e
// EMPRESA_COORDS apontam para eles.
function ptAplicarNoSistema() {
  const gar = PONTOS.find(p => p.tipo === 'garagem');
  const emp = PONTOS.find(p => p.tipo === 'empresa');
  if (gar) { EMPRESA_CONFIG.garagem.lat = gar.lat; EMPRESA_CONFIG.garagem.lng = gar.lng;
             if (gar.endereco) EMPRESA_CONFIG.garagem.endereco = gar.endereco; }
  // e o texto que vai para as telas e o PDF
  if (gar && gar.endereco) { GARAGEM = gar.endereco; window.GARAGEM = GARAGEM; }
  if (emp) { EMPRESA_CONFIG.destino.lat = emp.lat; EMPRESA_CONFIG.destino.lng = emp.lng;
             if (emp.endereco) EMPRESA_CONFIG.destino.endereco = emp.endereco;
             if (emp.nome) EMPRESA_CONFIG.destino.nome = emp.nome; }
  if (emp && emp.endereco) { DESTINO = emp.endereco; window.DESTINO = DESTINO; }
  // Mantém em sincronia os campos que salvarEmpresaConfig lê. Assim o cadastro
  // é o único lugar de edição, sem quebrar o caminho de gravação que já existe.
  const gc = document.getElementById('cfgGarCoords');
  const dc = document.getElementById('cfgDestCoords');
  if (gc && gar) gc.value = gar.lat + ', ' + gar.lng;
  if (dc && emp) dc.value = emp.lat + ', ' + emp.lng;
  if (typeof optLimparCacheMatriz === 'function') optLimparCacheMatriz();
}

async function ptSalvarNaNuvem() {
  try {
    if (!fbDb) await initFirebase();
    if (!fbDb) { ptMsg('Salvo nesta sessão, mas o servidor está indisponível.', true); return; }
    const { setDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    await setDoc(doc(fbDb, CLIENTE_ID, 'config'),
      { pontos: PONTOS, updatedAt: new Date().toISOString() }, { merge: true });
  } catch (e) {
    ptMsg('Salvo nesta sessão (erro ao gravar no servidor: ' + e.message + ')', true);
  }
}

// ---------------- Cadastro de veiculos (Config > Frota) ----------------
let frEditandoId = null;

function frCalcular() {
  const manual = document.getElementById('frManual').checked;
  const cap = document.getElementById('frCapacidade');
  cap.disabled = !manual;
  if (!manual) {
    const a = parseInt(document.getElementById('frAssentos').value, 10) || 0;
    const t = parseInt(document.getElementById('frTripulacao').value, 10) || 0;
    cap.value = Math.max(0, a - t);
  }
}

function frMsg(txt, erro) {
  const el = document.getElementById('frMsg');
  if (!el) return;
  el.textContent = txt || '';
  el.style.color = erro ? 'var(--red)' : 'var(--green)';
}

function frRenderLista() {
  const box = document.getElementById('frotaLista');
  if (!box) return;
  if (!FROTA.length) {
    box.innerHTML = '<div style="font-size:12px;color:var(--muted);padding:10px;border:1px dashed var(--border);border-radius:10px">' +
      'Nenhum veículo cadastrado ainda. Enquanto não houver frota, as linhas seguem com as capacidades antigas (Van 15, Carro 4).</div>';
    return;
  }
  box.innerHTML = FROTA.map(v => {
    const cap = frCapacidadeDe(v);
    const usos = DATA.filter(r => r.veiculoId === v.id).length;
    return '<div class="fr-item">' +
      '<div style="flex:1;min-width:0">' +
        '<div style="font-weight:600;font-size:13px">' + esc(frRotulo(v)) + '</div>' +
        '<div style="font-size:11.5px;color:var(--muted)">' + esc(v.tipo) +
          (v.modelo && v.apelido ? ' · ' + esc(v.modelo) : '') +
          ' · ' + (parseInt(v.assentos,10)||0) + ' assentos − ' + (parseInt(v.tripulacao,10)||0) + ' tripulação' +
          (v.capacidadeManual != null && v.capacidadeManual !== '' ? ' · ajustado à mão' : '') +
          (v.ativo === false ? ' · <b style="color:var(--red)">fora de operação</b>' : '') +
          (usos ? ' · em ' + usos + (usos === 1 ? ' linha' : ' linhas') : '') +
        '</div>' +
      '</div>' +
      '<div class="fr-cap">' + cap + '<span>vagas</span></div>' +
      '<button onclick="frEditar(\'' + v.id + '\')" class="ico-btn ico-editar" title="Editar veículo" aria-label="Editar veículo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M4 20h4L19 9a2.1 2.1 0 0 0-3-3L5 17v3Z"/><path d="M14.5 6.5 17.5 9.5"/></svg></button>' +
      '<button onclick="frExcluir(\'' + v.id + '\')" class="ico-btn ico-excluir" title="Excluir veículo" aria-label="Excluir veículo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M4 7h16M9.5 7V5h5v2M6.5 7l.8 13h9.4l.8-13"/><path d="M10 11v6M14 11v6"/></svg></button>' +
    '</div>';
  }).join('');
}

function frLimparForm() {
  frEditandoId = null;
  document.getElementById('frTipo').value = 'Van';
  document.getElementById('frModelo').value = '';
  document.getElementById('frApelido').value = '';
  document.getElementById('frAssentos').value = 16;
  document.getElementById('frTripulacao').value = 1;
  const _at = document.getElementById('frAtivo'); if (_at) _at.checked = true;
  document.getElementById('frManual').checked = false;
  document.getElementById('frBtnSalvar').textContent = 'Adicionar veículo';
  document.getElementById('frBtnCancelar').style.display = 'none';
  frCalcular();
}

function frCancelar() { frLimparForm(); frMsg(''); frDestacar(null); }

// Numa lista longa, mandar os dados para campos fora da tela parece que nada
// aconteceu. Rola até o formulário e marca a linha que está sendo editada.
function frDestacar(id) {
  document.querySelectorAll('#frotaLista .fr-item').forEach(el => el.classList.remove('em-edicao'));
  if (!id) return;
  const lista = document.getElementById('frotaLista');
  const itens = lista ? [...lista.querySelectorAll('.fr-item')] : [];
  const i = FROTA.findIndex(v => v.id === id);
  if (itens[i]) itens[i].classList.add('em-edicao');
  const campo = document.getElementById('frTipo');
  if (campo) campo.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

function frEditar(id) {
  const v = frBuscar(id);
  if (!v) return;
  frEditandoId = id;
  document.getElementById('frTipo').value = v.tipo || 'Van';
  document.getElementById('frModelo').value = v.modelo || '';
  document.getElementById('frApelido').value = v.apelido || '';
  document.getElementById('frAssentos').value = v.assentos || 0;
  document.getElementById('frTripulacao').value = v.tripulacao || 0;
  const _at2 = document.getElementById('frAtivo'); if (_at2) _at2.checked = v.ativo !== false;
  const manual = (v.capacidadeManual != null && v.capacidadeManual !== '');
  document.getElementById('frManual').checked = manual;
  frCalcular();
  if (manual) document.getElementById('frCapacidade').value = v.capacidadeManual;
  document.getElementById('frBtnSalvar').textContent = 'Salvar alterações';
  document.getElementById('frBtnCancelar').style.display = '';
  frMsg('Editando ' + frRotulo(v) + '. Os campos abaixo já estão preenchidos.', false);
  frDestacar(id);
}

function frSalvar() {
  const tipo = document.getElementById('frTipo').value;
  const modelo = document.getElementById('frModelo').value.trim();
  const apelido = document.getElementById('frApelido').value.trim();
  const assentos = parseInt(document.getElementById('frAssentos').value, 10);
  const tripulacao = parseInt(document.getElementById('frTripulacao').value, 10);
  const manual = document.getElementById('frManual').checked;
  const capManual = manual ? parseInt(document.getElementById('frCapacidade').value, 10) : null;

  if (!assentos || assentos < 1) { frMsg('Informe quantos assentos o veículo tem.', true); return; }
  if (isNaN(tripulacao) || tripulacao < 0) { frMsg('Informe quantos assentos ficam com a tripulação (0 se nenhum).', true); return; }
  if (tripulacao >= assentos) { frMsg('A tripulação não pode ocupar todos os assentos.', true); return; }
  if (manual && (isNaN(capManual) || capManual < 0)) { frMsg('Informe a capacidade manual.', true); return; }
  if (manual && capManual > assentos - tripulacao) {
    if (!confirm('A capacidade manual (' + capManual + ') é maior que os assentos disponíveis (' +
                 (assentos - tripulacao) + '). Continuar mesmo assim?')) return;
  }

  const dados = { tipo: tipo, modelo: modelo, apelido: apelido, assentos: assentos,
                  tripulacao: tripulacao, capacidadeManual: manual ? capManual : null,
                  ativo: (document.getElementById('frAtivo') || { checked: true }).checked };

  if (frEditandoId) {
    const v = frBuscar(frEditandoId);
    if (!v) { frMsg('Veículo não encontrado.', true); return; }
    Object.assign(v, dados);
    // o rotulo do veiculo mudou: atualiza as linhas que o usam
    DATA.forEach(r => { if (r.veiculoId === v.id) r.veiculo = frRotulo(v); });
    logChange('alteracao', 'Veículo ' + frRotulo(v), '—', 'Cadastro do veículo alterado', '');
  } else {
    dados.id = 'v' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    FROTA.push(dados);
    logChange('inclusao', 'Veículo ' + frRotulo(dados), '—', 'Novo veículo cadastrado (' + frCapacidadeDe(dados) + ' vagas)', '');
  }

  PL_FROTA_LIVRE = null;   // a frota mudou: a seleção do planejamento é refeita
  frSalvarNaNuvem();
  frLimparForm();
  frRenderLista();
  glPopularVeiculos();
  renderSidebar();
  saveAfterChange();
  frMsg('Frota atualizada.', false);
}

function frExcluir(id) {
  const v = frBuscar(id);
  if (!v) return;
  const usos = DATA.filter(r => r.veiculoId === id);
  if (usos.length) {
    if (!confirm('Este veículo está em ' + usos.length + (usos.length === 1 ? ' linha' : ' linhas') +
                 '.\n\nSe excluir, essas linhas voltam a usar a capacidade antiga até você escolher outro veículo. Continuar?')) return;
    usos.forEach(r => { delete r.veiculoId; });
    saveAfterChange();
  } else if (!confirm('Excluir o veículo ' + frRotulo(v) + '?')) return;
  FROTA = FROTA.filter(x => x.id !== id);
  logChange('exclusao', 'Veículo ' + frRotulo(v), frRotulo(v), '—', '');
  frSalvarNaNuvem();
  frRenderLista();
  glPopularVeiculos();
  renderSidebar();
  frMsg('Veículo removido.', false);
}

async function frSalvarNaNuvem() {
  try {
    if (!fbDb) await initFirebase();
    if (!fbDb) { frMsg('Salvo nesta sessão, mas o servidor está indisponível.', true); return; }
    const { setDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    await setDoc(doc(fbDb, CLIENTE_ID, 'config'), { veiculos: FROTA, updatedAt: new Date().toISOString() }, { merge: true });
  } catch (e) {
    frMsg('Salvo nesta sessão (erro ao gravar no servidor: ' + e.message + ')', true);
  }
}

async function salvarEmpresaConfig() {
  const status = document.getElementById('cfgEmpresaStatus');
  const parseCoords = (txt) => {
    const m = (txt||'').split(',').map(s => parseFloat(s.trim()));
    if (m.length === 2 && !isNaN(m[0]) && !isNaN(m[1])) return { lat: m[0], lng: m[1] };
    return null;
  };
  const nome = document.getElementById('cfgNome').value.trim();
  const operacaoNome = (document.getElementById('cfgOperacaoNome') || {}).value;
  const whatsCliente = document.getElementById('cfgWhatsCliente').value.trim();
  const whatsRedentor = document.getElementById('cfgWhatsRedentor').value.trim();
  const t1 = document.getElementById('cfgT1').value;
  const t2 = document.getElementById('cfgT2').value;
  const t3 = document.getElementById('cfgT3').value;
  const ta = document.getElementById('cfgTA').value;
  const gar = parseCoords(document.getElementById('cfgGarCoords').value);
  const dest = parseCoords(document.getElementById('cfgDestCoords').value);

  if (!gar) { status.textContent = 'Coordenadas da garagem inválidas. Use: -23.5146, -47.5167'; status.className = 'opt-status error'; return; }
  if (!dest) { status.textContent = 'Coordenadas do destino inválidas. Use: -23.4429, -47.3896'; status.className = 'opt-status error'; return; }

  // Monta o objeto empresa
  EMPRESA_CONFIG.operacaoNome = (operacaoNome || '').trim();
  const empresa = {
    nome: nome || EMPRESA_CONFIG.nome,
    operacaoNome: (operacaoNome || '').trim(),
    whatsCliente: whatsCliente,
    whatsRedentor: whatsRedentor,
    senhaCliente: document.getElementById('cfgSenhaCliente').value.trim(),
    turnosChegada: { '1°': t1, '2°': t2, '3°': t3, 'ADM': ta },
    garagem: { lat: gar.lat, lng: gar.lng },
    destino: { lat: dest.lat, lng: dest.lng }
  };

  // Aplica em memória já (efeito imediato) e grava no Firebase
  aplicarEmpresaConfig({ empresa });
  status.textContent = 'Salvando no servidor...';
  status.className = 'opt-status';
  try {
    if (!fbDb) await initFirebase();
    if (fbDb) {
      const { setDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
      const configRef = doc(fbDb, CLIENTE_ID, 'config');
      await setDoc(configRef, { empresa, updatedAt: new Date().toISOString() }, { merge: true });
      status.textContent = 'Dados da empresa salvos!';
      status.className = 'opt-status success';
    } else {
      status.textContent = 'Aplicado nesta sessão, mas o Firebase está indisponível para salvar.';
      status.className = 'opt-status error';
    }
  } catch(e) {
    status.textContent = 'Aplicado nesta sessão (erro ao salvar no servidor: ' + e.message + ')';
    status.className = 'opt-status error';
  }
}

// ====================== IMPORTAÇÃO DE PASSAGEIROS ======================
const IMP_COLUNAS = ['NOME COMPLETO','LINHA','TURNO','HORARIO EMBARQUE','LOCAL EMBARQUE','ENDERECO RESIDENCIAL','BAIRRO','CIDADE','TELEFONE','COORDENADAS','TIPO DE VEICULO','MOTORISTA'];
let IMP_DADOS = null; // dados parseados aguardando confirmação

function impAbrir() {
  document.getElementById('impPasso1').style.display = 'block';
  document.getElementById('impPasso2').style.display = 'none';
  document.getElementById('impErro').textContent = '';
  document.getElementById('impStatus').textContent = '';
  document.getElementById('impNomeArquivo').textContent = '';
  document.getElementById('impArquivo').value = '';
  IMP_DADOS = null;
  document.getElementById('modalImport').classList.add('open');
}

function impBaixarModelo() {
  // Gera uma planilha-modelo .xlsx com cabeçalho e uma linha de exemplo
  const cab = ['NOME COMPLETO','MATRÍCULA','LINHA','TURNO','HORÁRIO EMBARQUE','LOCAL EMBARQUE','ENDEREÇO RESIDENCIAL','BAIRRO','CIDADE','TELEFONE','COORDENADAS','TIPO DE VEÍCULO','MOTORISTA'];
  const exemplo = ['João da Silva','01234','1','ADM','05:45','Av. Exemplo, 100 (Ponto de ônibus)','Rua de Casa, 50','Centro','Sorocaba','15 99999-0000','-23.50, -47.45','VAN',''];
  const ws = XLSX.utils.aoa_to_sheet([cab, exemplo]);
  ws['!cols'] = cab.map(() => ({ wch: 22 }));
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Passageiros');
  XLSX.writeFile(wb, 'modelo_importacao_passageiros.xlsx');
}

function impNormalizarChave(s) {
  return String(s||'').toUpperCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'') // remove acentos
    .replace(/\(.*?\)/g,'') // remove parênteses e conteúdo
    .replace(/[^A-Z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
}

function impAcharColuna(headers, alvo) {
  const a = impNormalizarChave(alvo);
  for (let i = 0; i < headers.length; i++) {
    const h = impNormalizarChave(headers[i]);
    if (h === a || h.startsWith(a) || a.startsWith(h)) return i;
  }
  return -1;
}

function impFormatarHorario(v) {
  if (v == null || v === '') return '--:--';
  // número decimal do Excel (fração do dia)
  if (typeof v === 'number') {
    const totalMin = Math.round(v * 24 * 60);
    const h = Math.floor(totalMin / 60) % 24, m = totalMin % 60;
    return String(h).padStart(2,'0') + ':' + String(m).padStart(2,'0');
  }
  let s = String(v).trim().toUpperCase().replace('H', ':').replace(/[^0-9:]/g,'');
  if (/^\d{1,2}:\d{0,2}$/.test(s)) {
    let [h, m] = s.split(':');
    return h.padStart(2,'0') + ':' + (m||'0').padStart(2,'0');
  }
  if (/^\d{1,2}$/.test(s)) return s.padStart(2,'0') + ':00';
  return '--:--';
}

function impLerArquivo(ev) {
  const file = ev.target.files[0];
  if (!file) return;
  document.getElementById('impNomeArquivo').textContent = '' + file.name;
  document.getElementById('impErro').textContent = '';
  const reader = new FileReader();
  reader.onload = (e) => {
    try {
      const data = new Uint8Array(e.target.result);
      const wb = XLSX.read(data, { type: 'array' });
      const ws = wb.Sheets[wb.SheetNames[0]];
      const linhas = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
      impProcessar(linhas);
    } catch (err) {
      document.getElementById('impErro').textContent = 'Não consegui ler o arquivo: ' + err.message;
    }
  };
  reader.readAsArrayBuffer(file);
}

// Telefone canonico via motor/comum.js — fonte unica. Se o comum.js nao tiver
// carregado, devolve o que veio: melhor guardar o original do que inventar.
function impTelCanonico(bruto) {
  try {
    const r = window.temviaComum.normalizarTelefone(bruto, { obrigatorio: false });
    return r.ok && r.valor ? r.valor : bruto;
  } catch (e) { return bruto; }
}

// Confere identidade do lote inteiro. Devolve { erros, avisos }.
// ERRO impede importar. AVISO importa, mas a pessoa fica sem login.
function impValidarIdentidade(passageiros) {
  const erros = [], avisos = [];
  if (!window.temviaComum) {
    erros.push('O modulo comum.js nao carregou — nao consigo validar telefone. ' +
               'Recarregue a pagina antes de importar.');
    return { erros, avisos };
  }

  const porTelefone = {}, porMatricula = {};

  passageiros.forEach((p, i) => {
    const onde = 'linha ' + (i + 1) + ' (' + p.nome + ')';

    const t = window.temviaComum.normalizarTelefone(p.telefone, { obrigatorio: false });
    if (!t.ok) {
      erros.push(onde + ': telefone "' + p.telefone + '" — ' + t.motivo);
    } else if (!t.valor) {
      avisos.push(onde + ': sem telefone — entra no cadastro, mas nao tera acesso ao app.');
    } else {
      (porTelefone[t.valor] = porTelefone[t.valor] || []).push(p.nome);
    }

    if (!p.matricula) {
      avisos.push(onde + ': sem matricula — precisara dela para ativar o acesso.');
    } else {
      (porMatricula[p.matricula] = porMatricula[p.matricula] || []).push(p.nome);
    }
  });

  // Telefone repetido = duas pessoas disputando a MESMA identidade. Bloqueia.
  Object.keys(porTelefone).forEach(t => {
    if (porTelefone[t].length > 1) {
      erros.push('Telefone ' + window.temviaComum.formatarTelefone(t) +
                 ' aparece em ' + porTelefone[t].length + ' pessoas: ' +
                 porTelefone[t].join(', ') + '. Cada pessoa precisa do proprio numero.');
    }
  });

  // Matricula repetida = quase sempre erro de planilha, mas nao impede login,
  // porque a chave e o telefone. Ver o cabecalho do patch.
  Object.keys(porMatricula).forEach(m => {
    if (porMatricula[m].length > 1) {
      avisos.push('Matricula ' + m + ' repetida em: ' + porMatricula[m].join(', ') + '.');
    }
  });

  return { erros, avisos };
}

function impProcessar(linhas) {
  // Acha a linha de cabeçalho (a que tem "NOME")
  let hIdx = -1;
  for (let i = 0; i < Math.min(linhas.length, 10); i++) {
    if (linhas[i].some(c => impNormalizarChave(c).includes('NOME'))) { hIdx = i; break; }
  }
  if (hIdx < 0) { document.getElementById('impErro').textContent = 'Não encontrei a linha de cabeçalho (com "NOME COMPLETO"). Use a planilha-modelo.'; return; }

  const headers = linhas[hIdx];
  const col = {
    nome: impAcharColuna(headers, 'NOME COMPLETO'),
    matricula: impAcharColuna(headers, 'MATRICULA'),
    linha: impAcharColuna(headers, 'LINHA'),
    turno: impAcharColuna(headers, 'TURNO'),
    horario: impAcharColuna(headers, 'HORARIO EMBARQUE'),
    embarque: impAcharColuna(headers, 'LOCAL EMBARQUE'),
    endereco: impAcharColuna(headers, 'ENDERECO RESIDENCIAL'),
    bairro: impAcharColuna(headers, 'BAIRRO'),
    cidade: impAcharColuna(headers, 'CIDADE'),
    telefone: impAcharColuna(headers, 'TELEFONE'),
    coords: impAcharColuna(headers, 'COORDENADAS'),
    veiculo: impAcharColuna(headers, 'TIPO DE VEICULO'),
    motorista: impAcharColuna(headers, 'MOTORISTA')
  };
  if (col.nome < 0 || col.linha < 0 || col.turno < 0) {
    document.getElementById('impErro').textContent = 'A planilha precisa ter pelo menos as colunas NOME COMPLETO, LINHA e TURNO.'; return;
  }

  const passageiros = [];
  const avisos = [];
  for (let i = hIdx + 1; i < linhas.length; i++) {
    const r = linhas[i];
    const nome = String(r[col.nome]||'').trim();
    if (!nome) continue; // pula linhas vazias
    const linha = String(r[col.linha]||'').trim();
    const turno = String(r[col.turno]||'').trim().toUpperCase();
    if (!linha || !turno) { avisos.push('Linha ' + (i+1) + ' (' + nome + '): sem LINHA/TURNO — ignorada.'); continue; }

    // Coordenadas
    let lat = null, lng = null;
    const craw = String(col.coords >= 0 ? r[col.coords] : '').trim();
    if (craw) {
      const parts = craw.split(',').map(s => parseFloat(s.trim()));
      if (parts.length === 2 && !isNaN(parts[0]) && !isNaN(parts[1])) { lat = parts[0]; lng = parts[1]; }
    }
    if (lat == null) avisos.push('' + nome + ': sem coordenadas válidas (não aparecerá no mapa/roteirizador até preencher).');

    passageiros.push({
      nome,
      linha, turno,
      horario: impFormatarHorario(col.horario >= 0 ? r[col.horario] : ''),
      embarque: String(col.embarque >= 0 ? r[col.embarque] : '').trim(),
      endereco: String(col.endereco >= 0 ? r[col.endereco] : '').trim(),
      bairro: String(col.bairro >= 0 ? r[col.bairro] : '').trim(),
      cidade: String(col.cidade >= 0 ? r[col.cidade] : '').trim() || 'Sorocaba',
      // Canonico quando valido; o que veio da planilha quando nao. A tela de
      // conferencia mostra os invalidos antes de deixar importar.
      telefone: impTelCanonico(String(col.telefone >= 0 ? r[col.telefone] : '').trim()),
      matricula: String(col.matricula >= 0 ? r[col.matricula] : '').trim(),
      veiculo: String(col.veiculo >= 0 ? r[col.veiculo] : '').trim() || 'Van',
      motorista: String(col.motorista >= 0 ? r[col.motorista] : '').trim(),
      lat, lng,
      status: 'ativo', km: 0, retorno: ''
    });
  }

  if (!passageiros.length) { document.getElementById('impErro').textContent = 'Nenhum passageiro válido encontrado na planilha.'; return; }

  // Agrupa por linha+turno para montar as rotas
  const rotasMap = {};
  passageiros.forEach(p => {
    const key = p.linha + '-' + p.turno;
    if (!rotasMap[key]) rotasMap[key] = [];
    rotasMap[key].push(p);
  });

  const val = impValidarIdentidade(passageiros);
  IMP_DADOS = { passageiros, rotasMap, avisos: avisos.concat(val.avisos), erros: val.erros };
  impMostrarPrevia();
}

function impMostrarPrevia() {
  const { passageiros, rotasMap, avisos } = IMP_DADOS;
  const erros = IMP_DADOS.erros || [];
  const nRotas = Object.keys(rotasMap).length;
  document.getElementById('impResumo').innerHTML =
    '<b>' + passageiros.length + '</b> passageiros em <b>' + nRotas + '</b> linha(s)/turno(s): ' +
    Object.keys(rotasMap).map(k => k + ' (' + rotasMap[k].length + ')').join(', ');

  let html = '<thead><tr style="position:sticky;top:0;background:var(--surface2)">' +
    ['Nome','Matrícula','Linha','Turno','Horário','Bairro','Telefone','Coords'].map(h => '<th style="padding:7px 9px;text-align:left;border-bottom:1px solid var(--border)">'+h+'</th>').join('') +
    '</tr></thead><tbody>';
  passageiros.forEach(p => {
    html += '<tr>' +
      '<td style="padding:6px 9px;border-bottom:1px solid var(--border)">'+esc(p.nome)+'</td>' +
      '<td style="padding:6px 9px;border-bottom:1px solid var(--border)">'+esc(p.matricula||'\u2014')+'</td>' +
      '<td style="padding:6px 9px;border-bottom:1px solid var(--border)">'+esc(p.linha)+'</td>' +
      '<td style="padding:6px 9px;border-bottom:1px solid var(--border)">'+esc(p.turno)+'</td>' +
      '<td style="padding:6px 9px;border-bottom:1px solid var(--border)">'+esc(p.horario)+'</td>' +
      '<td style="padding:6px 9px;border-bottom:1px solid var(--border)">'+esc(p.bairro)+'</td>' +
      '<td style="padding:6px 9px;border-bottom:1px solid var(--border)">'+esc(p.telefone)+'</td>' +
      '<td style="padding:6px 9px;border-bottom:1px solid var(--border)">'+(p.lat!=null?'':'—')+'</td>' +
    '</tr>';
  });
  html += '</tbody>';
  document.getElementById('impPreviaTabela').innerHTML = html;
  document.getElementById('impAvisos').innerHTML = avisos.length ? ('' + avisos.length + ' aviso(s):<br>' + avisos.slice(0,8).join('<br>') + (avisos.length>8?'<br>...':'')) : '';

  // Erro de identidade impede importar. Nao e aviso: telefone repetido faz
  // duas pessoas disputarem o mesmo login, e a segunda apaga a primeira.
  const cxErro = document.getElementById('impAvisos');
  if (erros.length && cxErro) {
    cxErro.innerHTML =
      '<div style="border:1px solid var(--red);border-radius:8px;padding:10px 12px;margin-bottom:8px">' +
      '<b style="color:var(--red)">' + erros.length + ' problema(s) impedem a importa\u00e7\u00e3o</b>' +
      '<div style="font-size:11.5px;margin-top:6px;line-height:1.6">' +
      erros.slice(0, 12).map(esc).join('<br>') +
      (erros.length > 12 ? '<br>\u2026 e mais ' + (erros.length - 12) : '') +
      '</div><div style="font-size:11.5px;margin-top:8px;color:var(--muted)">' +
      'Corrija a planilha e importe de novo.</div></div>' + cxErro.innerHTML;
  }
  const btn = document.getElementById('impBtnConfirmar');
  if (btn) {
    btn.disabled = erros.length > 0;
    btn.style.opacity = erros.length ? '.5' : '';
    btn.style.cursor = erros.length ? 'not-allowed' : 'pointer';
  }

  document.getElementById('impPasso1').style.display = 'none';
  document.getElementById('impPasso2').style.display = 'block';
}

function impVoltar() {
  document.getElementById('impPasso1').style.display = 'block';
  document.getElementById('impPasso2').style.display = 'none';
}

function impConfirmar() {
  if ((IMP_DADOS.erros || []).length) {
    alert('A planilha tem ' + IMP_DADOS.erros.length + ' problema(s) de identidade.\n\n' +
          'Corrija e importe de novo.');
    return;
  }
  if (!IMP_DADOS) return;
  const modo = document.querySelector('input[name="impModo"]:checked').value;
  const { rotasMap } = IMP_DADOS;
  const status = document.getElementById('impStatus');

  if (modo === 'substituir') {
    if (!confirm('SUBSTITUIR TUDO: isso vai apagar todos os passageiros e rotas atuais e colocar só os importados. Tem certeza?')) return;
    DATA.length = 0;
  }

  let novasRotas = 0, novosPax = 0;
  Object.keys(rotasMap).forEach(key => {
    const lista = rotasMap[key];
    const linha = lista[0].linha;
    const turno = lista[0].turno;
    const veiculo = lista[0].veiculo || 'Van';
    const motorista = lista[0].motorista || '';
    const rotaId = linha + '-' + turno;

    // Procura rota existente (modo acrescentar) ou cria nova
    let rota = DATA.find(r => r.id === rotaId);
    if (!rota) {
      rota = {
        id: rotaId, linha: linha, turno: turno,
        cod: 'L' + linha + '|' + turno + '|' + String(veiculo).toUpperCase(),
        veiculo: veiculo, motorista: motorista, motoristaSaida: '',
        passageiros: []
      };
      DATA.push(rota);
      novasRotas++;
    }
    // Ordem inicial = sequência da planilha (continua de onde a rota está)
    let ordem = rota.passageiros.length;
    lista.forEach(p => {
      ordem++;
      rota.passageiros.push({
        nome: p.nome, lat: p.lat, lng: p.lng,
        endereco: p.endereco, embarque: p.embarque,
        bairro: p.bairro, cidade: p.cidade, telefone: p.telefone,
        horario: p.horario, status: 'ativo', km: 0, retorno: '', ordem: ordem
      });
      novosPax++;
    });
  });

  status.textContent = 'Salvando...';
  try {
    saveAfterChange();
    logChange('inclusao', 'Importação de planilha', '—', novosPax + ' passageiros em ' + Object.keys(rotasMap).length + ' linha(s)', modo === 'substituir' ? 'Substituição total' : 'Acréscimo');
    renderSidebar();
    status.innerHTML = '<b>' + novosPax + '</b> passageiros importados! (' + novasRotas + ' nova(s) linha(s))';
    setTimeout(() => { document.getElementById('modalImport').classList.remove('open'); }, 1800);
  } catch (e) {
    status.textContent = 'Erro ao salvar: ' + e.message;
  }
}

// ---- MOTORISTA VIEW (from main system) ----
function openMotoristView() {
  const selMoto = document.getElementById('motoSelectMotorista');
  selMoto.innerHTML = '<option value="">— Todos os motoristas —</option>';
  MOTORISTAS.forEach(m => {
    const opt = document.createElement('option');
    opt.value = m.nome;
    opt.textContent = m.nome;
    selMoto.appendChild(opt);
  });
  motoFilterLinhas();
  document.getElementById('motoRotaContent').innerHTML = '';
  document.getElementById('motoView').classList.add('open');
}

function motoFilterLinhas() {
  const motoNome = document.getElementById('motoSelectMotorista').value;
  const sel = document.getElementById('motoSelectLinha');
  sel.innerHTML = '<option value="">— Selecione uma linha —</option>';
  DATA.forEach(rota => {
    if (motoNome && rota.motorista !== motoNome && rota.motoristaSaida !== motoNome) return;
    const ativos = rota.passageiros.filter(p => p.status === 'ativo').length;
    if (ativos === 0) return;
    const chegada = TURNOS_CHEGADA[rota.turno] || '';
    const opt = document.createElement('option');
    opt.value = rota.id;
    opt.textContent = 'Linha ' + rota.linha + ' · ' + rota.turno + ' Turno · ' + ativos + ' pass. · chegada ' + chegada;
    sel.appendChild(opt);
  });
  document.getElementById('motoRotaContent').innerHTML = '';
}

function motoLoadRota() {
  const rotaId = document.getElementById('motoSelectLinha').value;
  const content = document.getElementById('motoRotaContent');
  if (!rotaId) { content.innerHTML = ''; return; }
  const rota = DATA.find(r => r.id === rotaId);
  if (!rota) return;
  const chegada = TURNOS_CHEGADA[rota.turno] || '';
  const mObj = MOTORISTAS.find(m => m.nome === rota.motorista);
  const mObjS = rota.motoristaSaida ? MOTORISTAS.find(m => m.nome === rota.motoristaSaida) : null;
  const sorted = rota.passageiros
    .filter(p => p.status === 'ativo')
    .sort((a,b) => (a.horario||'99:99').localeCompare(b.horario||'99:99'));

  function buildMapsUrlLocal(stops) {
    const garAddr  = encodeURIComponent('R. Sebastiana Rosa Luposeli, 59, Sorocaba SP');
    const empAddr  = encodeURIComponent('Av. Jerome Case, 2600, Eden, Sorocaba SP');
    const vertAddr = encodeURIComponent('Estr. dos Carvalhos, 1441, Cajuru do Sul, Sorocaba SP');
    const isVertiv = String(rota.linha).startsWith('VERTIV');
    const dest = isVertiv ? vertAddr : empAddr;
    if (stops.length === 0) return 'https://www.google.com/maps/dir/?api=1&origin=' + garAddr + '&destination=' + dest + '&travelmode=driving';
    const waypoints = stops.slice(0,8).map(p => p.lat && p.lng ? p.lat+','+p.lng : encodeURIComponent((p.embarque||p.endereco||'')+', '+(p.cidade||'Sorocaba')+' SP'));
    return 'https://www.google.com/maps/dir/?api=1&origin=' + garAddr + '&destination=' + dest + '&waypoints=' + waypoints.join('%7C') + '&travelmode=driving';
  }

  function buildWazeUrlLocal(p) {
    if (p && p.lat && p.lng) return 'https://waze.com/ul?ll=' + p.lat + ',' + p.lng + '&navigate=yes&zoom=17';
    const q = encodeURIComponent(((p&&(p.embarque||p.endereco))||'') + ', ' + ((p&&p.cidade)||'Sorocaba') + ' SP');
    return 'https://waze.com/ul?q=' + q + '&navigate=yes';
  }

  const mapsUrl = buildMapsUrlLocal(sorted);
  const wazeUrl = sorted.length > 0 ? buildWazeUrlLocal(sorted[0]) : '#';

  let html = '<div class="chips">';
  html += '<span class="chip chip-turno">' + rota.turno + ' Turno</span>';
  html += '<span class="chip chip-pass">' + sorted.length + ' passageiros</span>';
  html += '<span class="chip chip-vei">' + rota.veiculo + '</span></div>';

  if (mObj) {
    html += '<div class="moto-info-card"><div class="moto-info-title">Motorista</div>';
    html += '<div class="moto-name">' + mObj.nome + '</div>';
    if (mObj.tel) html += '<div class="moto-tel">' + mObj.tel + '</div>';
    if (mObjS) html += '<div style="margin-top:8px;font-size:12px;color:var(--muted)">Saída: <strong>' + mObjS.nome + '</strong>' + (mObjS.tel ? ' · ' + mObjS.tel : '') + '</div>';
    html += '</div>';
  }

  html += '<div class="nav-btns-row">';
  html += '<a href="' + mapsUrl + '" target="_blank" class="nav-maps-btn"><span style="font-size:18px"></span> Google Maps</a>';
  html += '<a href="' + wazeUrl + '" target="_blank" class="nav-waze-btn"><span style="font-size:18px">●</span> Waze</a>';
  html += '</div>';

  html += '<div class="moto-info-card">';
  html += '<div class="moto-info-title" style="color:var(--green)">Garagem Redentor</div>';
  html += '<div style="font-size:12px;color:var(--muted)">R. Sebastiana Rosa Luposeli, 59 — Júlio de Mesquita Filho</div></div>';

  html += '<div class="moto-info-card"><div class="moto-info-title">Paradas</div>';
  sorted.forEach((p, i) => {
    const addr = p.embarque || p.endereco || '—';
    const mapsStop = p.lat && p.lng ? 'https://www.google.com/maps/search/?api=1&query=' + p.lat + ',' + p.lng : 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(addr + ', ' + (p.cidade||'Sorocaba') + ' SP');
    const wazeStop = buildWazeUrlLocal(p);
    html += '<div class="moto-stop"><div class="moto-stop-num">' + (i+1) + '</div>';
    html += '<div style="flex:1"><div style="display:flex;gap:8px;align-items:center">';
    html += '<div class="moto-stop-time">' + (p.horario||'--:--') + '</div>';
    html += '<div><div class="moto-stop-name">' + p.nome.split(' ').slice(0,2).join(' ') + '</div>';
    if (p.telefone) html += '<div class="moto-stop-tel">' + waLink(p.telefone) + '</div>';
    html += '</div></div><div class="moto-stop-addr">' + addr + '</div>';
    html += '<div class="stop-nav-row"><a href="' + mapsStop + '" target="_blank" class="stop-nav-maps">Google Maps</a>';
    html += '<a href="' + wazeStop + '" target="_blank" class="stop-nav-waze">Waze</a></div>';
    html += '</div></div>';
  });
  html += '</div>';

  html += '<div class="moto-dest"><div class="moto-dest-label">Destino Final</div>';
  html += '<div class="moto-dest-time">' + chegada + '</div>';
  const isVertivRota = String(rota.linha).startsWith('VERTIV');
  html += '<div class="dest-addr" style="font-size:12px;color:var(--muted);margin-top:4px">' + (isVertivRota ? 'Estr. dos Carvalhos, 1441 — Cajuru do Sul, Sorocaba-SP' : 'Av. Jerome Case, 2600 — Éden, Sorocaba-SP') + '</div></div>';

  content.innerHTML = html;
}

// ---- ROUTE OPTIMIZATION ----
// 1C: coordenadas agora vêm do EMPRESA_CONFIG (mesma referência).
// Os objetos garagem/destino têm .lat e .lng, que é o que os usos leem;
// campos extras (label, endereco) são ignorados sem problema.
const GARAGEM_COORDS = EMPRESA_CONFIG.garagem;
const EMPRESA_COORDS = EMPRESA_CONFIG.destino;
const MAX_ROTA_MINUTOS = 60;
let otimizarRotaId = null;
let pendingOptimization = null;
let lastDirectionsResult = null;
let optMap = null;
let optDirectionsRenderer = null;

function setOptStatus(msg, type) {
  const el = document.getElementById('optStatus');
  if (!el) return;
  el.textContent = msg;
  el.className = 'opt-status ' + (type || '');
}

async function ensureMapsLoaded() {
  const key = getApiKey();
  if (!key) throw new Error('API Key não configurada. Clique em Config.');
  if (window.google && window.google.maps && window.google.maps.Geocoder) return;
  setOptStatus('Carregando Google Maps API...', 'running');
  try {
    await loadGoogleMaps(key);
    await new Promise(r => setTimeout(r, 800));
    if (!window.google || !window.google.maps) {
      throw new Error('Google Maps não carregou. Verifique: (1) API Key correta, (2) APIs ativadas no Google Cloud, (3) Faturamento ativado.');
    }
  } catch(e) {
    throw new Error('Erro ao carregar Maps: ' + e.message);
  }
}

function getPassengerAddress(p) {
  return p.embarque && p.embarque.trim() ? p.embarque.trim() : (p.endereco || '').trim();
}

async function geocodeAddress(geocoder, address, cidade) {
  return new Promise((resolve) => {
    const cidadeStr = cidade && cidade.trim() ? cidade.trim() : 'Sorocaba';
    const cleanAddr = address.replace(/\s+/g, ' ').trim();
    const fullAddr = cleanAddr + ', ' + cidadeStr + ', SP, Brasil';
    const timer = setTimeout(() => { resolve(null); }, 10000);
    geocoder.geocode({ address: fullAddr, region: 'BR' }, (results, status) => {
      clearTimeout(timer);
      if (status === 'OK' && results[0]) {
        resolve({ lat: results[0].geometry.location.lat(), lng: results[0].geometry.location.lng() });
      } else {
        resolve(null);
      }
    });
  });
}

// ==================================================================
// OTIMIZADOR DE ROTA
// ------------------------------------------------------------------
// Tudo o que decide sequencia mora aqui, separado do Google. As funcoes
// de avaliacao e de solver sao puras: recebem uma matriz e devolvem um
// resultado, sem tocar em rede nem em DOM. E o que torna possivel testar
// o caso da Linha 6 (75 min x 69 min) sem depender da API.
// ==================================================================

// ---------- regras da operação, em um lugar só ----------
// Estes são os valores de fábrica. O que o gestor salvar em
// Configurações > Otimização de rotas vira config.otimizacao no Firestore
// e sobrescreve o que estiver aqui. Nenhuma dessas regras deve voltar a
// aparecer solta no meio do código.
const OPT_PADRAO = {
  // --- regras operacionais (o gestor configura) ---
  maxRideMin: 60,             // tempo máximo do passageiro dentro do veículo
  margemChegadaMin: 5,        // o veículo chega esta folga antes do horário obrigatório
  stopServiceSeconds: 30,     // tempo parado em cada ponto
  extraPassengerSeconds: 10,  // adicional por passageiro além do primeiro no mesmo ponto
  agruparPontos: true,        // tratar embarques vizinhos como um ponto só
  coordToleranceMeters: 25,   // até esta distância, é o mesmo ponto
  preservarOrdem: true,       // ganho pequeno não justifica remexer a ordem
  minGanhoSegundos: 120,      // ganho mínimo de tempo para sugerir mudança
  minGanhoMetros: 1000,       // ou ganho mínimo de distância, com tempo empatado
  objetivo: 'tempo',          // 'tempo' | 'distancia' | 'equilibrado'
  permitirAcimaDoLimite: false, // aplicar rota com passageiro acima do limite?
  reservaVagas: 0,            // vagas deixadas livres em cada veiculo

  // --- técnicos: não aparecem para o gestor ---
  exactMaxPoints: 13,         // acima disso o solver usa busca local
  tolPioraSegundos: 5,        // empate técnico de tempo
  trafficAware: false         // reservado; ver Fase 2.3
};

// Cópia viva usada pelo sistema. Nunca substitua o objeto: só os campos,
// para que quem já guardou a referência continue vendo o valor novo.
const OPT_CFG = Object.assign({}, OPT_PADRAO);

// Aplica o que veio do Firestore por cima dos padrões, campo a campo, com
// validação. Valor ausente ou inválido mantém o padrão — nunca quebra.
function optAplicarConfig(cfg) {
  if (!cfg || typeof cfg !== 'object') { Object.assign(OPT_CFG, OPT_PADRAO); return OPT_CFG; }
  const num = (v, min, max, padrao) => {
    const n = Number(v);
    return (isFinite(n) && n >= min && n <= max) ? n : padrao;
  };
  OPT_CFG.maxRideMin            = num(cfg.maxRideMin, 5, 300, OPT_PADRAO.maxRideMin);
  OPT_CFG.margemChegadaMin      = num(cfg.margemChegadaMin, 0, 120, OPT_PADRAO.margemChegadaMin);
  OPT_CFG.stopServiceSeconds    = num(cfg.stopServiceSeconds, 0, 900, OPT_PADRAO.stopServiceSeconds);
  OPT_CFG.extraPassengerSeconds = num(cfg.extraPassengerSeconds, 0, 300, OPT_PADRAO.extraPassengerSeconds);
  OPT_CFG.coordToleranceMeters  = num(cfg.coordToleranceMeters, 0, 500, OPT_PADRAO.coordToleranceMeters);
  OPT_CFG.minGanhoSegundos      = num(cfg.minGanhoSegundos, 0, 3600, OPT_PADRAO.minGanhoSegundos);
  OPT_CFG.minGanhoMetros        = num(cfg.minGanhoMetros, 0, 50000, OPT_PADRAO.minGanhoMetros);
  OPT_CFG.agruparPontos         = cfg.agruparPontos !== undefined ? !!cfg.agruparPontos : OPT_PADRAO.agruparPontos;
  OPT_CFG.preservarOrdem        = cfg.preservarOrdem !== undefined ? !!cfg.preservarOrdem : OPT_PADRAO.preservarOrdem;
  OPT_CFG.permitirAcimaDoLimite = cfg.permitirAcimaDoLimite !== undefined
    ? !!cfg.permitirAcimaDoLimite : OPT_PADRAO.permitirAcimaDoLimite;
  OPT_CFG.reservaVagas = num(cfg.reservaVagas, 0, 20, OPT_PADRAO.reservaVagas);
  OPT_CFG.objetivo = ['tempo', 'distancia', 'equilibrado'].indexOf(cfg.objetivo) >= 0
    ? cfg.objetivo : OPT_PADRAO.objetivo;
  return OPT_CFG;
}

// O que vai para o Firestore: só as regras operacionais.
function optConfigParaSalvar() {
  return {
    maxRideMin: OPT_CFG.maxRideMin,
    margemChegadaMin: OPT_CFG.margemChegadaMin,
    stopServiceSeconds: OPT_CFG.stopServiceSeconds,
    extraPassengerSeconds: OPT_CFG.extraPassengerSeconds,
    agruparPontos: OPT_CFG.agruparPontos,
    coordToleranceMeters: OPT_CFG.coordToleranceMeters,
    preservarOrdem: OPT_CFG.preservarOrdem,
    minGanhoSegundos: OPT_CFG.minGanhoSegundos,
    minGanhoMetros: OPT_CFG.minGanhoMetros,
    objetivo: OPT_CFG.objetivo,
    permitirAcimaDoLimite: OPT_CFG.permitirAcimaDoLimite,
    reservaVagas: OPT_CFG.reservaVagas
  };
}


// ---------- geometria ----------
function optMetros(a, b) {
  const R = 6371000, rad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * rad, dLng = (b.lng - a.lng) * rad;
  const la1 = a.lat * rad, la2 = b.lat * rad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(la1) * Math.cos(la2) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

// ---------- agrupamento de passageiros no mesmo ponto ----------
// Dois passageiros no mesmo endereco sao UM ponto operacional. Antes viravam
// dois waypoints, o que inflava o tempo e a contagem de paradas.
function optAgruparPontos(passageiros, coordsMap) {
  const pontos = [];
  passageiros.forEach(p => {
    const c = coordsMap[p.nome];
    if (!c) return;
    const achado = OPT_CFG.agruparPontos
      ? pontos.find(pt => optMetros(pt, c) <= OPT_CFG.coordToleranceMeters)
      : null;
    if (achado) { achado.passageiros.push(p); return; }
    pontos.push({
      lat: c.lat, lng: c.lng,
      rotulo: p.embarque || p.endereco || p.nome,
      passageiros: [p]
    });
  });
  pontos.forEach((pt, i) => {
    pt.idx = i;
    pt.servicoSeg = OPT_CFG.stopServiceSeconds +
      Math.max(0, pt.passageiros.length - 1) * OPT_CFG.extraPassengerSeconds;
    pt.nomes = pt.passageiros.map(x => x.nome);
  });
  return pontos;
}

// A ordem atual, traduzida para indices de ponto (pela ordem de horario).
function optOrdemAtual(pontos, passageirosOrdenados) {
  const vistos = [], ordem = [];
  passageirosOrdenados.forEach(p => {
    const pt = pontos.find(x => x.passageiros.some(q => q.nome === p.nome));
    if (pt && vistos.indexOf(pt.idx) < 0) { vistos.push(pt.idx); ordem.push(pt.idx); }
  });
  // qualquer ponto que nao apareceu entra no fim, para nao perder passageiro
  pontos.forEach(pt => { if (ordem.indexOf(pt.idx) < 0) ordem.push(pt.idx); });
  return ordem;
}

// ---------- avaliacao de uma ordem ----------
// ctx = { dur[][], dist[][], pontos, chegadaMin }
// Indices na matriz: 0 = garagem, 1..K = pontos, K+1 = empresa.
// Horarios calculados de tras para frente a partir da chegada obrigatoria.
function optAvaliarOrdem(ordem, ctx) {
  const K = ctx.pontos.length, EMP = K + 1;
  let durSeg = 0, distM = 0;
  const seq = [0].concat(ordem.map(i => i + 1)).concat([EMP]);
  for (let k = 0; k < seq.length - 1; k++) {
    durSeg += ctx.dur[seq[k]][seq[k + 1]];
    distM += ctx.dist[seq[k]][seq[k + 1]];
    if (k > 0) durSeg += ctx.pontos[seq[k] - 1].servicoSeg;
  }
  // tempo de cada ponto dentro do veiculo = do embarque ate a chegada
  const rideSeg = new Array(ordem.length);
  let acc = 0;
  for (let k = ordem.length - 1; k >= 0; k--) {
    const atual = ordem[k] + 1;
    const prox = (k === ordem.length - 1) ? EMP : ordem[k + 1] + 1;
    acc += ctx.dur[atual][prox];
    if (k < ordem.length - 1) acc += ctx.pontos[ordem[k + 1]].servicoSeg;
    rideSeg[k] = acc;
  }
  let violacoes = 0, maiorRide = 0;
  ordem.forEach((pi, k) => {
    const min = rideSeg[k] / 60;
    if (min > maiorRide) maiorRide = min;
    if (min > OPT_CFG.maxRideMin) violacoes += ctx.pontos[pi].passageiros.length;
  });
  const chegada = ctx.chegadaMin;
  const embarqueMin = ordem.map((pi, k) => chegada - Math.round(rideSeg[k] / 60));
  const saidaGaragem = chegada - Math.round(durSeg / 60);

  // Jornada do veículo: inclui a volta VAZIA da empresa até a garagem.
  // Esse trecho não entra no tempo de nenhum passageiro — ninguém está a
  // bordo — mas é combustível, hora de motorista e desgaste. Ficava de fora.
  // Como é constante para qualquer ordem, medi-lo não altera a decisão.
  const voltaSeg = (ctx.dur[EMP] && ctx.dur[EMP][0]) ? ctx.dur[EMP][0] : 0;
  const voltaM = (ctx.dist[EMP] && ctx.dist[EMP][0]) ? ctx.dist[EMP][0] : 0;

  // O trecho garagem -> 1o embarque TAMBEM e vazio: ninguem esta a bordo.
  // Contá-lo como "com passageiros" inflava o número em dezenas de minutos.
  // Esta decomposição fecha exatamente: vazioIda + aBordo + volta = jornada.
  const vazioIdaSeg = ordem.length
    ? ctx.dur[0][ordem[0] + 1] + ctx.pontos[ordem[0]].servicoSeg
    : durSeg;
  const aBordoSeg = ordem.length ? rideSeg[0] : 0;
  return {
    ordem: ordem.slice(),
    durSeg: durSeg, distM: distM,
    durMin: Math.round(durSeg / 60), distKm: distM / 1000,
    violacoes: violacoes, maiorRideMin: Math.round(maiorRide),
    rideMin: rideSeg.map(s => Math.round(s / 60)),
    embarqueMin: embarqueMin, saidaGaragem: saidaGaragem,
    voltaSeg: voltaSeg, voltaMin: Math.round(voltaSeg / 60),
    vazioIdaSeg: vazioIdaSeg, vazioIdaMin: Math.round(vazioIdaSeg / 60),
    aBordoSeg: aBordoSeg, aBordoMin: Math.round(aBordoSeg / 60),
    vazioTotalSeg: vazioIdaSeg + voltaSeg,
    jornadaSeg: durSeg + voltaSeg, jornadaMin: Math.round((durSeg + voltaSeg) / 60),
    jornadaKm: (distM + voltaM) / 1000,
    retornoGaragem: chegada + Math.round(voltaSeg / 60)
  };
}

// ---------- comparacao lexicografica ----------
// 1) violacoes  2) duracao  3) distancia  4) menor mudanca em relacao a atual.
// Uma candidata um pouco mais longa PODE vencer se eliminar uma violacao.
function optComparar(a, b) {
  // Violação sempre vem primeiro: é regra operacional, não preferência.
  if (a.violacoes !== b.violacoes) return a.violacoes - b.violacoes;
  if (OPT_CFG.objetivo === 'distancia') {
    if (Math.abs(a.distM - b.distM) > 1) return a.distM - b.distM;
    if (a.durSeg !== b.durSeg) return a.durSeg - b.durSeg;
    return 0;
  }
  if (OPT_CFG.objetivo === 'equilibrado') {
    // 1 km equivale a 1 minuto: põe as duas grandezas na mesma régua.
    const ca = a.durSeg + (a.distM / 1000) * 60;
    const cb = b.durSeg + (b.distM / 1000) * 60;
    if (Math.abs(ca - cb) > 1) return ca - cb;
    return 0;
  }
  if (a.durSeg !== b.durSeg) return a.durSeg - b.durSeg;
  if (Math.abs(a.distM - b.distM) > 1) return a.distM - b.distM;
  return 0;
}

function optDiferencaOrdem(a, b) {
  let d = 0;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) d++;
  return d;
}

// ---------- solver exato (Held-Karp sobre sufixos) ----------
// Faz DP de tras para frente porque o tempo do passageiro dentro do veiculo
// depende so do que vem DEPOIS dele. Assim a restricao de 60 min entra na
// escolha da solucao, e nao como alerta calculado no fim.
function optResolverExato(ctx) {
  const K = ctx.pontos.length, EMP = K + 1;
  const total = 1 << K;
  const melhor = new Array(total);
  for (let s = 0; s < total; s++) melhor[s] = new Array(K).fill(null);

  const custoPonto = (i, T) => {
    // T = duracao do sufixo a partir da SAIDA do ponto i
    const min = T / 60;
    return min > OPT_CFG.maxRideMin ? ctx.pontos[i].passageiros.length : 0;
  };

  for (let i = 0; i < K; i++) {
    const durIE = ctx.dur[i + 1][EMP];
    melhor[1 << i][i] = {
      viol: custoPonto(i, durIE),
      dur: ctx.pontos[i].servicoSeg + durIE,
      dist: ctx.dist[i + 1][EMP],
      prox: -1
    };
  }

  for (let s = 1; s < total; s++) {
    for (let i = 0; i < K; i++) {
      if (!(s & (1 << i))) continue;
      const resto = s & ~(1 << i);
      if (resto === 0) continue;
      let best = null;
      for (let j = 0; j < K; j++) {
        if (!(resto & (1 << j))) continue;
        const sub = melhor[resto][j];
        if (!sub) continue;
        const durIJ = ctx.dur[i + 1][j + 1];
        const sufixo = durIJ + sub.dur;              // a partir da saida de i
        const cand = {
          viol: sub.viol + custoPonto(i, sufixo),
          dur: ctx.pontos[i].servicoSeg + sufixo,
          dist: ctx.dist[i + 1][j + 1] + sub.dist,
          prox: j
        };
        if (!best || cand.viol !== best.viol ? (best && cand.viol > best.viol ? false : true) : false) {
          // comparacao lexicografica explicita abaixo
        }
        if (!best ||
            cand.viol < best.viol ||
            (cand.viol === best.viol && cand.dur < best.dur) ||
            (cand.viol === best.viol && cand.dur === best.dur && cand.dist < best.dist)) {
          best = cand;
        }
      }
      melhor[s][i] = best;
    }
  }

  const cheio = total - 1;
  let inicio = -1, melhorTotal = null;
  for (let i = 0; i < K; i++) {
    const sub = melhor[cheio][i];
    if (!sub) continue;
    const cand = {
      viol: sub.viol,
      dur: ctx.dur[0][i + 1] + sub.dur,
      dist: ctx.dist[0][i + 1] + sub.dist
    };
    if (!melhorTotal ||
        cand.viol < melhorTotal.viol ||
        (cand.viol === melhorTotal.viol && cand.dur < melhorTotal.dur) ||
        (cand.viol === melhorTotal.viol && cand.dur === melhorTotal.dur && cand.dist < melhorTotal.dist)) {
      melhorTotal = cand; inicio = i;
    }
  }
  if (inicio < 0) return null;

  const ordem = [];
  let s = cheio, i = inicio;
  while (i >= 0) { ordem.push(i); const nx = melhor[s][i].prox; s = s & ~(1 << i); i = nx; }
  return ordem;
}

// ---------- solver heuristico (muitos pontos) ----------
// Sempre semeado com a ordem atual e so aceita melhora, entao o resultado
// nunca pode ser pior que a rota de hoje.
function optResolverHeuristico(ctx, ordemAtual) {
  const K = ctx.pontos.length, EMP = K + 1;
  const sementes = [ordemAtual.slice()];

  // vizinho mais proximo a partir da garagem
  const restante = [];
  for (let i = 0; i < K; i++) restante.push(i);
  const nn = [];
  let atual = 0;
  while (restante.length) {
    let melhorI = 0;
    for (let k = 1; k < restante.length; k++)
      if (ctx.dur[atual][restante[k] + 1] < ctx.dur[atual][restante[melhorI] + 1]) melhorI = k;
    const escolhido = restante.splice(melhorI, 1)[0];
    nn.push(escolhido); atual = escolhido + 1;
  }
  sementes.push(nn);

  let melhor = null;
  sementes.forEach(sem => {
    let cur = sem.slice(), curM = optAvaliarOrdem(cur, ctx), mudou = true, voltas = 0;
    while (mudou && voltas < 60) {
      mudou = false; voltas++;
      for (let i = 0; i < cur.length - 1; i++) {
        for (let j = i + 1; j < cur.length; j++) {
          const alt = cur.slice(0, i).concat(cur.slice(i, j + 1).reverse(), cur.slice(j + 1)); // 2-opt
          const m = optAvaliarOrdem(alt, ctx);
          if (optComparar(m, curM) < 0) { cur = alt; curM = m; mudou = true; }
        }
      }
      for (let i = 0; i < cur.length; i++) {           // Or-opt: move 1 ponto
        for (let j = 0; j < cur.length; j++) {
          if (i === j) continue;
          const alt = cur.slice(); const [x] = alt.splice(i, 1); alt.splice(j, 0, x);
          const m = optAvaliarOrdem(alt, ctx);
          if (optComparar(m, curM) < 0) { cur = alt; curM = m; mudou = true; }
        }
      }
    }
    if (!melhor || optComparar(curM, melhor.m) < 0) melhor = { ordem: cur, m: curM };
  });
  return melhor.ordem;
}

// ---------- orquestrador puro ----------
// Recebe a matriz pronta e devolve a decisao. Sem rede, sem DOM: testavel.
function optDecidir(ctx, ordemAtual) {
  const atual = optAvaliarOrdem(ordemAtual, ctx);
  const K = ctx.pontos.length;
  let candidataOrdem;
  if (K <= 1) candidataOrdem = ordemAtual.slice();
  else if (K <= OPT_CFG.exactMaxPoints) candidataOrdem = optResolverExato(ctx) || ordemAtual.slice();
  else candidataOrdem = optResolverHeuristico(ctx, ordemAtual);

  const candidata = optAvaliarOrdem(candidataOrdem, ctx);
  const cmp = optComparar(candidata, atual);

  // ---- vale a pena aplicar? ----
  // O solver ja devolveu a melhor sequencia possivel; aqui decidimos se a
  // diferenca justifica mexer na operacao. Sem Math.abs: piorar 200 m e
  // diferente de melhorar 200 m, e a versao anterior tratava os dois igual.
  const ganhoDur = atual.durSeg - candidata.durSeg;     // >0 = mais rapida
  const ganhoDist = atual.distM - candidata.distM;      // >0 = mais curta
  let melhorou = false;
  let motivo = '';

  if (cmp < 0 && candidata.violacoes < atual.violacoes) {
    // Menos gente acima do limite vence sempre, mesmo custando alguns minutos.
    melhorou = true;
    motivo = 'menos passageiros acima do limite';
  } else if (cmp < 0 && candidata.violacoes === atual.violacoes) {
    if (!OPT_CFG.preservarOrdem) {
      // Sem a trava, qualquer ganho no score já vale.
      melhorou = true;
      motivo = ganhoDur > 0 ? 'ganho de tempo' : 'ganho de distância';
    } else if (ganhoDur >= OPT_CFG.minGanhoSegundos) {
      melhorou = true;
      motivo = 'ganho de tempo';
    } else if (ganhoDur >= -OPT_CFG.tolPioraSegundos && ganhoDist >= OPT_CFG.minGanhoMetros) {
      // Tempo empatado na pratica, mas a rota encurta de verdade.
      melhorou = true;
      motivo = 'ganho de distância';
    }
    // Qualquer outro caso — inclusive ganhar segundos perdendo metros —
    // nao justifica remexer a ordem de embarque de ninguem.
  }

  return {
    atual: atual,
    candidata: candidata,
    melhorou: melhorou,
    motivo: motivo,
    ganhoDurSeg: ganhoDur,
    ganhoDistM: ganhoDist,
    mudancas: optDiferencaOrdem(atual.ordem, candidata.ordem),
    exato: K <= OPT_CFG.exactMaxPoints,
    ganhoMin: atual.durMin - candidata.durMin,
    ganhoKm: (atual.distM - candidata.distM) / 1000
  };
}

// ==================================================================
// PLANEJADOR DE MULTIPLAS ROTAS
// ------------------------------------------------------------------
// O otimizador responde "qual a melhor ordem para esta lista".
// O planejador responde "quantas listas, e quem vai em cada uma".
// Roda sobre a MESMA matriz e reaproveita o MESMO solver de ordem.
// ==================================================================

// Capacidade que o solver pode usar: a operacional menos a reserva.
// A reserva e explicita — se ela inviabilizar o plano, o planejador avisa
// em vez de ignorar o parametro.
function planCapacidadeUtil(veic, reserva) {
  const cap = frCapacidadeDe(veic);
  return Math.max(0, cap - (reserva || 0));
}

// Frota disponivel, do menor para o maior. Sem cadastro, o planejador nao
// tem como dimensionar: quem chama trata esse caso.
// "Na oficina" e "hoje saiu para um extra" sao coisas diferentes: a primeira
// e cadastro (v.ativo), a segunda e deste planejamento (PL_FROTA_LIVRE).
// Sem separar, o gestor desmarcaria o mesmo veiculo todo dia.
let PL_FROTA_LIVRE = null;   // null = todos os ativos

function planFrotaDisponivel(reserva) {
  const ativos = FROTA.filter(v => v.ativo !== false);
  // Se a frota mudou depois da seleção, os ids guardados podem não existir
  // mais. Selecão vazia significa "não sei", não "nenhum veículo".
  const valida = PL_FROTA_LIVRE && ativos.some(v => PL_FROTA_LIVRE.has(v.id));
  return ativos
    .filter(v => !valida || PL_FROTA_LIVRE.has(v.id))
    .map(v => ({ veic: v, cap: planCapacidadeUtil(v, reserva) }))
    .filter(x => x.cap > 0)
    .sort((a, b) => a.cap - b.cap);
}

// Uma "rota candidata" durante o planejamento: sequencia de indices de ponto.
function planDemanda(seq, pontos) {
  return seq.reduce((n, i) => n + pontos[i].passageiros.length, 0);
}

// Uma rota so e viavel se: cabe no veiculo e ninguem passa do limite.
// Devolve a metrica junto, para nao calcular duas vezes.
function planViavel(seq, ctx, capMax) {
  if (planDemanda(seq, ctx.pontos) > capMax) return null;
  const m = optAvaliarOrdem(seq, ctx);
  if (m.violacoes > 0) return null;
  return m;
}

// ---------- economias de Clarke-Wright, adaptadas ----------
// Formato real: garagem -> pontos -> empresa. Juntar a rota que TERMINA em A
// com a que COMECA em B economiza o retorno de A a empresa e a ida da garagem
// ate B, pagando o trecho A->B.
function planEconomias(ctx) {
  const K = ctx.pontos.length, EMP = K + 1, lista = [];
  for (let a = 0; a < K; a++) {
    for (let b = 0; b < K; b++) {
      if (a === b) continue;
      const s = ctx.dur[a + 1][EMP] + ctx.dur[0][b + 1] - ctx.dur[a + 1][b + 1];
      lista.push({ a: a, b: b, s: s });
    }
  }
  return lista.sort((x, y) => y.s - x.s);
}

// ---------- nucleo: monta as rotas ----------
// travas.grupos: listas de indices de ponto que devem ficar juntos
// capMax: maior capacidade util disponivel na frota
function planAgrupar(ctx, capMax, travas, aceitarPiora) {
  const K = ctx.pontos.length;
  // cada ponto comeca sozinho, exceto os grupos travados
  let rotas = [];
  const jaColocado = new Set();
  (travas.grupos || []).forEach(gr => {
    const seq = gr.filter(i => i >= 0 && i < K && !jaColocado.has(i));
    if (!seq.length) return;
    seq.forEach(i => jaColocado.add(i));
    rotas.push(seq.slice());
  });
  for (let i = 0; i < K; i++) if (!jaColocado.has(i)) rotas.push([i]);

  const donoDe = new Map();
  rotas.forEach((r, ri) => r.forEach(i => donoDe.set(i, ri)));

  const economias = planEconomias(ctx);
  for (const e of economias) {
    if (!aceitarPiora && e.s <= 0) break;   // sem economia, nao junta
    const ra = donoDe.get(e.a), rb = donoDe.get(e.b);
    if (ra === undefined || rb === undefined || ra === rb) continue;
    const A = rotas[ra], B = rotas[rb];
    if (!A || !B) continue;
    // so junta ponta com ponta: A termina em 'a', B comeca em 'b'
    if (A[A.length - 1] !== e.a || B[0] !== e.b) continue;
    const juntas = A.concat(B);
    if (!planViavel(juntas, ctx, capMax)) continue;
    rotas[ra] = juntas;
    rotas[rb] = null;
    juntas.forEach(i => donoDe.set(i, ra));
  }
  return rotas.filter(Boolean);
}

// ---------- atribuicao de veiculos ----------
// Rota mais cheia pega o menor veiculo que a comporta. Sobrando rota sem
// veiculo, o plano e inviavel — e o planejador diz isso.
function planAtribuirVeiculos(rotas, ctx, frota) {
  const disponiveis = frota.map(x => ({ ...x, usado: false }));
  const ordem = rotas
    .map((seq, i) => ({ i: i, dem: planDemanda(seq, ctx.pontos) }))
    .sort((a, b) => b.dem - a.dem);
  const atribuicao = new Array(rotas.length).fill(null);
  let faltou = 0;
  ordem.forEach(({ i, dem }) => {
    const escolhido = disponiveis.find(x => !x.usado && x.cap >= dem);
    if (escolhido) { escolhido.usado = true; atribuicao[i] = escolhido; }
    else faltou++;
  });
  return { atribuicao: atribuicao, faltou: faltou };
}

// ---------- reotimiza a ordem de cada rota ----------
function planOtimizarOrdens(rotas, ctx) {
  return rotas.map(seq => {
    if (seq.length <= 2) return seq;
    const sub = planSubContexto(ctx, seq);
    const melhor = seq.length <= OPT_CFG.exactMaxPoints
      ? optResolverExato(sub)
      : optResolverHeuristico(sub, seq.map((_, k) => k));
    if (!melhor) return seq;
    const nova = melhor.map(k => seq[k]);
    // so troca se realmente melhorar nesta mesma base
    const antes = optAvaliarOrdem(seq, ctx), depois = optAvaliarOrdem(nova, ctx);
    return optComparar(depois, antes) < 0 ? nova : seq;
  });
}

// Recorta a matriz global para os pontos de uma rota. O solver exato trabalha
// com indices 0..n-1, entao precisa da sua propria matriz.
function planSubContexto(ctx, seq) {
  const n = seq.length, N = n + 2, EMPg = ctx.pontos.length + 1;
  const dur = Array.from({ length: N }, () => new Array(N).fill(0));
  const dist = Array.from({ length: N }, () => new Array(N).fill(0));
  for (let i = 0; i < n; i++) {
    dur[0][i + 1] = ctx.dur[0][seq[i] + 1];
    dist[0][i + 1] = ctx.dist[0][seq[i] + 1];
    dur[i + 1][n + 1] = ctx.dur[seq[i] + 1][EMPg];
    dist[i + 1][n + 1] = ctx.dist[seq[i] + 1][EMPg];
    for (let j = 0; j < n; j++) {
      dur[i + 1][j + 1] = ctx.dur[seq[i] + 1][seq[j] + 1];
      dist[i + 1][j + 1] = ctx.dist[seq[i] + 1][seq[j] + 1];
    }
  }
  return { dur: dur, dist: dist, pontos: seq.map(i => ctx.pontos[i]), chegadaMin: ctx.chegadaMin };
}

// ---------- controle do numero de rotas ----------
// Junta rotas alem do ponto de economia positiva, para caber no limite pedido.
function planReduzirPara(rotas, ctx, capMax, alvo) {
  let atual = rotas.slice();
  let voltas = 0;
  while (atual.length > alvo && voltas < 200) {
    voltas++;
    let melhor = null;
    for (let i = 0; i < atual.length; i++) {
      for (let j = 0; j < atual.length; j++) {
        if (i === j) continue;
        const juntas = atual[i].concat(atual[j]);
        const m = planViavel(juntas, ctx, capMax);
        if (!m) continue;
        if (!melhor || m.durSeg < melhor.m.durSeg) melhor = { i: i, j: j, seq: juntas, m: m };
      }
    }
    if (!melhor) break;   // nao da para juntar mais sem violar regra
    const nova = [];
    atual.forEach((r, k) => { if (k !== melhor.i && k !== melhor.j) nova.push(r); });
    nova.push(melhor.seq);
    atual = nova;
  }
  return atual;
}

// Divide a rota mais cheia, para chegar ao numero pedido.
function planAumentarPara(rotas, ctx, alvo) {
  let atual = rotas.slice();
  let voltas = 0;
  while (atual.length < alvo && voltas < 200) {
    voltas++;
    let alvoIdx = -1, maior = 1;
    atual.forEach((r, i) => { if (r.length > maior) { maior = r.length; alvoIdx = i; } });
    if (alvoIdx < 0) break;   // todas com um ponto so: nao da para dividir
    const r = atual[alvoIdx];
    let corte = null;
    for (let c = 1; c < r.length; c++) {
      const a = r.slice(0, c), b = r.slice(c);
      const ma = optAvaliarOrdem(a, ctx), mb = optAvaliarOrdem(b, ctx);
      const custo = ma.durSeg + mb.durSeg;
      if (!corte || custo < corte.custo) corte = { c: c, custo: custo };
    }
    if (!corte) break;
    atual.splice(alvoIdx, 1, r.slice(0, corte.c), r.slice(corte.c));
  }
  return atual;
}

// ==================================================================
// planejarRotas — a porta de entrada
// ==================================================================
// opts = { modoRotas: 'auto'|'max'|'exato', numRotas, reservaVagas,
//          travas: { grupos: [[idx,...]], rotasFixas: [{pontos, veiculoId}] } }
function planejarRotas(ctx, opts) {
  opts = opts || {};
  const travas = opts.travas || {};
  const reserva = (opts.reservaVagas !== undefined && opts.reservaVagas !== null)
    ? opts.reservaVagas : OPT_CFG.reservaVagas;
  const frota = planFrotaDisponivel(reserva);

  const diag = { reserva: reserva, etapas: [] };
  const passo = t => diag.etapas.push(t);

  if (!frota.length) {
    return { ok: false, motivo: 'sem-frota',
      mensagem: 'Nenhum veículo da frota tem vaga disponível' +
        (reserva > 0 ? ' com reserva de ' + reserva + '.' : '. Cadastre a frota em Configurações.'),
      diag: diag };
  }
  const capMax = frota[frota.length - 1].cap;
  passo('Frota: ' + frota.length + ' veículos, maior com ' + capMax + ' vagas' +
        (reserva > 0 ? ' (já descontada a reserva de ' + reserva + ')' : ''));

  // Ponto que sozinho ja estoura o maior veiculo: nao ha plano possivel.
  const grandeDemais = ctx.pontos.filter(p => p.passageiros.length > capMax);
  if (grandeDemais.length) {
    return { ok: false, motivo: 'ponto-grande',
      mensagem: 'O ponto "' + grandeDemais[0].rotulo + '" tem ' +
        grandeDemais[0].passageiros.length + ' passageiros e o maior veículo comporta ' +
        capMax + '. Separe o ponto ou cadastre um veículo maior.',
      diag: diag };
  }

  // Passageiro que, sozinho na van, ja passa do limite de tempo. Dividir a rota
  // nao resolve — nao existe plano. Dizer isso e melhor do que culpar a frota.
  const longeDemais = [];
  ctx.pontos.forEach((p, i) => {
    const m = optAvaliarOrdem([i], ctx);
    if (m.violacoes > 0) longeDemais.push({ p: p, min: m.rideMin[0] });
  });
  if (longeDemais.length) {
    return { ok: false, motivo: 'ponto-longe',
      mensagem: 'Mesmo sozinho no veículo, ' +
        (longeDemais.length === 1
          ? '"' + longeDemais[0].p.rotulo + '" ficaria ' + longeDemais[0].min + ' min em viagem'
          : longeDemais.length + ' pontos passariam do limite') +
        ', acima do máximo de ' + OPT_CFG.maxRideMin + ' min. Nenhuma divisão de rotas resolve isso: ' +
        'reveja o limite em Configurações ou o ponto de embarque.',
      pontos: longeDemais.map(x => x.p.rotulo), diag: diag };
  }

  // 1) agrupa
  let rotas = planAgrupar(ctx, capMax, travas, false);
  passo(rotas.length + ' agrupamentos formados pela geografia');

  // 2) numero de rotas pedido
  const minimoViavel = planReduzirPara(rotas, ctx, capMax, 1).length;
  if (opts.modoRotas === 'max' || opts.modoRotas === 'exato') {
    const alvo = Math.max(1, parseInt(opts.numRotas, 10) || 1);
    if (rotas.length > alvo) rotas = planReduzirPara(rotas, ctx, capMax, alvo);
    if (opts.modoRotas === 'exato' && rotas.length < alvo) rotas = planAumentarPara(rotas, ctx, alvo);
    const falhou = (opts.modoRotas === 'max' && rotas.length > alvo) ||
                   (opts.modoRotas === 'exato' && rotas.length !== alvo);
    if (falhou) {
      return { ok: false, motivo: 'restricao-impossivel',
        mensagem: 'Não existe plano com ' + (opts.modoRotas === 'max' ? 'no máximo ' : 'exatamente ') +
          alvo + (alvo === 1 ? ' rota' : ' rotas') + ' respeitando capacidade e o limite de ' +
          OPT_CFG.maxRideMin + ' min por passageiro. O mínimo viável é ' + minimoViavel +
          (minimoViavel === 1 ? ' rota' : ' rotas') + '.',
        minimoViavel: minimoViavel, diag: diag };
    }
    passo('Ajustado para ' + rotas.length + ' rotas conforme pedido');
  }

  // 3) ordem otima dentro de cada rota
  rotas = planOtimizarOrdens(rotas, ctx);
  passo('Ordem de embarque otimizada em cada rota');

  // 4) veiculos
  const { atribuicao, faltou } = planAtribuirVeiculos(rotas, ctx, frota);
  if (faltou) {
    // Distinguir DUAS causas que parecem a mesma. Se os assentos somados dao
    // conta de todo mundo, o gargalo nao e a frota: e o numero de rotas que a
    // geografia e o limite de tempo obrigam. Mandar comprar van nesse caso e
    // mandar o gestor gastar dinheiro no lugar errado.
    const totalPax = ctx.pontos.reduce((n, p) => n + p.passageiros.length, 0);
    const assentos = frota.reduce((n, x) => n + x.cap, 0);
    const sobramAssentos = assentos >= totalPax;
    let msg;
    if (sobramAssentos) {
      msg = 'O limite de ' + OPT_CFG.maxRideMin + ' min por passageiro obriga a dividir em ' +
        rotas.length + ' rotas, e a frota tem ' + frota.length +
        (frota.length === 1 ? ' veículo' : ' veículos') + '. ' +
        'Assento não é o problema: são ' + assentos + ' vagas para ' + totalPax + ' passageiros. ' +
        'Falta veículo para rodar em paralelo — ou o limite de tempo precisa ser revisto.';
    } else {
      msg = 'A frota não comporta todo mundo: ' + assentos + ' vagas para ' + totalPax +
        ' passageiros' +
        (reserva > 0 ? ' (a reserva de ' + reserva + ' vaga(s) por veículo já está descontada)' : '') +
        '. Cadastre mais um veículo em Configurações › Frota.';
    }
    return { ok: false, motivo: 'frota-insuficiente', mensagem: msg,
      rotasNecessarias: rotas.length, veiculosDisponiveis: frota.length,
      assentosDisponiveis: assentos, totalPassageiros: totalPax,
      sobramAssentos: sobramAssentos, diag: diag };
  }
  passo('Veículos atribuídos');

  // 5) metricas finais, todas na mesma base
  // A otimizacao roda no espaco do solver; a ENTREGA e no sentido real. Na
  // saida a sequencia do solver esta invertida. Faltava isto: as portas
  // optAvaliar/optResolver existiam e ninguem as chamava.
  const detalhe = rotas.map((seq, i) => {
    const seqReal = ctx._saida ? seq.slice().reverse() : seq;
    const m = optAvaliar(seqReal, ctx);
    const at = atribuicao[i];
    return {
      seq: seqReal, metrica: m,
      veiculoId: at.veic.id, veiculoRotulo: frRotulo(at.veic),
      capacidade: at.cap, ocupacao: planDemanda(seq, ctx.pontos)
    };
  }).sort((a, b) => ctx._saida
      ? (a.metrica.retornoGaragem - b.metrica.retornoGaragem)
      : (a.metrica.saidaGaragem - b.metrica.saidaGaragem));

  const total = detalhe.reduce((acc, r) => ({
    durSeg: acc.durSeg + r.metrica.durSeg,
    distM: acc.distM + r.metrica.distM,
    violacoes: acc.violacoes + r.metrica.violacoes,
    pax: acc.pax + r.ocupacao
  }), { durSeg: 0, distM: 0, violacoes: 0, pax: 0 });

  return {
    ok: true, rotas: detalhe, total: total, reserva: reserva,
    minimoViavel: minimoViavel, diag: diag
  };
}

// ==================================================================
// ROTA DE SAÍDA
// ------------------------------------------------------------------
// Uma saída é uma entrada de trás para frente. Em vez de escrever um
// segundo solver — que teria os próprios defeitos e a própria manutenção —
// convertemos o problema e reaproveitamos o que já está testado.
// ==================================================================

// Recebe o contexto da saída, no sentido real:
//   índice 0   = ponto de partida (a empresa, de onde todos saem)
//   1..K       = pontos de desembarque
//   K+1        = ponto final (a garagem)
//   partidaMin = horário de saída da empresa
// Devolve o contexto invertido, que o solver de entrada entende.
function optContextoSaida(ctxSaida) {
  const K = ctxSaida.pontos.length, N = K + 2;
  const dur = Array.from({ length: N }, () => new Array(N).fill(0));
  const dist = Array.from({ length: N }, () => new Array(N).fill(0));
  // Transpor não basta: as PONTAS também trocam de papel. No mundo invertido
  // o índice 0 é a garagem (fim real) e o K+1 é a empresa (partida real).
  //    inv[i][j] = real[trocaPonta(j)][trocaPonta(i)]
  // Sem a troca, o solver pedia "garagem -> ponto" onde só existia medição de
  // "ponto -> garagem", e os tempos vinham zerados.
  const p = k => (k === 0 ? N - 1 : (k === N - 1 ? 0 : k));
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      dur[i][j] = ctxSaida.dur[p(j)][p(i)];
      dist[i][j] = ctxSaida.dist[p(j)][p(i)];
    }
  }
  return {
    dur: dur, dist: dist,
    pontos: ctxSaida.pontos,
    // o solver trabalha com "chegada"; aqui ela é a partida da empresa
    chegadaMin: ctxSaida.partidaMin,
    _saida: true, _partidaMin: ctxSaida.partidaMin
  };
}

// Traduz de volta o que o solver devolveu, para o mundo real da saída.
// Os horários vêm espelhados em torno da hora fixa: real = 2T - solver.
function optMetricaSaida(m, ctxInv) {
  const T = ctxInv._partidaMin;
  const espelho = min => 2 * T - min;
  return Object.assign({}, m, {
    // a ordem do solver está invertida: a primeira parada real é a última dele
    ordem: m.ordem.slice().reverse(),
    rideMin: m.rideMin.slice().reverse(),
    // "embarque" na saída é o DESEMBARQUE de cada passageiro
    embarqueMin: m.embarqueMin.slice().reverse().map(espelho),
    desembarqueMin: m.embarqueMin.slice().reverse().map(espelho),
    // o solver chama de "saída da garagem" o fim da rota invertida:
    // no mundo real é a volta à garagem
    saidaGaragem: T,
    partidaEmpresa: T,
    retornoGaragem: espelho(m.saidaGaragem),
    // vazio da ida na saída é o trecho garagem -> empresa, que o solver
    // enxerga como a volta
    vazioIdaSeg: m.voltaSeg, vazioIdaMin: m.voltaMin,
    voltaSeg: m.vazioIdaSeg, voltaMin: m.vazioIdaMin,
    sentido: 'saida'
  });
}

// Porta única: avalia uma ordem no sentido certo, seja qual for.
function optAvaliar(ordem, ctx) {
  if (!ctx._saida) return optAvaliarOrdem(ordem, ctx);
  // na saída a ordem chega no sentido real; o solver precisa dela invertida
  const m = optAvaliarOrdem(ordem.slice().reverse(), ctx);
  return optMetricaSaida(m, ctx);
}

// Resolve a melhor sequência no sentido certo.
function optResolver(ctx) {
  const K = ctx.pontos.length;
  const ordem = K <= OPT_CFG.exactMaxPoints
    ? optResolverExato(ctx)
    : optResolverHeuristico(ctx, ctx.pontos.map((_, i) => i));
  if (!ordem) return null;
  return ctx._saida ? ordem.slice().reverse() : ordem;
}

// ---------- matriz (unico ponto que fala com o Google) ----------
// Cache por conjunto de coordenadas: a matriz e o item caro da conta.
// (K+1)x(K+1) elementos; com 9 pontos sao 100 elementos, o teto de um
// unico request client-side do Distance Matrix.
const OPT_MATRIZ_CACHE = {};

function optChaveMatriz(pontos) {
  const r = n => Math.round(n * 1e5) / 1e5;
  return [r(GARAGEM_COORDS.lat), r(GARAGEM_COORDS.lng), r(EMPRESA_COORDS.lat), r(EMPRESA_COORDS.lng)]
    .concat(pontos.map(p => r(p.lat) + ',' + r(p.lng)).sort()).join('|');
}

// Limites do DistanceMatrixService (client-side), todos simultaneos:
//   no maximo 25 origens, 25 destinos e 100 elementos por requisicao.
// Fatiar so um dos lados nao basta — foi o que causou MAX_DIMENSIONS_EXCEEDED
// com 27 pontos: 84 elementos (dentro do teto) mas 28 destinos (fora).
const OPT_MAX_LADO = 25;
const OPT_MAX_ELEMENTOS = 100;

// Escolhe o tamanho dos blocos para gastar o menor numero de requisicoes.
// Com os dois lados grandes, 10x10 enche os 100 elementos exatos.
function optLotes(nOrig, nDest) {
  let dest = Math.min(nDest, OPT_MAX_LADO);
  let orig = Math.min(nOrig, OPT_MAX_LADO, Math.max(1, Math.floor(OPT_MAX_ELEMENTOS / dest)));
  if (orig * dest > OPT_MAX_ELEMENTOS || (nOrig > orig && nDest > dest)) {
    const lado = Math.floor(Math.sqrt(OPT_MAX_ELEMENTOS));   // 10
    dest = Math.min(nDest, lado);
    orig = Math.min(nOrig, Math.max(1, Math.floor(OPT_MAX_ELEMENTOS / dest)));
  }
  return { orig: Math.max(1, orig), dest: Math.max(1, dest) };
}

function optPedirMatriz(svc, origens, destinos) {
  return new Promise((ok, err) => {
    let tentativas = 0;
    const tentar = () => {
      svc.getDistanceMatrix({
        origins: origens, destinations: destinos,
        travelMode: google.maps.TravelMode.DRIVING
      }, (r, st) => {
        if (st === 'OK') return ok(r);
        // Transitorios do lado do Google. UNKNOWN_ERROR e o codigo que a
        // propria documentacao manda repetir; e o que aparece quando o
        // servico devolve 502 e o navegador reporta como falha de CORS.
        if ((st === 'OVER_QUERY_LIMIT' || st === 'UNKNOWN_ERROR') && tentativas < 3) {
          tentativas++;
          setTimeout(tentar, 600 * tentativas);
          return;
        }
        err(new Error('Distance Matrix: ' + st));
      });
    };
    tentar();
  });
}

// sentido = 'entrada' (garagem -> pontos -> empresa) ou 'saida'
// (empresa -> pontos -> garagem). NUNCA transpor a matriz da entrada para
// obter a da saída: rua de mão única e viaduto fazem t(a,b) != t(b,a).
async function optObterMatriz(pontos, aoProgredir, sentido) {
  const chave = (sentido === 'saida' ? 'S|' : 'E|') + optChaveMatriz(pontos);
  if (OPT_MATRIZ_CACHE[chave]) {
    if (aoProgredir) aoProgredir('Tempos entre os pontos (reaproveitados desta sessão)');
    return OPT_MATRIZ_CACHE[chave];
  }
  const K = pontos.length, N = K + 2, EMP = K + 1;
  const LL = c => new google.maps.LatLng(c.lat, c.lng);
  // origens: garagem + pontos (a empresa nunca e origem)
  // destinos: pontos + empresa (a garagem nunca e destino)
  // na saída o veículo parte da empresa e termina na garagem
  const PARTIDA = (sentido === 'saida') ? EMPRESA_COORDS : GARAGEM_COORDS;
  const FIM = (sentido === 'saida') ? GARAGEM_COORDS : EMPRESA_COORDS;
  const origens = [LL(PARTIDA)].concat(pontos.map(LL));
  const destinos = pontos.map(LL).concat([LL(FIM)]);

  const dur = Array.from({ length: N }, () => new Array(N).fill(0));
  const dist = Array.from({ length: N }, () => new Array(N).fill(0));

  const svc = new google.maps.DistanceMatrixService();
  const lote = optLotes(origens.length, destinos.length);
  const totalReq = Math.ceil(origens.length / lote.orig) * Math.ceil(destinos.length / lote.dest);
  let elementos = 0, requisicoes = 0;

  if (aoProgredir && totalReq > 1)
    aoProgredir('Consultando tempos em ' + totalReq + ' blocos');

  for (let oi = 0; oi < origens.length; oi += lote.orig) {
    const fatiaO = origens.slice(oi, oi + lote.orig);
    for (let di = 0; di < destinos.length; di += lote.dest) {
      const fatiaD = destinos.slice(di, di + lote.dest);
      const res = await optPedirMatriz(svc, fatiaO, fatiaD);
      requisicoes++;
      res.rows.forEach((linha, li) => {
        const oIdx = oi + li;                    // 0 = garagem, 1..K = pontos
        linha.elements.forEach((el, dli) => {
          elementos++;
          const dAbs = di + dli;
          const dIdx = (dAbs < K) ? dAbs + 1 : EMP;
          if (el.status !== 'OK') { dur[oIdx][dIdx] = 1e9; dist[oIdx][dIdx] = 1e9; return; }
          dur[oIdx][dIdx] = el.duration.value;
          dist[oIdx][dIdx] = el.distance.value;
        });
      });
      if (aoProgredir && totalReq > 1 && requisicoes < totalReq)
        aoProgredir('Tempos entre os pontos: bloco ' + requisicoes + ' de ' + totalReq);
      if (requisicoes < totalReq) await new Promise(r => setTimeout(r, 120));
    }
  }
  // Um elemento a mais: a volta vazia da empresa para a garagem. Sem ele a
  // jornada do veículo fica pela metade.
  try {
    const rVolta = await optPedirMatriz(svc, [LL(FIM)], [LL(PARTIDA)]);
    const el = rVolta.rows[0].elements[0];
    if (el.status === 'OK') { dur[EMP][0] = el.duration.value; dist[EMP][0] = el.distance.value; }
    elementos++;
  } catch (e) { console.warn('volta empresa→garagem não medida:', e.message); }

  if (aoProgredir) aoProgredir('Tempos entre os pontos calculados (' + elementos + ' trechos)');

  const m = { dur: dur, dist: dist, elementos: elementos, requisicoes: requisicoes };
  OPT_MATRIZ_CACHE[chave] = m;
  // Diagnostico interno. O custo nunca aparece para o gestor.
  console.info('[matriz]', K, 'pontos ·', elementos, 'elementos ·', requisicoes,
               'requisição(ões) · custo estimado US$', (elementos * 0.005).toFixed(2));
  return m;
}

function optLimparCacheMatriz() { Object.keys(OPT_MATRIZ_CACHE).forEach(k => delete OPT_MATRIZ_CACHE[k]); }

async function getCoords(geocoder, p) {
  if (p.lat && p.lng && Math.abs(p.lat) > 1 && Math.abs(p.lng) > 1) {
    return { lat: p.lat, lng: p.lng };
  }
  const addr = getPassengerAddress(p);
  return await geocodeAddress(geocoder, addr, p.cidade);
}

function otPasso(txt, estado) {
  const box = document.getElementById('otPassos');
  if (!box) return;
  const div = document.createElement('div');
  div.className = 'ot-passo ' + (estado || 'ok');
  div.textContent = (estado === 'run' ? '· ' : estado === 'erro' ? '× ' : '✓ ') + txt;
  box.appendChild(div);
}
function otLimparPassos() { const b = document.getElementById('otPassos'); if (b) b.innerHTML = ''; }

function otHHMM(min) {
  const m = ((Math.round(min) % 1440) + 1440) % 1440;
  return String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
}

function otRenderFatos(rota) {
  const box = document.getElementById('otFatos');
  if (!box) return;
  const ativos = rota.passageiros.filter(p => p.status === 'ativo' && (p.endereco || p.embarque));
  const chegada = TURNOS_CHEGADA[rota.turno] || '—';
  box.innerHTML =
    otFato('Chegada obrigatória', chegada) +
    otFato('Origem', GARAGEM_LABEL.replace(' (início da rota)', '')) +
    otFato('Destino', DESTINO.split('—')[0].trim()) +
    otFato('Passageiros', String(ativos.length)) +
    otFato('Pontos de embarque', '<span id="otQtdPontos">—</span>') +
    otFato('Tempo máximo em viagem', OPT_CFG.maxRideMin + ' min') +
    otFato('Margem de chegada', OPT_CFG.margemChegadaMin + ' min') +
    otFato('Objetivo', { tempo: 'Menor tempo', distancia: 'Menor distância',
                         equilibrado: 'Equilibrado' }[OPT_CFG.objetivo]);
}
function otFato(rot, val) {
  return '<div class="ot-fato"><span>' + rot + '</span><b>' + val + '</b></div>';
}

function otBlocoMetricas(titulo, m, ref) {
  const delta = (a, b, suf, inverso) => {
    if (ref === undefined) return '';
    const d = a - b;
    if (Math.abs(d) < 0.05) return '';
    const bom = inverso ? d > 0 : d < 0;
    return '<span class="ot-delta ' + (bom ? 'bom' : 'ruim') + '">' +
      (d > 0 ? '+' : '') + (Math.round(d * 10) / 10) + suf + '</span>';
  };
  return '<div class="ot-bloco">' +
    '<div class="ot-bloco-tit">' + titulo + '</div>' +
    '<div class="ot-linha"><span>Duração</span><b>' + m.durMin + ' min</b>' + (ref ? delta(m.durMin, ref.durMin, ' min') : '') + '</div>' +
    '<div class="ot-linha"><span>Distância</span><b>' + (Math.round(m.distKm * 10) / 10) + ' km</b>' + (ref ? delta(m.distKm, ref.distKm, ' km') : '') + '</div>' +
    '<div class="ot-linha"><span>Saída da garagem</span><b>' + otHHMM(m.saidaGaragem) + '</b></div>' +
    '<div class="ot-linha"><span>Maior tempo de passageiro</span><b>' + m.maiorRideMin + ' min</b></div>' +
    '<div class="ot-linha"><span>Acima de ' + OPT_CFG.maxRideMin + ' min</span><b class="' + (m.violacoes ? 'ot-mau' : 'ot-bom') + '">' +
      m.violacoes + '</b></div>' +
  '</div>';
}

function otSequencia(titulo, ordem, ctx, metrica) {
  let h = '<div class="ot-seq"><div class="ot-seq-tit">' + titulo + '</div><div class="ot-seq-item ot-seq-fixo">Garagem</div>';
  ordem.forEach((pi, k) => {
    const pt = ctx.pontos[pi];
    h += '<div class="ot-seq-item"><span class="ot-seq-h">' + otHHMM(metrica.embarqueMin[k]) + '</span>' +
         pt.nomes.join(' + ') +
         (metrica.rideMin[k] > OPT_CFG.maxRideMin ? '<span class="ot-seq-alerta">' + metrica.rideMin[k] + ' min</span>' : '') +
         '</div>';
  });
  h += '<div class="ot-seq-item ot-seq-fixo">Empresa · ' + otHHMM(ctx.chegadaMin) + '</div></div>';
  return h;
}

function openOtimizar(rotaId) {
  const key = getApiKey();
  if (!key) { alert('Configure sua Google Maps API Key primeiro.\nClique em Config no cabeçalho.'); return; }
  otimizarRotaId = rotaId;
  const rota = DATA.find(r => r.id === rotaId);
  const chegada = TURNOS_CHEGADA[rota.turno] || '';
  document.getElementById('otimizarTitle').textContent = 'Otimização inteligente — Linha ' + rota.linha + ' · ' + rota.turno + ' Turno';
  setOptStatus('Aguardando...', '');
  otLimparPassos();
  otRenderFatos(rota);
  const _btnA = document.getElementById('btnAnalisarRota'); if (_btnA) _btnA.disabled = false;
  const _btnM = document.getElementById('btnManterAtual'); if (_btnM) _btnM.textContent = 'Fechar';
  document.getElementById('optResultSection').style.display = 'none';
  document.getElementById('optMapSection').style.display = 'none';
  document.getElementById('btnAplicar').style.display = 'none';
  document.getElementById('btnVerMapa').style.display = 'none';
  document.getElementById('btnVerMapa').textContent = 'Ver Mapa';
  pendingOptimization = null;
  document.getElementById('modalOtimizar').classList.add('open');
}

// Mantido por compatibilidade: qualquer chamada antiga cai no fluxo novo.
async function otimizarRotaAtual() { return analisarMelhorRota(); }

async function analisarMelhorRota() {
  const btn = document.getElementById('btnAnalisarRota');
  if (btn) btn.disabled = true;
  otLimparPassos();
  setOptStatus('Preparando análise...', 'running');
  try {
    await ensureMapsLoaded();
    const rota = DATA.find(r => r.id === otimizarRotaId);
    const chegadaHora = TURNOS_CHEGADA[rota.turno] || '';
    if (!chegadaHora) {
      setOptStatus('Este turno não tem horário de chegada configurado. Ajuste em Configurações.', 'error');
      if (btn) btn.disabled = false; return;
    }

    const passAtivos = rota.passageiros
      .filter(p => p.status === 'ativo' && (p.endereco || p.embarque))
      .sort((a, b) => (a.horario || '99:99').localeCompare(b.horario || '99:99'));
    if (!passAtivos.length) { setOptStatus('Nenhum passageiro ativo com endereço.', 'error'); if (btn) btn.disabled = false; return; }

    // ---- coordenadas ----
    setOptStatus('Validando pontos...', 'running');
    const geocoder = new google.maps.Geocoder();
    const coordsMap = {};
    for (let i = 0; i < passAtivos.length; i++) {
      const p = passAtivos[i];
      setOptStatus('Coordenadas ' + (i + 1) + '/' + passAtivos.length + ': ' + p.nome.split(' ')[0] + '...', 'running');
      coordsMap[p.nome] = await getCoords(geocoder, p);
      await new Promise(r => setTimeout(r, 120));
    }
    const semCoords = passAtivos.filter(p => !coordsMap[p.nome]);
    if (semCoords.length) {
      otPasso('Sem coordenada: ' + semCoords.map(p => p.nome).join(', '), 'erro');
      setOptStatus('Otimização interrompida: ' + semCoords.length +
        ' passageiro(s) sem endereço localizável. Corrija o endereço e tente de novo.', 'error');
      if (btn) btn.disabled = false; return;
    }
    otPasso('Pontos validados');

    // ---- agrupamento ----
    const pontos = optAgruparPontos(passAtivos, coordsMap);
    const elQtd = document.getElementById('otQtdPontos');
    if (elQtd) elQtd.textContent = String(pontos.length);
    const juntos = pontos.filter(p => p.passageiros.length > 1).length;
    otPasso(pontos.length + ' pontos de embarque' + (juntos ? ' (' + juntos + ' com passageiros no mesmo local)' : ''));

    // ---- matriz ----
    setOptStatus('Calculando tempos entre os pontos...', 'running');
    const matriz = await optObterMatriz(pontos, msg => otPasso(msg));

    const [hh, mm] = chegadaHora.split(':').map(Number);
    // A margem faz o veículo chegar antes do horário obrigatório: o alvo real
    // do cálculo é a chegada menos a folga.
    const alvoMin = hh * 60 + mm - OPT_CFG.margemChegadaMin;
    const ctx = { dur: matriz.dur, dist: matriz.dist, pontos: pontos, chegadaMin: alvoMin };
    const ordemAtual = optOrdemAtual(pontos, passAtivos);
    if (OPT_CFG.margemChegadaMin > 0)
      otPasso('Alvo de chegada ' + otHHMM(alvoMin) + ' (' + OPT_CFG.margemChegadaMin +
              ' min de folga antes de ' + chegadaHora + ')');

    // ---- decisao ----
    setOptStatus('Comparando alternativas...', 'running');
    const dec = optDecidir(ctx, ordemAtual);
    otPasso('Restrições verificadas (limite de ' + OPT_CFG.maxRideMin + ' min em viagem)');
    otPasso('Ordem atual comparada na mesma base de tempos');
    otPasso(dec.exato
      ? 'Todas as sequências possíveis avaliadas (solução exata)'
      : 'Melhor alternativa encontrada por busca local');

    console.info('[otimizador]',
      '\nORDEM ATUAL   ', dec.atual.ordem.map(i => pontos[i].nomes.join('+')).join(' -> '),
      '\n              ', dec.atual.durMin + ' min / ' + (Math.round(dec.atual.distKm * 10) / 10) + ' km / viol=' + dec.atual.violacoes,
      '\nMELHOR ENCONTRADA', dec.candidata.ordem.map(i => pontos[i].nomes.join('+')).join(' -> '),
      '\n              ', dec.candidata.durMin + ' min / ' + (Math.round(dec.candidata.distKm * 10) / 10) + ' km / viol=' + dec.candidata.violacoes,
      '\nMELHORIA =', dec.melhorou);

    ultimoCtxOtimizacao = ctx;
    renderOptComparacao(dec, ctx, rota);

    if (dec.melhorou) {
      const partes = [];
      if (dec.ganhoMin > 0) partes.push(dec.ganhoMin + ' min mais rápida');
      if (dec.ganhoKm > 0.05) partes.push((Math.round(dec.ganhoKm * 10) / 10) + ' km menor');
      if (dec.atual.violacoes > dec.candidata.violacoes)
        partes.push((dec.atual.violacoes - dec.candidata.violacoes) + ' passageiro(s) a menos acima do limite');
      setOptStatus('Rota melhor encontrada. ' + partes.join(' · '), 'success');
      pendingOptimization = {
        rotaId: otimizarRotaId, ctx: ctx, metrica: dec.candidata,
        chegadaHora: chegadaHora, keepOrder: false, anterior: dec.atual
      };
      document.getElementById('btnAplicar').style.display = 'inline-block';
      document.getElementById('btnManterAtual').textContent = 'Manter rota atual';
    } else {
      const acima = dec.atual.ordem
        .map((pi, k) => ({ pt: pontos[pi], min: dec.atual.rideMin[k] }))
        .filter(x => x.min > OPT_CFG.maxRideMin);
      if (acima.length) {
        setOptStatus('Sua rota atual já é a melhor possível — mas nenhuma sequência resolve ' +
          acima.map(x => x.pt.nomes.join(' e ') + ' (' + x.min + ' min)').join(', ') +
          '. Considere dividir a linha ou usar outro veículo.', 'error');
      } else {
        setOptStatus('Sua rota atual já está otimizada.', 'success');
      }
      pendingOptimization = null;
      document.getElementById('btnAplicar').style.display = 'none';
      document.getElementById('btnManterAtual').textContent = 'Fechar';
    }
    document.getElementById('optResultSection').style.display = 'block';
    document.getElementById('btnVerMapa').style.display = 'none';
  } catch (e) {
    // Falha de API nunca altera a rota: so informa.
    otPasso(e.message, 'erro');
    setOptStatus('Não foi possível concluir a análise: ' + e.message + '. A rota atual não foi alterada.', 'error');
    pendingOptimization = null;
    console.error(e);
  }
  if (btn) btn.disabled = false;
}

let ultimoCtxOtimizacao = null;

function renderOptComparacao(dec, ctx, rota) {
  const body = document.getElementById('optResultBody');
  let h = '';
  if (!dec.melhorou) {
    h += '<div class="ot-aviso">Analisamos as alternativas respeitando o horário de chegada e as regras ' +
         'operacionais. Nenhuma sequência apresentou resultado melhor que a rota atual.' +
         (dec.mudancas
           ? ' A melhor alternativa encontrada apenas troca ' + dec.mudancas + ' ponto(s) de posição, ' +
             'sem ganho que justifique mexer na operação' +
             (dec.ganhoDistM < 0 ? ' (ficaria ' + Math.round(-dec.ganhoDistM) + ' m mais longa)' : '') + '.'
           : '') +
         '</div>';
    h += '<div class="ot-comp ot-comp-1">' + otBlocoMetricas('Rota atual', dec.atual) + '</div>';
    h += otSequencia('Sequência atual', dec.atual.ordem, ctx, dec.atual);
  } else {
    h += '<div class="ot-comp">' +
         otBlocoMetricas('Rota atual', dec.atual) +
         otBlocoMetricas('Rota proposta', dec.candidata, dec.atual) +
         '</div>';
    h += '<div class="ot-economia">Economia: <b>' + Math.max(0, dec.ganhoMin) + ' min</b> · <b>' +
         (Math.round(Math.max(0, dec.ganhoKm) * 10) / 10) + ' km</b>' +
         (dec.mudancas ? ' <span>· ' + dec.mudancas + ' ponto(s) mudam de posição</span>' : '') + '</div>';
    h += '<div class="ot-seqs">' +
         otSequencia('Antes', dec.atual.ordem, ctx, dec.atual) +
         otSequencia('Depois', dec.candidata.ordem, ctx, dec.candidata) +
         '</div>';
  }
  body.innerHTML = h;
}

async function recalcularApenasHorarios() {
  const btn = document.getElementById('btnRecalcHorarios');
  if (btn) btn.disabled = true;
  otLimparPassos();
  setOptStatus('Preparando...', 'running');
  try {
    await ensureMapsLoaded();
    const rota = DATA.find(r => r.id === otimizarRotaId);
    const chegadaHora = TURNOS_CHEGADA[rota.turno] || '';
    if (!chegadaHora) {
      setOptStatus('Este turno não tem horário de chegada configurado. Ajuste em Configurações.', 'error');
      if (btn) btn.disabled = false; return;
    }
    const passAtivos = rota.passageiros
      .filter(p => p.status === 'ativo' && (p.endereco || p.embarque))
      .sort((a, b) => (a.horario || '99:99').localeCompare(b.horario || '99:99'));
    if (!passAtivos.length) { setOptStatus('Nenhum passageiro ativo com endereço.', 'error'); if (btn) btn.disabled = false; return; }

    const geocoder = new google.maps.Geocoder();
    const coordsMap = {};
    for (let i = 0; i < passAtivos.length; i++) {
      const p = passAtivos[i];
      setOptStatus('Coordenadas ' + (i + 1) + '/' + passAtivos.length + '...', 'running');
      coordsMap[p.nome] = await getCoords(geocoder, p);
      await new Promise(r => setTimeout(r, 120));
    }
    const semCoords = passAtivos.filter(p => !coordsMap[p.nome]);
    if (semCoords.length) {
      otPasso('Sem coordenada: ' + semCoords.map(p => p.nome).join(', '), 'erro');
      setOptStatus('Interrompido: ' + semCoords.length + ' passageiro(s) sem endereço localizável.', 'error');
      if (btn) btn.disabled = false; return;
    }
    otPasso('Pontos validados');

    const pontos = optAgruparPontos(passAtivos, coordsMap);
    const elQtd = document.getElementById('otQtdPontos');
    if (elQtd) elQtd.textContent = String(pontos.length);
    setOptStatus('Calculando os tempos da ordem atual...', 'running');
    // Reaproveita a matriz se ela já existir nesta sessão; senão calcula.
    const matriz = await optObterMatriz(pontos, msg => otPasso(msg));
    const [hh, mm] = chegadaHora.split(':').map(Number);
    const alvoMin = hh * 60 + mm - OPT_CFG.margemChegadaMin;
    const ctx = { dur: matriz.dur, dist: matriz.dist, pontos: pontos, chegadaMin: alvoMin };
    const ordemAtual = optOrdemAtual(pontos, passAtivos);
    const metrica = optAvaliarOrdem(ordemAtual, ctx);
    otPasso('Horários recalculados mantendo a ordem atual');

    ultimoCtxOtimizacao = ctx;
    const body = document.getElementById('optResultBody');
    body.innerHTML = otBlocoMetricas('Rota atual (ordem mantida)', metrica) +
                     otSequencia('Sequência', ordemAtual, ctx, metrica);
    pendingOptimization = {
      rotaId: otimizarRotaId, ctx: ctx, metrica: metrica,
      chegadaHora: chegadaHora, keepOrder: true, anterior: metrica
    };
    setOptStatus('Horários recalculados. Revise e aplique.', 'success');
    document.getElementById('btnAplicar').style.display = 'inline-block';
    document.getElementById('btnAplicar').textContent = 'Aplicar horários';
    document.getElementById('optResultSection').style.display = 'block';
    document.getElementById('btnVerMapa').style.display = 'none';
  } catch (e) {
    otPasso(e.message, 'erro');
    setOptStatus('Não foi possível recalcular: ' + e.message + '. A rota atual não foi alterada.', 'error');
    pendingOptimization = null;
  }
  if (btn) btn.disabled = false;
}

function toggleOptMap() {
  const section = document.getElementById('optMapSection');
  const btn = document.getElementById('btnVerMapa');
  if (section.style.display === 'none') {
    section.style.display = 'block';
    btn.textContent = 'Ocultar Mapa';
    renderOptMap();
  } else {
    section.style.display = 'none';
    btn.textContent = 'Ver Mapa';
  }
}

function renderOptMap() {
  if (!lastDirectionsResult) return;
  const mapDiv = document.getElementById('optMapDiv');
  if (!mapDiv) return;
  if (!optMap) {
    optMap = new google.maps.Map(mapDiv, {
      zoom: 11,
      center: new google.maps.LatLng(GARAGEM_COORDS.lat, GARAGEM_COORDS.lng),
      mapTypeId: 'roadmap',
      styles: [
        { elementType: 'geometry', stylers: [{ color: '#1c2330' }] },
        { elementType: 'labels.text.fill', stylers: [{ color: '#8b949e' }] },
        { elementType: 'labels.text.stroke', stylers: [{ color: '#0d1117' }] },
        { featureType: 'road', elementType: 'geometry', stylers: [{ color: '#2d3748' }] },
        { featureType: 'road.highway', elementType: 'geometry', stylers: [{ color: '#3b4a6b' }] },
        { featureType: 'water', elementType: 'geometry', stylers: [{ color: '#0d1117' }] },
      ]
    });
    optDirectionsRenderer = new google.maps.DirectionsRenderer({
      map: optMap,
      polylineOptions: { strokeColor: '#f59e0b', strokeWeight: 4 },
      suppressMarkers: true
    });
  }
  optDirectionsRenderer.setDirections(lastDirectionsResult);
  const route = lastDirectionsResult.routes[0];
  const legs = route.legs;
  new google.maps.Marker({
    position: new google.maps.LatLng(GARAGEM_COORDS.lat, GARAGEM_COORDS.lng),
    map: optMap, title: 'Garagem Redentor',
    icon: { path: google.maps.SymbolPath.CIRCLE, scale: 10, fillColor: '#10b981', fillOpacity: 1, strokeColor: '#fff', strokeWeight: 2 }
  });
  if (pendingOptimization && pendingOptimization.novasParadas) {
    pendingOptimization.novasParadas.forEach((item, i) => {
      const coords = pendingOptimization.coordsMap && pendingOptimization.coordsMap[item.passageiro.nome];
      const pos = coords ? new google.maps.LatLng(coords.lat, coords.lng) : (legs[i] ? legs[i].end_location : null);
      if (!pos) return;
      const marker = new google.maps.Marker({
        position: pos, map: optMap,
        title: item.horario + ' — ' + item.passageiro.nome,
        label: { text: String(i+1), color: '#000', fontWeight: 'bold', fontSize: '12px' },
        icon: { path: google.maps.SymbolPath.CIRCLE, scale: 14, fillColor: item.alerta ? '#ef4444' : '#f59e0b', fillOpacity: 1, strokeColor: '#fff', strokeWeight: 2 }
      });
      const iw = new google.maps.InfoWindow({
        content: '<div style="color:#000;font-size:12px;min-width:160px"><strong>' + item.passageiro.nome.split(' ')[0] + '</strong><br>' + item.horario + '<br>' + item.minutosEmRota + 'min em rota' + (item.alerta ? '<br><span style="color:red">+60min</span>' : '') + '</div>'
      });
      marker.addListener('click', () => iw.open(optMap, marker));
    });
  }
  const lastLeg = legs[legs.length-1];
  new google.maps.Marker({
    position: lastLeg.end_location, map: optMap,
    icon: { path: google.maps.SymbolPath.CIRCLE, scale: 12, fillColor: '#3b82f6', fillOpacity: 1, strokeColor: '#fff', strokeWeight: 2 }
  });
}

// ---- PAINEL GERAL ----
function openPainel() {
  const body = document.getElementById('painelBody');

  const totalAtivos = DATA.reduce((s, r) => s + r.passageiros.filter(p => p.status === 'ativo').length, 0);
  const totalFerias = DATA.reduce((s, r) => s + r.passageiros.filter(p => p.status === 'ferias').length, 0);
  const totalAfastado = DATA.reduce((s, r) => s + r.passageiros.filter(p => p.status === 'afastado').length, 0);
  // Turnos dinâmicos: conta passageiros ativos por turno presente nos dados
  const ordemTurno = {'1°':1,'2°':2,'3°':3,'ADM':4};
  const turnosPresentes = [...new Set(DATA.filter(r => r.passageiros && r.passageiros.length).map(r => r.turno))]
    .sort((a,b) => (ordemTurno[a]||9) - (ordemTurno[b]||9));
  const contagemTurno = {};
  turnosPresentes.forEach(t => {
    contagemTurno[t] = DATA.reduce((s, r) => r.turno === t ? s + r.passageiros.filter(p=>p.status==='ativo').length : s, 0);
  });

  const linhasUnicas = [...new Set(DATA.map(r => r.linha))].sort((a,b)=>a-b);

  let html = '<div class="report-summary" style="margin-bottom:20px">' +
    '<div class="report-stat"><div class="report-stat-num" style="color:var(--green)">' + totalAtivos + '</div><div class="report-stat-label">Ativos</div></div>' +
    turnosPresentes.map(t => {
      const label = (t === 'ADM') ? 'ADM' : (t + '° Turno').replace('°°','°');
      const labelFinal = (t === 'ADM') ? 'ADM' : (t + ' Turno');
      return '<div class="report-stat"><div class="report-stat-num" style="color:var(--accent)">' + contagemTurno[t] + '</div><div class="report-stat-label">' + labelFinal + '</div></div>';
    }).join('') +
    '<div class="report-stat"><div class="report-stat-num" style="color:var(--accent2)">' + totalFerias + '</div><div class="report-stat-label">Férias</div></div>' +
    '<div class="report-stat"><div class="report-stat-num" style="color:var(--red)">' + totalAfastado + '</div><div class="report-stat-label">Afastados</div></div>' +
    '<div class="report-stat"><div class="report-stat-num" style="color:var(--muted)">' + DESLIGADOS.length + '</div><div class="report-stat-label">Desligados</div></div>' +
  '</div>';

  html += '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:14px">';

  linhasUnicas.forEach(linha => {
    const rotas = DATA.filter(r => r.linha === linha);
    const veiculo = rotas[0]?.veiculo || 'Van';
    const motorE = rotas[0]?.motorista || 'A definir';
    const mObj = MOTORISTAS.find(m => m.nome === motorE);

    html += '<div style="background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:14px 16px">';
    html += '<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px">';
    html += '<div class="line-badge ' + lc(linha) + '" style="width:34px;height:34px;font-size:15px;' +
      (corLinha(linha) && DATA.some(r => String(r.linha) === String(linha) && r.cor)
        ? 'background:' + corLinha(linha) + '22;color:' + corLinha(linha) : '') + '">' + linha + '</div>';
    html += '<div><div style="font-family:Barlow,sans-serif;font-weight:700;font-size:14px">Linha ' + linha + '</div>';
    html += '<div style="font-size:11px;color:var(--muted)">' + motorE + (mObj && mObj.tel ? ' · ' + mObj.tel : '') + '</div></div></div>';

    rotas.forEach(rota => {
      const cap = (rota.veiculo === 'Carro' ? 4 : 15);
      const ocupantes = rota.passageiros.filter(p => p.status === 'ativo' || p.status === 'ferias' || p.status === 'afastado').length;
      const ativos = rota.passageiros.filter(p => p.status === 'ativo').length;
      const vagas = cap - ocupantes;
      const pct = Math.round((ocupantes / cap) * 100);
      const barColor = pct >= 100 ? 'var(--red)' : pct >= 80 ? 'var(--accent)' : 'var(--green)';

      html += '<div style="margin-bottom:8px">';
      html += '<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:4px">';
      html += '<span style="color:var(--muted)">' + (rota.turno === 'ADM' ? 'ADM' : rota.turno + ' Turno') + '</span>';
      html += '<span style="font-weight:600">' + ocupantes + '/' + cap;
      html += (vagas > 0 ? ' <span style="color:var(--green);font-size:10px">(' + vagas + ' vagas)</span>' : ' <span style="color:var(--red);font-size:10px">LOTADO</span>') + '</span></div>';
      html += '<div style="background:var(--surface2);border-radius:4px;height:6px;overflow:hidden">';
      html += '<div style="width:' + Math.min(pct,100) + '%;height:100%;background:' + barColor + ';border-radius:4px;transition:width 0.3s"></div></div></div>';
    });

    html += '</div>';
  });

  html += '</div>';
  body.innerHTML = html;
  document.getElementById('modalPainel').classList.add('open');
}

// ---- FIREBASE + LOCALSTORAGE PERSISTENCE ----
const STORAGE_KEY = C.storageKey;
const FB_CONFIG = C.fb;

// Nome da instancia Firebase deste app.
// Precisa ser IGUAL ao nome usado pelo Portal de Acesso (portal-<transportadora>-<operacao>),
// senao a sessao criada no login do portal nao e reconhecida aqui e o sistema pede a senha de novo.
const FB_APP_NOME = C.appNome;

// ============================================================
// TRAVA DE IDENTIDADE (proteção multi-cliente)
// CLIENTE_ID = nome da coleção própria deste cliente no Firestore.
// PROJETO_ESPERADO = projectId do Firebase que ESTE arquivo deve usar.
// Se o arquivo for aberto apontando para o banco errado, a trava
// impede qualquer gravação e avisa, em vez de sobrescrever dados.
// ============================================================
const CLIENTE_ID = C.clienteId;
const PROJETO_ESPERADO = C.projetoEsperado;
let TRAVA_OK = true; // vira false se a identidade não bater

function verificarIdentidade() {
  const real = (FB_CONFIG && FB_CONFIG.projectId) || '';
  if (real !== PROJETO_ESPERADO) {
    TRAVA_OK = false;
    try {
      document.body.innerHTML = '<div style="max-width:560px;margin:80px auto;padding:32px;font-family:sans-serif;background:#1a1208;border:2px solid #f59e0b;border-radius:14px;color:#fff;text-align:center">' +
        '<div style="font-size:48px;margin-bottom:12px"></div>' +
        '<h2 style="color:#f59e0b">Arquivo no lugar errado</h2>' +
        '<p>Este arquivo é do cliente <b>' + CLIENTE_ID.toUpperCase() + '</b> (projeto <b>' + PROJETO_ESPERADO + '</b>), mas está conectado ao projeto <b>' + real + '</b>.</p>' +
        '<p style="color:#fca5a5">Por segurança, o sistema foi bloqueado para NÃO sobrescrever dados de outro cliente.</p>' +
        '<p style="font-size:13px;color:#9ca3af">Verifique se o arquivo correto está na pasta certa do servidor.</p>' +
        '</div>';
    } catch(e) {}
    return false;
  }
  return true;
}

let fbDb = null;
let fbSaveTimeout = null;
let fbDocRef = null;

// Initialize Firebase ONCE on page load
async function initFirebase() {
  if (fbDb) return true;
  if (!verificarIdentidade()) return false; // TRAVA: não conecta se o projeto não bate
  try {
    const { initializeApp, getApps, getApp } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-app.js');
    const { getFirestore, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    const app = getApps().find(a => a.name === FB_APP_NOME) || initializeApp(FB_CONFIG, FB_APP_NOME);
    // App Check e sessao, nesta ordem, antes de qualquer acesso ao Firestore.
    // Sem sessao o Firestore recusa tudo — e no PIN a recusa vira
    // "voce ja tem um PIN cadastrado", que e mentira.
    if (window.temviaComum) await window.temviaComum.prepararFirebase(app);
    fbDb = getFirestore(app);
    fbDocRef = doc(fbDb, CLIENTE_ID, 'dados');
    console.log('Firebase conectado');
    return true;
  } catch(e) {
    console.warn('Firebase não disponível:', e.message);
    return false;
  }
}

// ---- AUTENTICAÇÃO (Firebase Auth) ----
let fbAuth = null;

async function initAuth() {
  if (fbAuth) return fbAuth;
  const { initializeApp, getApps, getApp } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-app.js');
  const { getAuth } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-auth.js');
  const app = getApps().find(a => a.name === FB_APP_NOME) || initializeApp(FB_CONFIG, FB_APP_NOME);
  // App Check e sessao, nesta ordem, antes de qualquer acesso ao Firestore.
  // Sem sessao o Firestore recusa tudo — e no PIN a recusa vira
  // "voce ja tem um PIN cadastrado", que e mentira.
  if (window.temviaComum) await window.temviaComum.prepararFirebase(app);
  fbAuth = getAuth(app);
  return fbAuth;
}

function toggleSenha() {
  const inp = document.getElementById('loginPassword');
  const eye = document.getElementById('loginEye');
  if (inp.type === 'password') { inp.type = 'text'; eye.textContent = ''; eye.title = 'Ocultar senha'; }
  else { inp.type = 'password'; eye.textContent = ''; eye.title = 'Mostrar senha'; }
}

async function fazerLogin() {
  const email = document.getElementById('loginEmail').value.trim();
  const senha = document.getElementById('loginPassword').value;
  const erroEl = document.getElementById('loginErro');
  const btn = document.getElementById('loginBtn');
  erroEl.textContent = '';
  if (!email || !senha) { erroEl.textContent = 'Preencha e-mail e senha.'; return; }
  btn.disabled = true; btn.textContent = 'Entrando...';
  try {
    await initAuth();
    const { signInWithEmailAndPassword } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-auth.js');
    await signInWithEmailAndPassword(fbAuth, email, senha);
    // sucesso: onAuthStateChanged cuida de liberar o sistema
  } catch (e) {
    const map = {
      'auth/invalid-email': 'E-mail inválido.',
      'auth/user-not-found': 'Usuário não encontrado.',
      'auth/wrong-password': 'Senha incorreta.',
      'auth/invalid-credential': 'E-mail ou senha incorretos.',
      'auth/too-many-requests': 'Muitas tentativas. Tente novamente em alguns minutos.'
    };
    erroEl.textContent = map[e.code] || ('Erro ao entrar: ' + e.message);
  } finally {
    btn.disabled = false; btn.textContent = 'Entrar';
  }
}

async function esqueciSenha() {
  const email = document.getElementById('loginEmail').value.trim();
  const erroEl = document.getElementById('loginErro');
  if (!email) { erroEl.style.color = '#ef4444'; erroEl.textContent = 'Digite seu e-mail primeiro, depois clique em "Esqueci minha senha".'; return; }
  try {
    await initAuth();
    const { sendPasswordResetEmail } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-auth.js');
    await sendPasswordResetEmail(fbAuth, email);
    erroEl.style.color = '#10b981';
    erroEl.textContent = 'Enviamos um link de redefinição para o seu e-mail.';
  } catch (e) {
    erroEl.style.color = '#ef4444';
    erroEl.textContent = 'Não foi possível enviar: ' + (e.code || e.message);
  }
}

// Portal da transportadora: e para la que mandamos quem chega sem sessao.
// Portal da transportadora: e para la que mandamos quem chega sem sessao.
// Vem da CASCA. Sem portalUrl declarado (ambiente de teste), o app mostra o
// proprio formulario em vez de redirecionar — senao a casca de teste vira
// beco sem saida, devolvendo para o portal de producao.
const PORTAL_URL = (window.CLIENTE_CONFIG && window.CLIENTE_CONFIG.portalUrl) || '';
function irParaPortal(usarReplace) {
  if (!PORTAL_URL) return false;              // sem portal: quem chama mostra o form
  if (usarReplace) window.location.replace(PORTAL_URL);
  else window.location.href = PORTAL_URL;
  return true;
}
let _bloqueadoComoCliente = false;

// Evita o "pisca": o formulario so aparece quando confirmamos que nao ha sessao aberta.
let _formGestorMostrado = false;
function mostrarFormularioGestor() {
  if (_formGestorMostrado) return;
  _formGestorMostrado = true;
  const chk = document.getElementById('loginChecando');
  const box = document.getElementById('loginBox');
  if (chk) chk.style.display = 'none';
  if (box) box.style.display = '';
}
setTimeout(mostrarFormularioGestor, 3500);

async function logout() {
  try {
    await initAuth();
    const { signOut } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-auth.js');
    await signOut(fbAuth);
  } catch (e) {}
  // Porta da frente do sistema agora e o portal temvia.
  if (!irParaPortal(false)) mostrarFormularioGestor();
}

// Perfis: {CLIENTE_ID}/acessos guarda quem e da EMPRESA CLIENTE.
// E-mail nao listado = gestor (transicao: contas antigas continuam entrando).
async function ehAcessoDeCliente(email) {
  try {
    const { getFirestore, doc, getDoc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    await initAuth();
    const snap = await getDoc(doc(getFirestore(fbAuth.app), CLIENTE_ID, 'acessos'));
    const lista = snap.exists() ? (snap.data().lista || []) : [];
    const alvo = (email || '').trim().toLowerCase();
    const u = lista.find(x => (x.email || '').trim().toLowerCase() === alvo);
    return !!(u && u.papel === 'cliente');
  } catch (e) { return false; }
}

// Inicia o sistema só depois de confirmar login
async function iniciarComAutenticacao() {
  await initAuth();
  const { onAuthStateChanged } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-auth.js');
  let jaIniciou = false;
  onAuthStateChanged(fbAuth, async (user) => {
    const overlay = document.getElementById('loginOverlay');
    // Sessao anonima NAO e login. Ela existe so para o Firestore aceitar a
    // requisicao; o token dela nao passa em nenhuma regra que exija gestor.
    // Tratar o anonimo como logado abria o sistema inteiro com um token que
    // nao escreve nada — e sem nada na tela dizendo isso.
    if (user && user.isAnonymous) user = null;
    if (user) {
      // Conta criada para a empresa cliente NAO abre o painel do gestor.
      if (await ehAcessoDeCliente(user.email)) {
        const { signOut } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-auth.js');
        await signOut(fbAuth);
        _bloqueadoComoCliente = true;   // nao redirecionar: a pessoa precisa LER o motivo
        const erroEl = document.getElementById('loginErro');
        if (erroEl) { erroEl.style.color = '#ef4444'; erroEl.textContent = 'Este login e do portal da empresa cliente, nao do gestor.'; }
        if (overlay) overlay.style.display = 'flex';
        mostrarFormularioGestor();
        return;
      }
      // Logado: esconde login e carrega o sistema (uma única vez)
      if (overlay) overlay.style.display = 'none';
      if (!jaIniciou) {
        jaIniciou = true;
        // getApiKey conhece a ordem: casca -> reserva -> nada. Ler o cache
        // direto aqui apagava a chave vinda da casca em navegador limpo.
        getApiKey();
        loadData().then(() => {
          renderSidebar();
          solCarregarFirebase();
          cadGestorCarregar();
          carregarPinsAtivos().then(() => { try { renderMotoristaList(); } catch(e) {} });
          carregarAcessos();
        });
      }
    } else if (_bloqueadoComoCliente) {
      // Conta de cliente barrada acima: fica na tela com a explicacao.
      if (overlay) overlay.style.display = 'flex';
      mostrarFormularioGestor();
    } else {
      // Sem sessao: a porta de entrada do sistema e o PORTAL, nao o login deste app.
      // replace() em vez de href para o botao "voltar" nao ficar pingando entre os dois.
      if (!irParaPortal(true)) mostrarFormularioGestor();
    }
  });
}

function getSnapshot() {
  return {
    DATA, DESLIGADOS, MOTORISTAS, nextMotoId, pdfRevision,
    changeLog, ROTAS_EXTRAS, SEM_ROTA,
    dataVersion: DATA_VERSION,
    savedAt: new Date().toISOString()
  };
}

function applySnapshot(snap) {
  if (!snap?.DATA?.length) return false;
  DATA.length = 0; snap.DATA.forEach(r => DATA.push(r));
  if (snap.DESLIGADOS) { DESLIGADOS.length = 0; snap.DESLIGADOS.forEach(d => DESLIGADOS.push(d)); }
  if (snap.MOTORISTAS) { MOTORISTAS.length = 0; snap.MOTORISTAS.forEach(m => MOTORISTAS.push(m)); }
  if (snap.nextMotoId) nextMotoId = snap.nextMotoId;
  if (snap.pdfRevision) Object.assign(pdfRevision, snap.pdfRevision);
  if (snap.changeLog) { changeLog.length = 0; snap.changeLog.forEach(c => changeLog.push(c)); }
  if (snap.ROTAS_EXTRAS) { ROTAS_EXTRAS.length = 0; snap.ROTAS_EXTRAS.forEach(r => ROTAS_EXTRAS.push(r)); }
  if (snap.SEM_ROTA) { SEM_ROTA.length = 0; snap.SEM_ROTA.forEach(r => SEM_ROTA.push(r)); }
  return true;
}

function saveToLocal(snap) {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(snap)); } catch(e) {}
}

// Remove valores `undefined` em qualquer nível — o Firestore rejeita undefined.
// undefined em objeto -> chave removida; undefined em array -> vira null.
function sanitizeForFirestore(value) {
  if (value === undefined) return null;
  if (value === null) return value;
  if (Array.isArray(value)) {
    return value.map(v => (v === undefined ? null : sanitizeForFirestore(v)));
  }
  if (typeof value === 'object') {
    const out = {};
    for (const k in value) {
      if (!Object.prototype.hasOwnProperty.call(value, k)) continue;
      const v = value[k];
      if (v === undefined) continue; // descarta a chave undefined
      out[k] = sanitizeForFirestore(v);
    }
    return out;
  }
  return value;
}

async function saveToFirebase(snap) {
  try {
    if (!fbDb) await initFirebase();
    if (!fbDb || !fbDocRef) { console.error('Firebase não disponível'); return; }
    const { setDoc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
    await setDoc(fbDocRef, sanitizeForFirestore(snap));
    console.log('Salvo no Firebase:', snap.savedAt);
    // Visual feedback
    let toast = document.getElementById('fbToast');
    if (!toast) {
      toast = document.createElement('div');
      toast.id = 'fbToast';
      toast.style.cssText = 'position:fixed;bottom:16px;right:16px;padding:8px 14px;border-radius:8px;font-size:12px;font-weight:700;z-index:9999;transition:opacity 0.5s;pointer-events:none';
      document.body.appendChild(toast);
    }
    toast.style.opacity = '1';
    toast.style.background = '#10b981';
    toast.style.color = '#000';
    toast.textContent = 'Sincronizado';
    clearTimeout(toast._t);
    toast._t = setTimeout(() => { toast.style.opacity = '0'; }, 2000);
  } catch(e) {
    console.error('Erro Firebase:', e.message, e.code);
    let toast = document.getElementById('fbToast');
    if (!toast) { toast = document.createElement('div'); toast.id = 'fbToast'; toast.style.cssText = 'position:fixed;bottom:16px;right:16px;padding:8px 14px;border-radius:8px;font-size:12px;font-weight:700;z-index:9999;pointer-events:none'; document.body.appendChild(toast); }
    toast.style.opacity = '1'; toast.style.background = '#ef4444'; toast.style.color = '#fff';
    toast.textContent = 'Erro: ' + e.message;
    clearTimeout(toast._t);
    toast._t = setTimeout(() => { toast.style.opacity = '0'; }, 5000);
  }
}

function saveData() {
  const snap = getSnapshot();
  saveToLocal(snap); // immediate
  if (fbSaveTimeout) clearTimeout(fbSaveTimeout);
  fbSaveTimeout = setTimeout(() => saveToFirebase(snap), 500);
}

function saveAfterChange() {
  saveData();
  updateStats();
}

async function loadData() {
  const BASE_VERSION = DATA_VERSION;

  // Read localStorage cache
  let localSnap = null;
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) localSnap = JSON.parse(raw);
  } catch(e) {}

  // Initialize Firebase
  const fbOk = await initFirebase();

  if (fbOk && fbDocRef) {
    try {
      const { getDoc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
      const snap = await getDoc(fbDocRef);

      // Carrega a configuração da empresa (doc 'config') sobre os padrões.
      // Seguro: se não existir ou falhar, mantém os valores padrão da Redentor.
      try {
        const { doc: _doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
        const cfgSnap = await getDoc(_doc(fbDb, CLIENTE_ID, 'config'));
        if (cfgSnap.exists()) aplicarEmpresaConfig(cfgSnap.data());
      } catch(cfgErr) { console.warn('config empresa:', cfgErr); }

      if (snap.exists()) {
        const saved = snap.data();
        // === REGRA DE OURO (reforçada): o Firebase é SEMPRE a fonte da verdade. ===
        // O cache local NUNCA sobrescreve o Firebase. Isso impede que o cache de
        // uma instância (ex.: outro cliente aberto no mesmo navegador) contamine
        // o banco. O cache local serve apenas como leitura/fallback offline.
        if (saved.DATA && saved.DATA.length > 0) {
          // Firebase manda, sempre.
          applySnapshot(saved);
          saveToLocal(saved);
          console.log('Firebase aplicado (fonte da verdade):', saved.savedAt);
        } else {
          // Firebase existe mas está vazio — envia os dados do arquivo como base inicial
          console.log('Firebase vazio — enviando dados iniciais do arquivo...');
          const newSnap = getSnapshot();
          await saveToFirebase(newSnap);
          saveToLocal(newSnap);
        }
      } else {
        // No data in Firebase yet
        const newSnap = getSnapshot();
        newSnap.dataVersion = BASE_VERSION;
        await saveToFirebase(newSnap);
        saveToLocal(newSnap);
        console.log('Dados iniciais enviados ao Firebase');
      }
      return DATA.length > 0;
    } catch(e) {
      console.warn('Firebase load error:', e.message);
    }
  }

  // Fallback to localStorage
  if (localSnap?.DATA?.length > 0) {
    applySnapshot(localSnap);
    console.log('Fallback localStorage:', localSnap.savedAt);
    return true;
  }
  return false;
}





// ---- EXCLUIR PASSAGEIRO ----
function excluirPassageiro(rotaId, idx) {
  // Pool "Sem Rota": exclui de SEM_ROTA
  if (rotaId === '__semrota__') {
    const p = SEM_ROTA[idx];
    if (!p) return;
    if (!confirm(`Excluir permanentemente "${p.nome}"?\n\nEsta ação não pode ser desfeita.`)) return;
    logChange('exclusao', p.nome, 'Sem Rota (pool)', 'Excluído', '');
    SEM_ROTA.splice(idx, 1);
    saveAfterChange();
    renderSidebar();
    if (typeof renderSemRotaList === 'function') renderSemRotaList();
    return;
  }
  // Lista de desligados
  if (rotaId === '__desligados__') {
    const p = DESLIGADOS[idx];
    if (!p) return;
    if (!confirm(`Excluir permanentemente "${p.nome}"?\n\nEsta ação não pode ser desfeita.`)) return;
    logChange('exclusao', p.nome, 'Desligados', 'Excluído', '');
    DESLIGADOS.splice(idx, 1);
    saveAfterChange();
    renderSidebar();
    return;
  }
  const rota = DATA.find(r => r.id === rotaId);
  if (!rota) return;
  const p = rota.passageiros[idx];
  if (!confirm(`Excluir permanentemente "${p.nome}"?\n\nEsta ação não pode ser desfeita.`)) return;
  logChange('exclusao', p.nome, 'Linha ' + rota.linha + ' ' + rota.turno, 'Excluído', '');
  rota.passageiros.splice(idx, 1);
  saveAfterChange();
  renderSidebar();
  selectLine(rotaId);
}

// Exclui o passageiro que está aberto no modal de edição e fecha o modal.
function excluirPassageiroAtual() {
  if (editingPassIdx === null || editingPassIdx === undefined) return;
  const rotaId = activeId;
  const idx = editingPassIdx;
  let antes;
  if (rotaId === '__semrota__') antes = SEM_ROTA.length;
  else if (rotaId === '__desligados__') antes = DESLIGADOS.length;
  else { const r = DATA.find(x => x.id === rotaId); antes = r ? r.passageiros.length : -1; }
  excluirPassageiro(rotaId, idx);
  let depois;
  if (rotaId === '__semrota__') depois = SEM_ROTA.length;
  else if (rotaId === '__desligados__') depois = DESLIGADOS.length;
  else { const r = DATA.find(x => x.id === rotaId); depois = r ? r.passageiros.length : -1; }
  if (depois < antes) closeModal();
}

// ---- MAPA GERAL ----
const MG_COLORS = {
  1: '#f59e0b', // amber
  2: '#3b82f6', // blue
  3: '#10b981', // green
  4: '#ef4444', // red
  5: '#8b5cf6', // purple
  6: '#f97316', // orange
  7: '#06b6d4', // cyan
};

let mgTurno = '1°';
// Item 14: o mapa abre sem nenhuma linha marcada. O gestor escolhe o que ver
// (ou clica em "Todas"), em vez de receber sete rotas sobrepostas de cara.
let mgLinhasSel = new Set();
let mgMap = null;
let mgMarkers = [];
let mgPolylines = [];
let mgDirectionsRenderers = [];
let mgInfoWindow = null;

function openMapaGeral(rotaExtraIdx) {
  const key = getApiKey();
  if (!key) { alert('Configure a API Key do Google Maps primeiro (Config)'); return; }
  // Abre limpo: sem linhas marcadas e com o aviso por cima do mapa.
  if (rotaExtraIdx === undefined) mgLinhasSel.clear();
  document.getElementById('modalMapaGeral').classList.add('open');
  renderMapaTurnoBar();
  buildLinhasCheck();
  ensureMapsLoaded().then(() => {
    initMapaGeral();
    renderMapaGeral(rotaExtraIdx);
  }).catch(e => alert('Erro ao carregar Maps: ' + e.message));
}

function initMapaGeral() {
  if (mgMap) return;
  mgInfoWindow = new google.maps.InfoWindow();
  mgMap = new google.maps.Map(document.getElementById('mapaGeralDiv'), {
    zoom: 11,
    center: new google.maps.LatLng(-23.5, -47.46),
    mapTypeId: 'roadmap',
    styles: [
      { elementType: 'geometry', stylers: [{ color: '#1c2330' }] },
      { elementType: 'labels.text.fill', stylers: [{ color: '#8b949e' }] },
      { elementType: 'labels.text.stroke', stylers: [{ color: '#0d1117' }] },
      { featureType: 'road', elementType: 'geometry', stylers: [{ color: '#2d3748' }] },
      { featureType: 'road.highway', elementType: 'geometry', stylers: [{ color: '#3b4a6b' }] },
      { featureType: 'water', elementType: 'geometry', stylers: [{ color: '#0d1117' }] },
      { featureType: 'landscape', elementType: 'geometry', stylers: [{ color: '#161b22' }] },
      { featureType: 'poi', visibility: 'off' },
      { featureType: 'transit', visibility: 'off' },
    ],
    fullscreenControl: true,
    mapTypeControl: false,
    streetViewControl: false,
  });
}

function buildLinhasCheck() {
  const container = document.getElementById('mgLinhasCheck');
  const linhas = [...new Set(DATA.map(r => r.linha))].sort((a,b) => a-b);
  container.innerHTML = '';
  linhas.forEach(l => {
    const color = corLinha(l);
    const btn = document.createElement('button');
    btn.id = 'mgL' + l;
    btn.style.cssText = `background:${mgLinhasSel.has(l) ? color : 'transparent'};color:${mgLinhasSel.has(l) ? '#000' : color};border:2px solid ${color};border-radius:6px;padding:3px 10px;font-size:12px;font-weight:700;cursor:pointer;transition:all 0.15s`;
    btn.textContent = 'L' + l;
    btn.onclick = () => toggleLinha(l, btn, color);
    container.appendChild(btn);
  });
}

function toggleLinha(l, btn, color) {
  if (mgLinhasSel.has(l)) {
    mgLinhasSel.delete(l);
    btn.style.background = 'transparent';
    btn.style.color = color;
  } else {
    mgLinhasSel.add(l);
    btn.style.background = color;
    btn.style.color = '#000';
  }
  renderMapaGeral();
}

function mgSelectAll() {
  DATA.forEach(r => mgLinhasSel.add(r.linha));
  buildLinhasCheck();
  renderMapaGeral();
}

function mgSelectNone() {
  mgLinhasSel.clear();
  buildLinhasCheck();
  renderMapaGeral();
}

function renderMapaTurnoBar() {
  const bar = document.getElementById('mgTurnoBar');
  if (!bar) return;
  const ordem = {'1°':1,'2°':2,'3°':3,'ADM':4};
  const presentes = [...new Set(DATA.filter(r => r.passageiros && r.passageiros.length).map(r => r.turno))]
    .sort((a,b) => (ordem[a]||9) - (ordem[b]||9));
  // Se o turno atual não existe nos dados, seleciona o primeiro presente
  if (!presentes.includes(mgTurno)) mgTurno = presentes[0] || '1°';
  let html = '<span style="font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:0.5px">Turno:</span>';
  presentes.forEach(t => {
    const label = (t === 'ADM') ? 'ADM' : (t + ' Turno');
    html += '<button class="turno-btn' + (mgTurno===t?' active':'') + '" onclick="setMapaTurno(\'' + t + '\', this)">' + label + '</button>';
  });
  bar.innerHTML = html;
}

function setMapaTurno(t, btn) {
  mgTurno = t;
  document.querySelectorAll('[id^="mgTurno"]').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  renderMapaGeral();
}

function clearMapaGeral() {
  mgMarkers.forEach(m => m.setMap(null)); mgMarkers = [];
  mgPolylines.forEach(p => p.setMap(null)); mgPolylines = [];
  mgDirectionsRenderers.forEach(r => r.setMap(null)); mgDirectionsRenderers = [];
}

async function renderMapaGeral(rotaExtraIdx) {
  if (!mgMap) return;
  clearMapaGeral();

  const showRoutes = document.getElementById('mgShowRoutes').checked;
  const rotas = DATA.filter(r => r.turno === mgTurno && mgLinhasSel.has(r.linha));
  // aviso "selecione a rota" some assim que houver algo marcado
  const _vazio = document.getElementById('mgVazio');
  if (_vazio) _vazio.style.display = mgLinhasSel.size ? 'none' : 'flex';
  const legend = document.getElementById('mgLegend');
  legend.innerHTML = '';
  const bounds = new google.maps.LatLngBounds();
  let hasPoints = false;

  // Garagem marker
  const garPos = new google.maps.LatLng(GARAGEM_COORDS.lat, GARAGEM_COORDS.lng);
  const garMarker = new google.maps.Marker({
    position: garPos, map: mgMap,
    title: 'Garagem Redentor',
    icon: { path: google.maps.SymbolPath.CIRCLE, scale: 10, fillColor: '#10b981', fillOpacity: 1, strokeColor: '#fff', strokeWeight: 2 },
    zIndex: 100
  });
  garMarker.addListener('click', () => {
    mgInfoWindow.setContent('<div style="color:#000;font-size:13px;font-weight:700">Garagem Redentor</div><div style="font-size:11px">R. Sebastiana Rosa Luposeli, 59</div>');
    mgInfoWindow.open(mgMap, garMarker);
  });
  mgMarkers.push(garMarker);
  bounds.extend(garPos);

  // Empresa marker
  const empPos = new google.maps.LatLng(EMPRESA_COORDS.lat, EMPRESA_COORDS.lng);
  const empMarker = new google.maps.Marker({
    position: empPos, map: mgMap,
    title: 'Empresa',
    icon: { path: google.maps.SymbolPath.CIRCLE, scale: 10, fillColor: '#3b82f6', fillOpacity: 1, strokeColor: '#fff', strokeWeight: 2 },
    zIndex: 100
  });
  empMarker.addListener('click', () => {
    mgInfoWindow.setContent('<div style="color:#000;font-size:13px;font-weight:700">Huawei — Empresa</div><div style="font-size:11px">Av. Jerome Case, 2600 — Éden</div>');
    mgInfoWindow.open(mgMap, empMarker);
  });
  mgMarkers.push(empMarker);
  bounds.extend(empPos);

  // Marker da Vertiv se houver rotas VERTIV no filtro atual
  const hasVertiv = rotas.some(r => String(r.linha).startsWith('VERTIV'));
  if (hasVertiv) {
    const vertivPos = new google.maps.LatLng(-23.386451104226673, -47.38984559023686);
    const vertivMarker = new google.maps.Marker({
      position: vertivPos, map: mgMap,
      title: 'Vertiv',
      icon: { path: google.maps.SymbolPath.CIRCLE, scale: 10, fillColor: '#dc2626', fillOpacity: 1, strokeColor: '#fff', strokeWeight: 2 },
      zIndex: 100
    });
    vertivMarker.addListener('click', () => {
      mgInfoWindow.setContent('<div style="color:#000;font-size:13px;font-weight:700">Vertiv</div><div style="font-size:11px">Estr. dos Carvalhos, 1441 — Cajuru do Sul</div>');
      mgInfoWindow.open(mgMap, vertivMarker);
    });
    mgMarkers.push(vertivMarker);
    bounds.extend(vertivPos);
  }

  const chegada = TURNOS_CHEGADA[mgTurno] || '';

  // Show sem-rota passengers as gray markers
  DATA.forEach(rota => {
    rota.passageiros.filter(p => p.status === 'sem-rota' && p.lat && p.lng).forEach(p => {
      const pos = new google.maps.LatLng(p.lat, p.lng);
      bounds.extend(pos);
      hasPoints = true;
      const marker = new google.maps.Marker({
        position: pos, map: mgMap,
        title: p.nome + ' (Sem Rota)',
        icon: { path: google.maps.SymbolPath.CIRCLE, scale: 10, fillColor: '#9ca3af', fillOpacity: 0.8, strokeColor: '#fff', strokeWeight: 2 },
        zIndex: 30
      });
      marker.addListener('click', () => {
        mgInfoWindow.setContent(`<div style="color:#000;min-width:180px">
          <div style="font-weight:700;font-size:13px;border-bottom:2px solid #9ca3af;padding-bottom:4px;margin-bottom:6px">Sem Rota</div>
          <div style="font-weight:600">${p.nome}</div>
          <div style="font-size:11px;color:#555">${p.embarque||p.endereco||'—'}</div>
          <div style="font-size:11px;color:#555">${p.bairro||''} · ${p.cidade||''}</div>
          ${p.telefone ? `<div style="font-size:11px;color:#555">${p.telefone}</div>` : ''}
        </div>`);
        mgInfoWindow.open(mgMap, marker);
      });
      mgMarkers.push(marker);
    });
  });

  // ROTAS EXTRAS: sempre visíveis independente das linhas selecionadas 
  const reColor = '#ec4899';
  // Mostrar todas as rotas extras ativas (ou destacar a selecionada)
  ROTAS_EXTRAS.forEach((re, reIdx) => {
    const isDestacada = rotaExtraIdx !== undefined && rotaExtraIdx === reIdx;
    const cor = isDestacada ? reColor : '#ec4899';
    const escala = isDestacada ? 13 : 10;

    legend.innerHTML += `<div style="display:flex;align-items:center;gap:6px">
      <div style="width:14px;height:14px;border-radius:50%;background:${cor};flex-shrink:0;${isDestacada ? 'border:2px solid #fff' : 'opacity:0.7'}"></div>
      <span style="color:var(--text)">${re.nome}</span>
      <span style="color:var(--muted)">${re.passageiros.length} pass.</span>
    </div>`;

    re.passageiros.filter(p => p.lat && p.lng).forEach((p, i) => {
      const pos = new google.maps.LatLng(p.lat, p.lng);
      bounds.extend(pos);
      hasPoints = true;
      const marker = new google.maps.Marker({
        position: pos, map: mgMap,
        label: { text: String(i + 1), color: '#000', fontSize: '10px', fontWeight: '700' },
        icon: { path: google.maps.SymbolPath.CIRCLE, scale: escala, fillColor: cor, fillOpacity: 1, strokeColor: '#fff', strokeWeight: 2 },
        zIndex: isDestacada ? 90 : 70
      });
      marker.addListener('click', () => {
        mgInfoWindow.setContent(`<div style="color:#000;min-width:180px">
          <div style="font-weight:700;font-size:13px;border-bottom:2px solid ${cor};padding-bottom:4px;margin-bottom:6px">${re.nome}</div>
          <div style="font-weight:600">${p.nome}</div>
          <div style="font-size:11px;color:#555">${p.embarque || p.endereco || '—'}</div>
          <div style="font-size:11px;color:#555">${p.bairro || ''} · ${p.cidade || ''}</div>
          ${p.telefone ? `<div style="font-size:11px;color:#555">${p.telefone}</div>` : ''}
          <div style="font-size:10px;color:#888;margin-top:4px">Parada ${i + 1} de ${re.passageiros.filter(x => x.lat && x.lng).length}</div>
        </div>`);
        mgInfoWindow.open(mgMap, marker);
      });
      mgMarkers.push(marker);
    });

    // Traçar rota: Garagem → Passageiros → Empresa/Vertiv (se showRoutes ativo)
    if (showRoutes && re.passageiros.filter(p => p.lat && p.lng).length > 0) {
      const stops = re.passageiros.filter(p => p.lat && p.lng);
      const waypoints = stops.slice(0, -1).map(p => ({
        location: new google.maps.LatLng(p.lat, p.lng),
        stopover: true
      }));
      const isVertivRota = String(re.linha).startsWith('VERTIV');
      const destCoords = isVertivRota
        ? { lat: -23.386451104226673, lng: -47.38984559023686 }
        : EMPRESA_COORDS;
      const directionsService = new google.maps.DirectionsService();
      const directionsRenderer = new google.maps.DirectionsRenderer({
        map: mgMap,
        suppressMarkers: true,
        polylineOptions: { strokeColor: cor, strokeOpacity: 0.7, strokeWeight: isDestacada ? 4 : 2.5 }
      });
      mgPolylines.push(directionsRenderer);
      directionsService.route({
        origin: new google.maps.LatLng(GARAGEM_COORDS.lat, GARAGEM_COORDS.lng),
        destination: new google.maps.LatLng(destCoords.lat, destCoords.lng),
        waypoints: waypoints,
        optimizeWaypoints: false,
        travelMode: google.maps.TravelMode.DRIVING
      }, (result, status) => {
        if (status === 'OK') directionsRenderer.setDirections(result);
      });
    }
  });

  for (let ri = 0; ri < rotas.length; ri++) {
    const rota = rotas[ri];
    const color = corLinha(rota);
    const passAtivos = rota.passageiros
      .filter(p => p.status === 'ativo' && p.lat && p.lng)
      .sort((a,b) => (a.horario||'99:99').localeCompare(b.horario||'99:99'));

    if (passAtivos.length === 0) continue;
    hasPoints = true;

    // Legend item
    legend.innerHTML += `<div style="display:flex;align-items:center;gap:6px">
      <div style="width:14px;height:14px;border-radius:50%;background:${color};flex-shrink:0"></div>
      <span style="color:var(--text)">Linha ${rota.linha}</span>
      <span style="color:var(--muted)">${passAtivos.length} pass.</span>
    </div>`;

    // Group passengers by coordinate (same point = multiple passengers)
    const coordGroups = new Map();
    passAtivos.forEach((p, i) => {
      const key = p.lat.toFixed(5) + ',' + p.lng.toFixed(5);
      if (!coordGroups.has(key)) coordGroups.set(key, []);
      coordGroups.get(key).push({...p, ordem: i+1});
    });

    // One marker per unique coordinate
    coordGroups.forEach((passengers, key) => {
      const [lat, lng] = key.split(',').map(Number);
      const pos = new google.maps.LatLng(lat, lng);
      bounds.extend(pos);
      const isMulti = passengers.length > 1;
      let label;
      if (isMulti) {
        label = String(passengers.length);
      } else {
        const ord = passengers[0].ordem;
        label = (typeof ord === 'number' || typeof ord === 'string') ? String(ord) : '';
      }
      const marker = new google.maps.Marker({
        position: pos, map: mgMap,
        title: passengers.map(p => p.nome).join(', '),
        label: { text: label, color: '#000', fontSize: '10px', fontWeight: '700' },
        icon: {
          path: google.maps.SymbolPath.CIRCLE,
          scale: isMulti ? 14 : 11,
          fillColor: color,
          fillOpacity: 0.9,
          strokeColor: isMulti ? '#fff' : '#fff',
          strokeWeight: isMulti ? 2.5 : 1.5
        },
        zIndex: isMulti ? 60 : 50
      });
      marker.addListener('click', () => {
        let html = `<div style="color:#000;min-width:200px">
          <div style="font-weight:700;font-size:13px;border-bottom:2px solid ${color};padding-bottom:4px;margin-bottom:8px">
            Linha ${rota.linha} · ${rota.turno} Turno
            ${isMulti ? `<span style="background:${color};color:#000;border-radius:4px;padding:1px 6px;font-size:10px;margin-left:6px">${passengers.length} passageiros</span>` : ''}
          </div>
          <div style="font-size:11px;color:#555;margin-bottom:8px">${passengers[0].embarque||passengers[0].endereco||'—'}</div>`;
        passengers.forEach(p => {
          html += `<div style="border-top:1px solid #eee;padding-top:6px;margin-top:6px">
            <div style="font-weight:600;font-size:13px">${p.nome}</div>
            <div style="font-size:11px;color:#555">${p.horario||'--:--'}${p.telefone ? ' · ' + p.telefone : ''}</div>
            <div style="font-size:11px;color:#888">${p.bairro||''} · ${p.cidade||''}</div>
          </div>`;
        });
        html += '</div>';
        mgInfoWindow.setContent(html);
        mgInfoWindow.open(mgMap, marker);
      });
      mgMarkers.push(marker);
    });

    // Draw route if enabled - with delay to avoid OVER_QUERY_LIMIT
    if (showRoutes && passAtivos.length > 0) {
      await new Promise(resolve => setTimeout(resolve, ri * 300)); // 300ms delay per route
      const directionsService = new google.maps.DirectionsService();
      const isVertivRota2 = String(rota.linha).startsWith('VERTIV');
      const destCoords2 = isVertivRota2
        ? { lat: -23.386451104226673, lng: -47.38984559023686 }
        : EMPRESA_COORDS;

      await new Promise(resolve => {
        directionsService.route({
          origin: new google.maps.LatLng(GARAGEM_COORDS.lat, GARAGEM_COORDS.lng),
          destination: new google.maps.LatLng(destCoords2.lat, destCoords2.lng),
          waypoints: (() => {
            const seen = new Set();
            return passAtivos.filter(p => {
              const k = p.lat.toFixed(5)+','+p.lng.toFixed(5);
              return seen.has(k) ? false : (seen.add(k), true);
            }).map(p => ({ location: new google.maps.LatLng(p.lat, p.lng), stopover: false }));
          })(),
          travelMode: google.maps.TravelMode.DRIVING,
          optimizeWaypoints: false,
        }, (result, status) => {
          if (status === 'OK') {
            console.log('Directions OK L' + rota.linha + ' ' + rota.turno + ' (' + passAtivos.length + ' waypoints)');
            const renderer = new google.maps.DirectionsRenderer({
              map: mgMap,
              directions: result,
              suppressMarkers: true,
              polylineOptions: {
                strokeColor: color,
                strokeWeight: 3,
                strokeOpacity: 0.75
              }
            });
            mgDirectionsRenderers.push(renderer);
          } else {
            console.warn('Directions fallback L' + rota.linha + ' ' + rota.turno + ':', status, '| waypoints:', passAtivos.length);
            // Fallback: straight polyline
            const path = [
              new google.maps.LatLng(GARAGEM_COORDS.lat, GARAGEM_COORDS.lng),
              ...passAtivos.map(p => new google.maps.LatLng(p.lat, p.lng)),
              new google.maps.LatLng(EMPRESA_COORDS.lat, EMPRESA_COORDS.lng)
            ];
            const poly = new google.maps.Polyline({
              path, map: mgMap,
              strokeColor: color, strokeWeight: 2, strokeOpacity: 0.6,
              icons: [{ icon: { path: 'M 0,-1 0,1', strokeOpacity: 1, scale: 3 }, offset: '0', repeat: '15px' }]
            });
            mgPolylines.push(poly);
          }
          resolve();
        });
      });
    }
  }

  if (hasPoints) {
    mgMap.fitBounds(bounds, { padding: 40 });
  }

  // Add chegada time to legend
  if (legend.innerHTML) {
    legend.innerHTML = `<span style="color:var(--muted);margin-right:8px">Chegada: <strong style="color:var(--text)">${chegada}</strong></span>` + legend.innerHTML;
    legend.innerHTML += `<span style="color:var(--muted);margin-left:auto;font-size:11px">Garagem &nbsp; Empresa</span>`;
  } else {
    legend.innerHTML = '<span style="color:var(--muted)">Nenhuma linha selecionada para este turno</span>';
  }
}




// ---- ROTAS EXTRAS ----
let rePassSelecionados = []; // {nome, lat, lng, horario, telefone, bairro, cidade, embarque}

function openRotasExtras() {
  // Set default date to today
  document.getElementById('reData').value = hojeLocal();
  rePassSelecionados = [];
  document.getElementById('reBusca').value = '';
  document.getElementById('reResultados').innerHTML = '';
  renderReSelecionados();
  renderRotasExtrasList();
  document.getElementById('modalRotasExtras').classList.add('open');
}

function filtrarPassRotaExtra() {
  const q = document.getElementById('reBusca').value.toLowerCase().trim();
  const div = document.getElementById('reResultados');
  if (!q) { div.innerHTML = ''; return; }
  // Search all active passengers across all routes
  const results = [];
  DATA.forEach(rota => {
    rota.passageiros.filter(p => p.status === 'ativo').forEach(p => {
      const match = p.nome.toLowerCase().includes(q) ||
        (p.bairro||'').toLowerCase().includes(q) ||
        (p.cidade||'').toLowerCase().includes(q) ||
        (p.embarque||'').toLowerCase().includes(q);
      if (match) results.push({...p, _rota: `L${rota.linha} ${rota.turno}`});
    });
  });
  if (results.length === 0) {
    div.innerHTML = '<div style="padding:12px;color:var(--muted);font-size:13px">Nenhum resultado</div>';
    return;
  }
  div.innerHTML = results.slice(0,20).map(p => {
    const already = rePassSelecionados.some(s => s.nome === p.nome);
    return `<div style="display:flex;align-items:center;gap:10px;padding:8px 12px;border-bottom:1px solid var(--border);cursor:pointer;${already?'opacity:0.4;pointer-events:none':''}" onclick="toggleRePass(${JSON.stringify(p).replace(/"/g,'&quot;')})">
      <div style="flex:1">
        <div style="font-weight:600;font-size:13px">${p.nome}</div>
        <div style="font-size:11px;color:var(--muted)">${p._rota} · ${p.bairro||''} · ${p.cidade||''}</div>
      </div>
      <div style="font-size:18px">${already ? '' : ''}</div>
    </div>`;
  }).join('');
}

function toggleRePass(p) {
  const idx = rePassSelecionados.findIndex(s => s.nome === p.nome);
  if (idx === -1) rePassSelecionados.push(p);
  else rePassSelecionados.splice(idx, 1);
  renderReSelecionados();
  filtrarPassRotaExtra(); // refresh list
}

function renderReSelecionados() {
  const div = document.getElementById('reSelecionados');
  if (rePassSelecionados.length === 0) {
    div.innerHTML = '<span style="font-size:12px;color:var(--muted)">Nenhum selecionado ainda</span>';
    return;
  }
  div.innerHTML = rePassSelecionados.map(p =>
    `<span style="background:rgba(236,72,153,0.15);border:1px solid rgba(236,72,153,0.3);color:#ec4899;border-radius:20px;padding:3px 10px;font-size:12px;cursor:pointer" onclick="toggleRePass(${JSON.stringify(p).replace(/"/g,'&quot;')})">
      ${p.nome.split(' ')[0]} ×
    </span>`
  ).join('');
}

function criarRotaExtra() {
  const nome = document.getElementById('reNome').value.trim();
  const data = document.getElementById('reData').value;
  if (!nome) { alert('Digite o nome da rota.'); return; }
  if (rePassSelecionados.length === 0) { alert('Selecione ao menos um passageiro.'); return; }
  const novaRota = {
    id: 'extra-' + Date.now(),
    nome, data,
    motorista: '',
    horario: '',
    garagem: true,   // início na garagem
    empresa: true,   // destino final na empresa
    passageiros: rePassSelecionados.map(p => ({...p})),
    criadoEm: new Date().toISOString()
  };
  ROTAS_EXTRAS.push(novaRota);
  saveAfterChange();
  // Reset form
  document.getElementById('reNome').value = '';
  document.getElementById('reData').value = '';
  rePassSelecionados = [];
  document.getElementById('reBusca').value = '';
  document.getElementById('reResultados').innerHTML = '';
  renderReSelecionados();
  renderRotasExtrasList();
  alert(`Rota Extra "${nome}" criada com ${novaRota.passageiros.length} passageiro(s)!\nVisualize no mapa para definir a ordem de embarque.`);
}

function renderRotasExtrasList() {
  const div = document.getElementById('rotasExtrasList');
  if (ROTAS_EXTRAS.length === 0) {
    div.innerHTML = '<div style="text-align:center;padding:16px;color:var(--muted);font-size:13px">Nenhuma rota extra ativa</div>';
    return;
  }
  div.innerHTML = ROTAS_EXTRAS.map((r, i) => `
    <div style="background:var(--surface);border:1px solid rgba(236,72,153,0.3);border-radius:12px;padding:14px;margin-bottom:10px">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">
        <div>
          <span style="font-weight:700;color:#ec4899">${r.nome}</span>
          <span style="font-size:12px;color:var(--muted);margin-left:8px">${r.data} · ${r.horario||'--:--'}</span>
        </div>
        <div style="display:flex;gap:6px">
          <button onclick="verRotaExtraNoMapa(${i})" class="export-btn" style="padding:4px 10px;font-size:11px">Ver no Mapa</button>
          <button onclick="excluirRotaExtra(${i})" class="export-btn" style="padding:4px 10px;font-size:11px;color:var(--red);border-color:var(--red)">Excluir</button>
        </div>
      </div>
      <div style="font-size:12px;color:var(--muted)">Garagem → Passageiros → Empresa &nbsp;·&nbsp; ${r.passageiros.length} passageiro(s) ${r.data ? '· ' + r.data : ''}</div>
      <div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:8px">
        ${r.passageiros.map(p => `<span style="background:var(--surface2);border:1px solid var(--border);border-radius:4px;padding:2px 8px;font-size:11px">${p.nome.split(' ').slice(0,2).join(' ')}</span>`).join('')}
      </div>
    </div>
  `).join('');
}

function excluirRotaExtra(idx) {
  const r = ROTAS_EXTRAS[idx];
  if (!confirm(`Excluir a rota extra "${r.nome}"?\nEsta ação não pode ser desfeita.`)) return;
  ROTAS_EXTRAS.splice(idx, 1);
  saveAfterChange();
  renderRotasExtrasList();
}

function verRotaExtraNoMapa(idx) {
  document.getElementById('modalRotasExtras').classList.remove('open');
  // Open mapa geral showing this extra route
  openMapaGeral(idx);
}

