function seAba(aba) {
  ['Lancar','Historico','Solicitacoes','Cadastro','Relatorio'].forEach(a => {
    const el = document.getElementById('seAba' + a);
    if (!el) return;
    const visivel = a.toLowerCase() === aba;
    el.style.display = visivel ? 'block' : 'none';
    el.style.flex = visivel ? '1' : '';
    el.style.overflowY = visivel ? 'auto' : '';
  });
  const tabs = {lancar:'seTab1', historico:'seTab2', solicitacoes:'seTab4', cadastro:'seTab5', relatorio:'seTab3'};
  Object.entries(tabs).forEach(([a, id]) => {
    const btn = document.getElementById(id);
    if (!btn) return;
    btn.style.background = a === aba ? 'var(--accent)' : 'transparent';
    btn.style.color = a === aba ? '#000' : 'var(--muted)';
  });
  if (aba === 'historico') seRenderHistorico();
  if (aba === 'relatorio') seRenderResumoRelatorio();
  if (aba === 'solicitacoes') solCarregarErender();
  if (aba === 'cadastro') cadGestorCarregar();
}

